/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20050606-9","meetingId":"h17-cm06","date":"2005年6月6日","dateIso":"2005-06-06","committee":"文教委員会","time":"午後１時０４分～午後３時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員の紹介","agenda":"幹部職員の紹介","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"日本共産党の沢田です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"プラン２１を、平成１２年度から始めて、５年になりますけれども、これから手をつけていく問題、既に実施されている問題、いろいろあるわけですけれども、現時点で、プラン２１に取り組んで、どういう成果というか、あるいは評価に至っているのか。できれば、具体的、客観的な資料みたいなものがあれば、教えていただければありがたいと思います。","respondent":"中島指導課長","answer":"プラン２１の客観的な資料をもとにした評価をですけれども、昨年１月に実施いたしました、プラン２１のフォーラムというのがあります。こちらの中で、かなりさまざまなデータをもとに、いろいろな協議を進めた状況があります。","voiceIndex":34,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"まだ、始めて５年と言えば５年ですから、性急な成果を求めるのは無理だと思うんですけれども、たしかきのうか、おととい、文部科学省が、習熟度別学習を取り入れている学校で、学力が向上したとか、不登校の率が改善されたとかというデータを出したんです。","respondent":"中島指導課長","answer":"ただ、それをこのプラン２１の、一つ一つの項目との相関で、具体的にデータをとっているわけではございませんけれども、やはり、学校が子どもたちのために、プラン２１の考え方に従って取り組んでいるさまざまな状況。","voiceIndex":36,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"でも、あまり他区だとか、他校と比較すると、本来の趣旨とは違う方向に走っちゃうから、単純には言えないんですけれども、今、学力問題がいろいろ取り沙汰されている中で、ほんとうの意味での学力がどこまでついていくのかというのは、私は、大変関心が高いところですので、何かの折に、弊害を避けながら、わかるようなものがあれば、ぜひ教えていただきたいというのが１点です。","respondent":"市川庶務課長","answer":"平成１５年度、１６年度と耐震診断の結果が出てまいりました。今、現に平成１７年度を行ってございまして、基本的には、優先度の高い工事から実施をしていくということで、最終的に計画を組んでいきたいと考えています。","voiceIndex":38,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"平成１７年度に耐震診断をやって、その結果で、今後どうするかを最終的に決定したいということですから、まさに耐震診断に乗せたというところなんじゃないかと思うんです。さっきの説明ですと、平成９年度から１４年度まで、補強工事が必要な半数と言ったのは、耐震診断の半数が終わったと言ったのか、ちょっとそこら辺を聞き逃したので。","respondent":"市川庶務課長","answer":"前回の文教委員会でも申し上げましたけれども、やはり何回かに分けて、２年、ないし３年と分けて、ある同じ学校の棟別、あるいは体育館は別にという形で工事をしていきませんと、教育活動に支障が生じますので、そういったことも含めて。","voiceIndex":40,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"そうすると、今年度の耐震診断は、診断としては最後の年になるわけですよね。それを見ないとわからないということはわかるんですが、おおよそ何年ぐらいをめどに、最終的にここまでには終わるんだということがわかったら、ちょっと。ずれ込んでも構わないんで、そのこと。それから、学校改築の問題との兼ね合いで、それはどうやったらいいのかということを、あわせてお願いします。","respondent":"市川庶務課長","answer":"ただし、先ほど申し上げましたが、今年度の耐震診断の結果が出て、最終的に調整する。その調整の中には、委員から最後のご質問をいただいた、校舎改築の問題も含めての調整ということで考えております。","voiceIndex":42,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか確認をさせていただきたいんですが、幼保一元という形で幼稚園業務がこちらのほうに回ったということなんですが、今回、文教委員会は、実際にどういうところが係わってくるんでしょうか。それから、これはお願いなんですが、研究校になって、研究発表をされると思うんですが、去年も、幾つか研究発表をされていて、事前に予定を入れていただきたいと思います。その３点を、お願いします。","respondent":"市川庶務課長","answer":"先ほど、教育次長のほうから申し上げましたけれども、基本的には、委員会の審議事項については、委員会のほうでご決定いただくのが筋だということを前提にして説明しますけれども、私ども理事者といたしましては、今回、幼保一元の教育委員会の事務事業の補助執行ということで。","voiceIndex":44,"id":"exchange-007"},{"speaker":"松澤委員","kind":"意見","question":"これから、学校そのものが改築し、また学校の中で避難場所としてのいろいろな設備をしていく中で、消防団の団小屋があるというのは、私はプラスだと思っているんですけれども、何で出て行ってくれという話になっているのか、その辺の考え方をお聞かせ願います。","respondent":"市川庶務課長","answer":"経緯から説明しますと、今、ちょうど小山小学校の敷地の一角、四隅のうちの一つのところに消防団、行政財産の使用許可ということで土地が３０m2ちょっとあります。そこのうち、十七、八m2ぐらいの広さだと思いますが、消防団のほうで格納庫のような施設をつくられています。","voiceIndex":49,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"話は大体わかりましたけれども、計画を見ると、セットバックしてもできると思うんですね、グランドなんかにかからないですから。そういう意味では、やはり、共存していく方向というのが望ましいんじゃないですかね。セットバックするから、費用は品川区で持ちなさいという話ではないんですね。だから、防災課とも話し合いをしながら、検討していっていただきたいと思います。","respondent":"市川庶務課長","answer":"ご指摘いただいた内容を含めて、関係部署と綿密な連携を取りながら、調整をします。","voiceIndex":51,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"この平成１４、１５、１６年度でいいですから、わかっていたら教えていただきたいというのが１点。そういう中でも、登録が増えている学校が、３１校中３分１ぐらい、大ざっぱに見て１０校ぐらいあるんですけれども、全体的に落ちているというので、微増のところが何カ所なんですけれども、その辺、どういう状況なのかということを伺っておきたいと思います。","respondent":"中島指導課長、谷田部学務課長、市川庶務課長","answer":"一昨年度は４名、その前の年がやはり７名という形で、そのほかの部分を見ますと、大体、このような形で推移している状況です。最初の給食の関係ですけれども、まだ平成１６年度の未納状況が整理されていませんので、平成１５年度でご説明申し上げます。それに対して、右側のは、平成１７年度４月末ということで、今年度が始まって１カ月経った時点の登録率で、ある意味で。","voiceIndex":53,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"給食のほうは、年々、状況は同じような状況で推移しているという話なんですが、０.１８％という数字が、零コンマですからすごく少ないんですけれども、小学校と中学校の実数として、どういうふうになっているのかを、ちょっとそこを教えてください。それから、非常勤職員のところで、７人、４人、７人というのは、数字的にはわかりました。そこを、ちょっと教えていただきたいんですけれども。","respondent":"中島指導課長","answer":"そういう形で発生した件数を、すべてこちらに記載しておりますので、これがそのまま人数ではないということを、まずご確認いただきたいと思います。実際に、小学校で何人、中学校で何人かという資料は、ちょっと今、手元にございませんで、説明できなくて申しわけございません。","voiceIndex":57,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"今の関係でもう１回。実数的に、やっぱり、そんなにいないというふうに考えていいんでしょうか。７件というと、多いととらえていいのかどうか。１人の先生に対して７件なのか、人が、例えば何カ月単位で採用して、あるいは、復職したけれども、まただめになっちゃってという形なのか、どうか、その実態がわからないから、そこを知りたくて伺ったので、そこもちょっと教えてください。","respondent":"中島指導課長、谷田部学務課長、市川庶務課長","answer":"過程の状況ですと、いろいろな状況で病気になるケースがあります。私どもも、十分教員のほうには配慮していかなきゃならないと考えています。小・中学校平均して０.１８％ということで、１カ月でも滞納すれば１人というふうにカウントしますので。ご案内のように、低学年、中学年、高学年と上に行くに従って、登録率が少なくなってまいりますので、全体の傾向から、この数字をどう評価するかは。","voiceIndex":59,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"補強してあるならあるで、わかっていてほしいし、していないなら、していないで、そういう理解でもいいかと思うんですけれども、自分たちが避難所として使う学校が、今どういう状況なのかという、そういう地域との連絡、連携みたいなものというのは、多分おありになると思うんですけれども、ちょっと確認をさせていただきたいと思います。","respondent":"市川庶務課長","answer":"診断の結果、ほんとうに心配な施設でしたら、これは一日の教育活動すらも、施設として供するわけにまいりませんので、そういうところで、地域の皆さんとも、学校という施設について、いざというときの施設として信頼するに足る施設かどうかという評価については。","voiceIndex":63,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"理解をしていいのか、どうかちょっとわからなくなったんですが、もう１回、最初のほうの、５８校のうち、ちょっと後段のほうにひっかかるかもしれませんけれども、耐震改修をやりました、現在の耐震基準でオーケーですよというのは、５８校中何校で、こことここは外れているんですよという言い方は、今はできないととらえてよろしいんでしょうか。ちょっと話がこんがらがっちゃっていますが。","respondent":"市川庶務課長","answer":"ただ、逆に言えば、今、私どもが予定している平成２０年度までの４カ年の工事の中ですべて対応できるとすれば、平成２０年度の時点では、一応、耐震補強の必要のある学校については、すべて対応いたしましたということが言えるように、計画を、今進めているです。","voiceIndex":65,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"もう一つ、簡単に。１学年、１クラス６人とかというふうになるわけですよね、そうだと思うので、こんなに少ない数字になるのは、どういう評価をしたらいいのかというのをお聞きしたい。","respondent":"中島指導課長","answer":"この６名なり、８名という状況は、学校の中で、そういった集団の中に学べる、生活できるような機会を工夫、検討していかなければならないと考えているところです。","voiceIndex":67,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"要するに、こういうふうに落差が出た学校経営といいますか、学校間の競争というふうに、たしかご説明の中であったと思うんです。人数が少ないところの学校経営に対しては、教育委員会として、何かまた適切なアドバイス等があるのかというふうに思ってお聞きしました。もしアドバイス、また工夫等が、学校経営者に対して、こうやって頑張ろうねというところがありましたら、ぜひお聞かせ願いたいと思います。","respondent":"中島指導課長","answer":"特に、この入学者数が極端に落ち込んでしまったという学校につきましては、やはり、私ども教育委員会としても大きな支援をしていかなくてはならないと考えますし、ほかにもいろいろな形で支援する学校を、今年度は重点的に８校ほど、重点支援校という形で位置づけまして。","voiceIndex":69,"id":"exchange-016"}]},{"id":"topic-03","title":"大崎地区小中一貫校の愛称","agenda":"大崎地区小中一貫校の愛称","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"近隣セキュリティに関連して、まずはじめに、不審者が非常に多くなったということで、新聞のほうにも出ていたんですが、現在、どういう対応をとられているのか。その状況を、まず確認をさせていただきたいと思います。","respondent":"中島指導課長","answer":"不審者に関しましては、庶務課長の後に、私のほうから口頭によりましてご報告差し上げる予定でございました。一昨日、土曜日等の新聞で、品川区のほうで不審者が出てきたという状況が報道されてあります。６月２日から３日に５件あったということで、新聞等に報道されております。","voiceIndex":80,"id":"exchange-017"},{"speaker":"西本委員","kind":"確認","question":"不審者が多くなったな、危険にさらされているなということがありまして、そういう意味から見ると、近隣セキュリティシステムというのが、いいタイミングで、まさに試行もやり始めるというところだと思うんです。一つ確認したいのが、所管が違うのかもしれませんが、地域の協力者とか、マザーフォンの設置、そこら辺の現状はどうなっているのかということで、今後の動きが少しわかりますか、いかがでしょうか。","respondent":"市川庶務課長","answer":"今のご質問にありましたマザーフォンというものの設置については、アンテナを保管するものとして、また、技術的な検討をあわせて行っているわけですが、区民生活事業部のほうで、どこの地点に、どういうふうに設置をしていったら効果的なのかということで、今、最終的な。","voiceIndex":82,"id":"exchange-018"},{"speaker":"西本委員","kind":"提案","question":"実は、これは当委員会への提案でもあるんですが、もちろん、委員一人ひとりが地域に帰られて、自分から率先して協力者になるという形で、それぞれご活躍をされていると思うんですが、やはり区議会という形で、文教委員会だけではなくて、ほかの委員会のほうにも声をかけていただいて、何かしら、協力者になるとか、マザーフォンの設置はやはりたくさんあるほうがいいわけですから、そういう形を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-019"},{"speaker":"山村委員","kind":"意見","question":"同じことを、この前、区民委員会で私も言った覚えがあるんです。そうすると、役所の方で品川区に住んでいる方も入るとか、入らないとかということを考えなきゃいけないというようなことを言われまして、区民委員会では、そういうことにはしませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"基本的に、何ｍ以内にするとかということではないんですか。そういう意味では、品川区商店街連合会に行ったら、品川区商店街連合会の方たちが、商店街でみんな加入しようとか、それはいいことだなと思っているんですけれどね。私たち、地元にいない、動いている方がなっても、それはどうですかね。ほんとうに役立つかどうかというのは、どうでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-021"},{"speaker":"南委員","kind":"提案","question":"私も、やっぱりそういう区民の安全な暮らしを守りたいという立場は、共通してあると思うんですよ。そういうための質疑もしているし、よくするようにという努力を、みんなでしているわけです。事区議会でやりましょうという提案に対しては、私は、そういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-022"},{"speaker":"西本委員","kind":"提案","question":"実際のところ。ただ、別に携帯だけではなくて、マザーフォンの設置なんかもあるわけですから、そういうものを、意識を持って、品川区議会という形で協力できる方はいかがでしょうかという程度でよろしいんじゃないかなと思うんです。もちろん、皆さん、やっておられると思うんですけれども、１回、議長のほうに提案をしていただいて、そういう形でということだけでもいいんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-023"},{"speaker":"大沢副委員長","kind":"提案","question":"議長に提案をして、議長に諮るということは、これは非常に重いことだと思いますので、あくまでも区議会議員の方たちの自主的な、自由な発想に基づいた危機管理というものに基づくものであれば、議長というよりも、先ほど、南委員がおっしゃったように、たがをはめるではなくて、いかに我々の意識を高めるかという啓蒙活動をもうちょっとしたほうがいいのであって、前段のことが大事であって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"当然、ここに至るまで、私も近隣セキュリティシステムに参加をするか、しないか、今、まさに、特に直接な問いかけはないですけれども、どうしようかなというのは、当然、地域で考えていますし、そこから発しないと、何か議長からとかということになると、本来の、地域の力でというものとは、何か議会の姿として違うものを示してしまうような気がしますので、そういう趣旨で、ご理解をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-025"},{"speaker":"松澤委員","kind":"意見","question":"近隣セキュリティシステムというのは、とんちんかんなことを言ったら、ごめんなさい。何人か協力員がいるわけですよね、一人の特定な子どもにですよね。それは、協力員の一人として、欠だと思うんです。ただ、ＰＲするというのは、それは当然のことですけれども、個人としては、近隣セキュリティシステムの協力員になって、活動できるかというと、私はなかなかできないと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-026"},{"speaker":"沢田委員","kind":"意見","question":"私も、それは各議員の自主性に任せるべきだと思います。議員は、そういう形で、例えば消防団だったら、区民消火隊だとか、いろいろな組織があるのに、それに熱心かどうかって、みんな入ることになったら、議員本来の仕事ができなくなってしまう。もちろん関心のある人は参加すればいいんだけれども、ある程度距離を置いて、その問題をきちっと見ていく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-027"},{"speaker":"西本委員","kind":"提案","question":"私の説明がうまくいかなくて、申しわけないです。そういう縛りをつけるとかではないんです。議長のほうに提案をして、そうすると大きなことになってしまうということであれば、もちろん違う方法があるかと思いますので、皆さんがそういうお考えで、区議会という形では縛りがありすぎるということであるならば、それは別な方法をちょっと考えたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-028"},{"speaker":"三上委員長","kind":"質問","question":"委員長として、この問題について、皆さんにご意見を伺いまして、これを文教委員会の意見という形で取りまとめるということでは、ちょっとできないと思います。発言のあったご意見の中から、少々、私が感じた点については、仕組みそのものがまだ完全にご理解していただけていないという部分もあるのかなという状況に、私も感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-029"},{"speaker":"三上委員長","kind":"提案","question":"ないようですので、今後の委員会運営について、私のほうから提案させていただきたいと思います。そういったことにつきまして、委員の皆様のほうから、文教委員会に係わる所管事項で、調査したいテーマがございましたら出していただき、委員会日程等を考慮しながら、できる限り審査・調査し、委員会の活性化を図っていきたいと考えておりますが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-030"},{"speaker":"沢田委員","kind":"意見","question":"学力を向上させるために、どういうことが必要なのか、どういうことができるのか。あるいはいろいろな試みが、品川区で言えば、一貫教育などもその試みの一つだとは思うんですけれども、議会として、その辺のところ、まだ何をどうするかというのは漠としているんですけれども、何か勉強したい、詰めてみたいなと思っています。","respondent":"三上委員長","answer":"それをまた検討させていただいて、皆さん方とお諮りさせていただきたいと思いますので、よろしくお願いしたいと思います。","voiceIndex":102,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":50918,"voices":104}},{"id":"h17-20050606-5","meetingId":"h17-cm06","date":"2005年6月6日","dateIso":"2005-06-06","committee":"総務委員会","time":"午後１時０４分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党の鈴木真澄です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高星委員","kind":"意見","question":"品川区民連合の高星です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"三村委員","kind":"質問","question":"すみません、初めてなので、基本的なことをお聞きするかもしれないんですけど、ちょっと今の公金の支払いや何かでは、カード決済や何かはされていないんですけれども、今後カードでの税金の取扱いは一部始められてくるような話を聞いたんですけれども、品川区管内においてはそういった取扱いは今後どのように考えられているんでしょうか。","respondent":"小野情報システム課長","answer":"品川区におきましては、電子区役所ということで、大きな計画の中ではこういう新しい決済を含めたやり方というものも視野には入れてありますけれども、まだきちっとしたシステム等についても確立をされているという状況ではございませんので。","voiceIndex":52,"id":"exchange-003"},{"speaker":"三村委員","kind":"質問","question":"今、チェンジ、システム的に振り替えはされているんですけれども、その中で対応ができるように、視野には入っていて、対応はできるようになる。実際にされるかどうか、実際にそういう公金のマルチペイメントという形で入ってきたときに、今のシステムでも対応ができるように想定はしてあるんですか。","respondent":"小野情報システム課長","answer":"いろいろな手続の電子化というふうなことで、新しいマルチペイメントのシステムが確立された時点で、そういうものを取り込めるような形での全体の整備というものは進めております。","voiceIndex":54,"id":"exchange-004"},{"speaker":"高星委員","kind":"質問・要望","question":"その下のほうの行政評価云々のこちらは主査制なんですよ。こういうのは僕ら自身もわからない。だれかがやっぱり、これは何とかしようという気持ちにならないといかにもわからないと思うんだけど、このままでいいと思っていらっしゃるのか、何とかしなきゃならないなと思っているのか、何とかするんでしたら、目鼻がつくことを考えられるのかどうなのか、その辺のところをちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"先ほど広報広聴課長のほうからイメージアップの中で区民の皆さんにわかりやすい区役所を目指すと、そういう運動をこれからも続けていくということでご説明させていただきましたけれども、基本としては常にそういう姿勢で臨んでいきたいと、このように考えておりますので。","voiceIndex":56,"id":"exchange-005"},{"speaker":"高星委員","kind":"質問","question":"まだわからない。仕事としてはこっちのほうがやりやすいわけなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-006"},{"speaker":"高星委員","kind":"意見","question":"内部事情はわかっている。仕事としてやりやすいのかどうなのか。ただ、全部説明してくれといったって、それは無理かもしれないけど、このほうがやりやすいのかどうか、その辺のところをもう一度聞かせてください。","respondent":"本間総務部長","answer":"一番わかりやすいのは、一般的に日本の社会では参事は部長級ですので何々部長、それから副参事は何々課長ということで、全部表示すれば非常にシンプルなわかりやすい組織になるとは思うんですが、その中で、やはりいろいろな行政を進める中で、例えば何々係長といいましても。","voiceIndex":60,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点お聞きしたいんですが、６ページ、企画部の中の財政担当、(6)の財政状況の公表の部分でちょっと確認をさせていただきたかったんですが、現在、企業会計手法によるバランスシート・行政コスト計算書と出ていますが、東京都なんかだと、公会計のほうも大分進める、それから複式簿記というのも出ておりましたが、品川区として何かその辺を検討なさっているのかどうか。","respondent":"日下部企画財政課長","answer":"私ども区のほうとしましても、いろいろバランスシートの導入であるとか、そういった経過の中でいろんな検討は進めてきておりますけれども、ただ、現在の時点ではこのバランスシートであるとか、行政コスト計算書については、総務省のほうが国を挙げて一つの基準を示した。","voiceIndex":65,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"複式簿記などはどこまでいいのかなというのも、区役所の中ではちょっとという思いもあるんですけど、やはりわかりやすくするという意味では検討されたかなというのが１点と、あと前に別の委員会でもお聞きしたことがあるんですけど、減価償却というものが役所には入っていないですよね。","respondent":"日下部企画財政課長","answer":"ただ、この間のそういうバランスシートであるとか、行政コスト計算書であるとか、そういう実績を着実に積み重ねてきておりますので、そういう成果の上に立って、今ご指摘の点についても具体的に検討を進めていきたいと、このように考えております。","voiceIndex":67,"id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"１点だけちょっと考え方を教えてほしいんですが、広報広聴課のところなんですけれども、これからおそらく品川区のいろんなものについて発信をしていく上で、広報広聴の役割というのは非常に高くなってくるというふうに思っているんですが、今回の場合、特にパブリシティをどう使っていくかというのは非常に大きな課題だろうと思うんです。","respondent":"中川原広報広聴課長","answer":"昨日の件かと思うんですけれども、昨日防犯ブザーが機能したよということで記者には説明をしたんですけれども、どうしてもやはり載せるほうの観点を見ますので、ああいう形で出たというのは、ある意味で新聞社というのは独立したメディアですから。","voiceIndex":69,"id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"確かに恐れずにやっていっていただきたいんですが、こちらの意図するところが真実として伝わらないで、ああいう媒体の場合は向こうのペースで載せられるとか、趣旨が変わってしまうという部分も十分今後の中で考えられていかれないと、パブリシティの使い方というのは非常に怖いんではないかなというふうに思っています。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"１点伺いたいんですけど、情報公開等はかなり進んできているんだなというふうには思うんですけども、外郭団体等の情報公開というのは、どういうふうになってきているかなというふうに思うんですけど、その辺の考え方、例えば審議会を公開しているところだとか、まだのところというのがあると思うんですけど、ちょっとそこら辺の考え方と。","respondent":"中川原広報広聴課長","answer":"外郭団体につきましては、独自の規定をすべて五つのところでつくっております。そこについては、それぞれ独自の組織に合わせた運用がなされているというふうに考えてあります。","voiceIndex":72,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"それぞれの団体でやっているというのは知っているんですけど、区のほうとの関係で、どういうふうに考えるのかというのが見えないんですけど。","respondent":"中川原広報広聴課長","answer":"審議会につきましては、私ども区が審議会を持っているのは、行政不服審査法に基づきまして、不服申し立てがあった場合、対応として審議会を持っておりますので、それは外郭団体とはまた違った意味があると思いますので、情報公開のそういった状況の公開については。","voiceIndex":74,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"要するに私が聞きたいのは、それぞれの団体がそういうことで言ってくれれば、それは当然区のほうの対応というのは迫られると思うんですよ。だけど、区のほうとして積極的にそういう団体、あえてこの区の仕事、いろいろお願いしているわけですから、そういう団体の情報を区の側からもっと公開しろとか、そういうことを働きかけるということはないのかどうなのかということを聞いているんですけど。","respondent":"濱野助役","answer":"重要な情報、つまり経営状況等に関する情報は当然のことながら区議会の第３回定例会だったと思いますが、そこに向けてすべての経営資料についての情報は議会へ報告されているです。","voiceIndex":76,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"やっぱり、区のほうからいろいろお願いして、資金的な面もありますけども、そうであれば、やっぱりやっている内容だとか財政状況だとかを含めてしっかり公開させるというのが、区のほうからも対応すべきじゃないかなというふうに思うんですが。","respondent":"濱野助役","answer":"今日は事務事業概要の場所でありますので、そういうご意見ということで承ります。","voiceIndex":78,"id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"区で出す書類ですから、お知らせ文書、これはやはり庁内としてもっと優しい表現で皆さんにお伝えをしていくと。我々、やはり役所の中にいますと、例えば規定とか申請とかわかるわけですが、やっぱりどういうふうにやるんですかと聞かれることも中にはありますね。そういう面で、一つこれは要望になるわけですが、ぜひそういう感覚で文書を作成していくというふうな形でお願いしたい。感想があれば。","respondent":"中川原広報広聴課長","answer":"イメージアップ運動でも、自分たちの職場の当たり前を見直して、それぞれの事業部ごとに取り組みましょうというのは、まさにそういう声を受けてのことだというふうに考えておりますので、さらに頑張って取り組みます。","voiceIndex":80,"id":"exchange-016"},{"speaker":"三村委員","kind":"質問","question":"１３ページとか１５ページの工事などの契約と実際の予算の数字と、実際の工事の落札率というんですか、そういった金額というのは大体どういう割合というか、その辺のことを教えていただければと思います。","respondent":"鷹倉経理課長","answer":"正確な数字は今手元に持ってございませんが、工事関係ということのお話ですが、品川区の場合、予定価格という形で公表していますが、電気を除く工事関係は概ね９５％ぐらい、電気については９５％を割り込むような形が最近の傾向かなと考えています。","voiceIndex":95,"id":"exchange-017"},{"speaker":"三村委員","kind":"質問","question":"そういった情報はどこかで公開はしているんですか。","respondent":"鷹倉経理課長","answer":"今申し上げましたとおり、予定価格については公表ということで、手を挙げられるときに公告しています。","voiceIndex":97,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"人権啓発のところでちょっとお伺いしたいんですけども、人権啓発課のところは二つの主査制で、一つは同和担当と男女共同参画担当と二つあるんですけど、人権というと同和対策と男女共同参画という感じがするんですけど、内容を見ていると、例えば同和対策担当のところですと、どれが同和の関係かなというのが何かちょっとよくわからないんですけど、例えば憲法週間記念とか。","respondent":"武内人権啓発課長","answer":"そういう中で、「人権教育のための国連１０年」というのがありまして、それに基づいてさまざまな人権問題を今後同和問題とあわせて啓発していく、教育していくということが国のほうでも考えられておりまして、そういった中で。","voiceIndex":99,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみにちょっと伺いますけども、同和生活相談というのは、相談員、たしか何年か前に２名から１名になったと思うんですけど、ここのところ大体何件ぐらいあるんでしょうか。２名から１名になって、対応はどういうふうになっているのか、大体わかりますか。","respondent":"武内人権啓発課長","answer":"それは大きな理由としては、相談員の方が長年同じというか、非常に経験豊かな方でないとなかなかできないという部分がありまして、１名の方が高齢でちょっと体を悪くしたということでおやめになったという結果です。","voiceIndex":101,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみに、２６２件というのは、人数が２６２人、品川区だけでの人数ですか。","respondent":"武内人権啓発課長","answer":"１人の方がいろんな相談ということでお見えになりますので、そういうトータル的な相談ということで、また内容等につきましては、人権侵害の部分もかなり入ってきておりますので、個別のこの内容については具体的なご説明は控えさせていただきたいと思います。","voiceIndex":103,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"内容の点は聞いてはいないんですけれども、差別事象の処理と書いてあるんですが、かなり区内でも差別事象というのはあるんですか。よかったら、言える範囲でいいんですけど、具体的にどんな差別地所があるんですか。","respondent":"武内人権啓発課長","answer":"昨年１０月に、新聞でもたびたび報道されておりますけれども、大量差別はがき事件というのが発生しておりまして、これは２年に及びまして、品川にあります食肉市場から始まりまして、同和地区出身者に誹謗中傷をあらわす大量なはがきを送りつけるという事件が発生していまして。","voiceIndex":105,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平和国際交流の部分で簡単にお聞きします。財団法人品川区国際友好協会が主体となっているということですが、総務課のほうではどの辺までタッチしているのかというのが１点と、ちょっと見ていて、先日聞かれたのを思い出したんですが、ジュネーブは平成３年に提携して、来年１５周年になると思うんですが、ある程度計画されていらっしゃるかどうか。ちょっと区民の方から聞かれたんですが、あれば。","respondent":"宮地総務課長兼危機管理室長","answer":"今の段階ではそういうことです。確かに平成１８年は１５周年記念ということで、こちらから訪問をするという年に当たります。","voiceIndex":107,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ジュネーブの、以前たしかこちらから訪問したときに、かなり大きな訪問団で行ったということが、その方たちのイメージが残っていまして、もしまた行くなら、ある程度費用がかかりますので早目に準備をしていきたいということの中で聞かれたんです。そういう意味で、早く決まれば、またいろんな面で広報していただきたいなと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-024"},{"speaker":"中島副委員長","kind":"質問","question":"単純な質問なんだろうなと思うんですが、４ページの5)の特別職報酬等審議会というのがあるんですが、この特別職というのは何ですか。","respondent":"宮地総務課長兼危機管理室長","answer":"区長、助役、収入役をはじめ、それから議長、議員です。区議会議員の皆さんも入っております。この方々の報酬等につきまして、審議会をつくって審議をしているものです。","voiceIndex":110,"id":"exchange-025"},{"speaker":"中島副委員長","kind":"質問","question":"審議会の審議委員の方というのは、どういう方でしょうか。","respondent":"宮地総務課長兼危機管理室長","answer":"１５名の方で構成されているわけですけれども、地域の代表の方、あるいは学識経験者、産業部門だったり、それから医療関係、そういったところの皆さんで構成されております。","voiceIndex":112,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問","question":"すごく単純なんですが、１２ページの、ちょっと教えてください。私も初めて見た。自動車の運行管理のところをずっと見てみますと、送迎用、運搬用というのうはわかるんですが、貸出用として車と自転車、電動バイク、この貸出はだれに貸し出すんでしょうか。その辺、ちょっとお伺いしたいと思います。","respondent":"鷹倉経理課長","answer":"車につきましては、平成１４年だったと思いますけども、それまでは各所管課で保管してございました。それを経理課で集中管理をするということになりまして、その関係で職員のほうに貸し出すという関係になってあります。","voiceIndex":114,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問","question":"先ほどお願いしたんですけれども、貸出用となると、区民に対する貸し出しと勘違いしますよね。だから、職員に対する貸し出しなのか、何か書いていないと、この辺なんですよ、ちょっとね。先ほども言いましたけれども、やっぱりわかりやすい表現をしてください。そこはわかりました。車の運転手なんですが、運転手の身分というのは全体を含めて、送迎用も含めて身分はどのようになっているんでしょうか。","respondent":"鷹倉経理課長","answer":"正規職員がやっているわけですが、退職補充という形で、ここのところ来ておりますので、今で言いますと、再任用、それから嘱託という形の方もいらっしゃる。だんだん正規職員が少なくなってきているというふうに言えます。","voiceIndex":116,"id":"exchange-028"},{"speaker":"藤田委員","kind":"意見","question":"企業ではまるごと業者に委託しているというような、区はちょっとそういう意味では違う、細かな動きがあるので、なかなかうまくいかないかどうかわかりませんが、将来的にはそういうことを考える必要性があるのではないかと思いますが、何かお考えがあれば。","respondent":"鷹倉経理課長","answer":"確かに今申し上げたとおり、正規職員がだんだん少なくなっているということ、それから時間もある程度見えるですので、その辺のところを具体的に検討していきたいなと考えております。","voiceIndex":118,"id":"exchange-029"},{"speaker":"高星委員","kind":"質問","question":"審査予定表の残りが、３のその他だけになっているんで、ちょっとお聞きしたいんですけど、先ほどちょっと出ましたけど、人権の啓発のところに書いてある同和の関係なんですが、この問題については、早くからこの問題の解決は行政がするんだということが位置づけられて、品川区もかなり早くからこの問題に積極的に取り組んできたというふうに思っているんですが、長年区が取り組みをされていて、成果。","respondent":"武内人権啓発課長","answer":"委員言われるとおり非常にこの課題は行政の責務であり、国民的課題だということで、ご存じのとおり同和対策審議会答申は昭和４０年から出ておりまして、この間３０年来の特別措置法で環境改善等は一定の成果が上げられたということで法期限を迎えたわけですけど、ただし。","voiceIndex":120,"id":"exchange-030"},{"speaker":"高星委員","kind":"質問","question":"その犯人がつかまったという話なんですけれども、これはどういう、言葉は悪いですけれども、大くくりで言ったら、どういう考えの持ち主の方なのか、単純な愉快犯じゃないけれども、そういったこれにちょっと乗っかってやってみようというふうな単純の意味のあれだったのか、あるいは悪質な目的意識を持った方がやられたのか、その辺をわかる限りで結構ですから。","respondent":"武内人権啓発課長","answer":"犯人につきましては、新聞報道されている部分でお答えさせていただきたいと思うんですけれども、犯人が言っていることは、私は今大学を卒業したんですけれども、仕事が、定職がない、ムカムカしていた。","voiceIndex":122,"id":"exchange-031"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば大崎駅を取り巻く広範なエリアにいわゆる住所のない地域もかなりあったというようなことは昔から言われている話ですよね。それについて、今どんどん解決されてきた部分は少なくはないというふうに思いますけれど、そういうことも含めて、これからも人権、とりわけ同和の関係についてもさらに一層力を入れていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それからもう一点は、最近よく新聞紙上にも出ていますが、契約の問題がかなりいろんなところで疑われています。先ほど質問の中でも落札率が出たと思いますけど、その辺、どういうふうにこの委員会でやっていくかというのをちょっと、やり方はあまりよくわからないんですが。この辺、自分としては調べてみたいという思いがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-033"},{"speaker":"三村委員","kind":"提案","question":"私もやっぱり先ほど言ったみたいな落札率、突き合わせればわかるというようなお答えをいただいたんですけれども、そうではなくて、やっぱり答えをきちんと、向こうにしてもらうんじゃなくて、こっちできちんと処理をしてわかりやすく出すとか、そういったやり方が必要なんじゃないかなと思うので、その辺のところをやっていただきたいことと、あと、先ほど情報化推進ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-034"},{"speaker":"原委員","kind":"意見","question":"区民サービスの電子化という中に、先ほど説明があったんですが、この１０月から電子入札の具体的な形ができると思うんですが、そのところで多少私たちも認識を持っていたほうがいいのかなと思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-035"},{"speaker":"原委員","kind":"意見","question":"システム的なものも含めて、どういう形で実施されて、予定はされているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-036"},{"speaker":"藤田委員","kind":"意見","question":"企画部の５ページになんですが、ボランティア活動の総合調整というのが書かれていますね。今ＮＰＯ、かなり区内の中でもいろんなところで活動がされておりますけども、「ボランティア活動の共通基準づくりを行い、関係組織との具体的な連携のしくみを検討する」というふうになっていますが、非常に今社会の中でどういう形でＮＰＯを行政が支援していくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど契約の件も話が出ました。私もそこのところは関心がありまして、契約についてはインターネットの公表によって見れるんですけど、実際ちょっとその流れ、またしくみ等がどういうふうになっているのか、全体的ないわゆる透明性というのは非常に確保されておりますので、それとあわせて各区的にどうなのかというところなんかも勉強したいなというふうに考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-038"},{"speaker":"高星委員","kind":"意見","question":"この３億円をもらうという話も、逆に今度ほかの区から見たら整合性の問題とか、何でそうなっているんだろうという、やっぱり我々は概念としてそういったものをしっかりと持っておかなきゃならない、頭に置いておかなきゃならないというふうに思うので、そういったことも含めて、やっぱり身近なものとしてしっかりと見ておく必要があるんじゃないかなということで、私はぜひともお願いしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-039"},{"speaker":"藤田委員","kind":"質問","question":"私も結構だと思いました。今日の新聞でしたか、大井競馬場で結婚式の写真が出ていましたね。やはり、競馬場は競馬場で努力されているなというふうに、あれを見て感じたわけなんですが、そういう話の一たんを聞きながら８月２日ですか、それでいいんじゃないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1686#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":40410,"voices":143}},{"id":"h17-20050607-11","meetingId":"h17-cm06","date":"2005年6月7日","dateIso":"2005-06-07","committee":"自治制度特別委員会","time":"午後１時０２分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"土井委員","kind":"意見","question":"品川区民連合の土井洋一です。１年間、どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今のご説明の中に税目の一部が都税として徴収されているということのお話が都区制度改革のこれに沿った形でご説明があったことと、主要５課題のときも同じようなご発言があったんですけれども、それは法的というか、今、どうなっているんですか。というのは、市町村民税は我々の税金だと言ったのに、向こうでは都税だという言っているものの法的な位置づけはどうなっているのか。","respondent":"日下部企画財政課長","answer":"実は市町村税が都税という形で徴収されていると。これは実は地方自治法第２８２条の中で、明確にその辺が定められてあります。これは地方税法の中で市町村税の税目等が定められておりますけれども、その関連の中で明確に位置づけられているというものです。","voiceIndex":25,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"概要だけ伺いたいんですが、最初に都区検討会からの流れのご説明がありました。今週末から新たな展開ということで、検討会が開かれている。それから、それに合わせて今、後のほうで１月の財調協議会で水平調整の話をしていたけれども、これも課長会で少し議論していこうなんておっしゃっていたけど、どういう形でこの部分を討議しようとされているのか、教えていただきたいと思っています。","respondent":"日下部企画財政課長","answer":"１点目の都区検討会、課長レベルの検討会において検討する中で、５課題だけかということでありますけれども、これははっきり申し上げて、５課題一本ということになろうかと思います。","voiceIndex":31,"id":"exchange-003"},{"speaker":"石田委員","kind":"意見","question":"もう１点、「基礎的の部分」のところで、２７次だったか、２９次だったか、地方制度調査会で聞いたときに、どうするという話をしたときに、「基礎自治体」という言葉はずっとみんなこういうふうにしちゃっているんだけれども、先ほど言った地方自治法の第２８１条の部分では「基礎的な地方公共団体」としか書いていないわけで、ずっとその「的」で来たわけだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-004"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"一度基本的なところでお聞きしたいんですけれども、１つはこのパンフレットに財源配分ですか、平成１８年度に適正な配分割合で進めていく。下に幾つか反映すべき要素と書かれていますけれども、教えていただきたい。","respondent":"日下部企画財政課長","answer":"それから２点目の都区協議会、これは実はこの報告書の中では、あまり評価がされていないんですけれども、ただこれは、通常時は確かに例えば財調協議会とか都区検討会とか。","voiceIndex":35,"id":"exchange-005"},{"speaker":"石田委員","kind":"意見","question":"清掃事業に関する課題検討状況なんですが、大分助役の部分が技術系職員とか、負担の公平化が非常に難しいなとか、全体的の調整が非常にあれなんですが、この辺のものは秋口ぐらいには上がってくると思っていまして、区長会に行って、最終的には３月までにということなんでしょうが、３月まで行かなくても、今年中というのか、今年度じゃなくて、今年中ぐらいで。","respondent":"中山清掃リサイクル課長","answer":"したがって、具体的な詰めをさらに急がなければいけないということがありますけれども、その他については特に期限があらかじめ示されているということはないんですけれども、やはり全体として。","voiceIndex":41,"id":"exchange-006"},{"speaker":"石田委員","kind":"意見","question":"内部にはあまり入らないつもりで進めていますが、当分の間という問題の中で、我々はある程度一定方向が出た中で、そこで良としてしまった我々がいるわけで、あまりあれですが、今のお話の中で急ぐ部分と急がない部分があるんだという部分があるけれども、技術系職員の部分はある程度目鼻立ちをつけないと、今のお話の中で急ぐ部分と急がない部分がちょっと出てこなかったから。","respondent":"中山清掃リサイクル課長","answer":"ただ、これがいわゆる人事権にかかわるものということがありまして、所管ではどちらかというと人事か助役・区長会というラインで検討を進めている部分ですけれども、これについては遠からず方向性を出さないと、確かに間に合わないものが１つです。","voiceIndex":43,"id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"理事者の方に聞くのがここなのかどうかはわからないけれども、清掃一部事務組合という組織には議会というのが片方にもう一つあるわけでして、その議会との関連等について、どういう位置づけと理解をしているのか、またそれが今、その問題を初めとして、どのようになっているのかという部分はご報告をいただいておいた方がいいんじゃないかと思うんですが。","respondent":"中山清掃リサイクル課長","answer":"そのときはこの区長会等で加盟されたものが加盟組織から戻り、了承された段階で、これは報告了承等がありますけれども、その段階で直近の清掃一部事務組合の議会ということですから、各議長が参加されている場に報告を行うという形をとっております。","voiceIndex":45,"id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"まさしくそんなことなんだろうけれども、問題は議会の権能と執行機関の権能とのバランスがどのような形になるのかということも含めて、どう理解をされているのかということです。","respondent":"中山清掃リサイクル課長","answer":"片や、もっと清掃事業全体の運営にかかわるもの、あるいは構造にかかわるものを、この自治制度特別委員会もそうですが、各区において、今現在、どのような検討が行われているかというようなことをそれぞれご報告し、各区の意向を踏まえて、それはそれぞれ今申し上げた。","voiceIndex":47,"id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"要するに、執行するための周りの会と言っては語弊があるけれども、具体的執行に当たっては執行機関が一定程度の検討を加えて、毎日一日進んでいくということは当然あってしかるべきこと。先ほどの当分の間と決めるということは、この清掃一部事務組合の根幹にかかわる部分だと私は思うんですけれども、そういう状況の中で、今の状況はどうなっているのかというところが知りたい。","respondent":"岩崎環境清掃事業部長","answer":"区長会が取りまとめた内容は、清掃一部事務組合に絡むものにつきましては、清掃一部事務組合の議会に適切に報告なり了承なりを求めるために、ご説明していると聞いております。","voiceIndex":49,"id":"exchange-010"},{"speaker":"土井委員","kind":"確認","question":"区長会で当分の間と決めたのはわかりました。問題はそれを議長会はよしとしたと言っていいのかどうかというところの確認をしたいんです。","respondent":"岩崎環境清掃事業部長","answer":"よしとするという意味では、議案という形になろうかと思いますが、議案という形で説明することではないわけでして、政策の基本のことですので、議案以前の問題のようなところがありますので、議案として了承されたということはないと理解しております。","voiceIndex":51,"id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"まさしくその部分だと思うんです。規約に書いてあったことを変えるわけですから、本来ならば議会できちっとやるべき代物ではないかという部分があるわけです。最高議決機関だと思うんですよ。そうでないとしたら、そうでないと言っていただかないと理解が進まないと思います。この点についてはちょっともう一回お聞きします。","respondent":"岩崎環境清掃事業部長","answer":"ですから、そういうふうに重さがどうなのかということで言えば、扱いは軽かったのではないかと思っていますけれども、それが現状だったということなのではないかと理解しているということです。","voiceIndex":53,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":32259,"voices":61}},{"id":"h17-20050608-14","meetingId":"h17-cm06","date":"2005年6月8日","dateIso":"2005-06-08","committee":"行財政改革特別委員会","time":"午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"中島委員","kind":"質問・要望","question":"２点、質問いたします。それから、外部委託の、公園施設受付維持管理とありますが、しながわ中央公園もそうだと思うんですが、非常によく管理されていて、花もいつもきれいになっているんですが、ちょっと一つ気になることがあるんです。これは全く外部のお店ではないかと思うので、そこら辺のところを、ちょっとご説明いただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"すみません、説明がちょっと短かったんですけれども、旧一碧荘につきましては、平成９年から貸出しをしておりましたけれども、施設等が老朽化して、実際にあそこの温泉が使えなくなった段階が閉館をいたしました。","voiceIndex":34,"id":"exchange-001"},{"speaker":"中島委員","kind":"質問","question":"よくわかりました。以前、ほかの区の施設に、ちょっと看板をつけられないかという相談を受けたことがあるものですから、そういう方が、あれを見たときに、どう判断されるのかとちょっと心配だったものですから、明確に伺っておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"何点かですけれども、一番大きい形で聞きたいのは、民間委託とか、指定管理者制度とか、要するに、行政から手を離すというのか、民間委託等が法的にできる行政の仕事と、できない仕事とあると思うんですけれども、その辺、大きく分けると、どういう分け方ができるか、ちょっと教えてください。","respondent":"榎本行財政改革担当課長","answer":"管理運営委託という形が、地方自治法上で、新たな概念として出てきて、それが今、指定管理者制度に変わってきているという形です。ですから、徐々に主体として委託できる範囲が、法的には、規制が緩和されて広がってきているというような認識を持ってあります。","voiceIndex":37,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば戸籍住民課というか、そういうものを扱う場合とか、民間企業でも、外部に委託しているような給与管理体制とか、直接、区民に対するサービスやら、内部的な事務処理的な仕事やら、いろいろあると思うんですけれども、ここまでは外部が入っては来られないとか、これ以上先については、直営というか。","respondent":"榎本行財政改革担当課長","answer":"例えば区民住宅等に関しましても、利用料の決定は、区がきちんとしなければいけないということですけれども、その後の賃料の徴収行為ですとか、そういうものについては委託ができるという判断で、それぞれ業務ごとに、そういうような通達等も出ているところもありますし。","voiceIndex":39,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"地方自治法だとか、それ以外のいろいろなもので、法的に規制というか、拘束力が働いているということがあるのか、ないのかという、法的な部分を、まず教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"そういう意味でいきますと、こういう委託等の場合については、許認可等の公権力の行使事務については、委託できないものと解されているということなんで、解釈の問題がかなり入ってきております。","voiceIndex":41,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。それから、次に、指定管理者制度というのが始まったわけですけれども、平成１８年度中に、この制度を取り入れるか、取り入れないかというのを決めていかなきゃいけないというような、時限的な制約があるというような話も聞いているんです。この制度そのものは、これから先、折に触れて導入しようという場合は、行政としてできるかどうかというのを、まず一つお聞きしておきたい。","respondent":"榎本行財政改革担当課長","answer":"そういう通知等が出ておりまして、事実上できるのは、道路であれば、清掃とか、簡単な維持補修とか、そういうものは指定管理者に任せて、委託して構わないということなんですけれども、許認可権限の部分についてはできないということで、通知が出ております。","voiceIndex":43,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"指定管理者の民間委託の欄なんかは、はっきり区側のメリットだけが表示されていて、これによって、もしサービスを利用する区民にとってのメリットがあれば、そういうことも表示しておいていただければ、ほかのものに移行するというか、運用を変える場合でも、判断の基準が出てくると思うんで、それも次回で結構ですから、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"民間活用の手法が、いろいろ、このところ増えていますけれども、ちょっと二つのところでわからないので、教えてください。一つは、すまいるスクールの指導員の委託がどこに該当するのか。それから、学校にも拡大されました、給食の業務代行がどこに当たるのか、教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"すまいるスクールにつきましては、該当するところが２カ所あるんです。一つは直営ということで、非常勤職員を活用してすまいるスクール事業を運営しているというところ。","voiceIndex":47,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"両方とも外部委託だということですが、働いていらっしゃる労働者の労働条件を守っていく法的な根拠はどこにあるのか、教えていただきたいんです。","respondent":"榎本行財政改革担当課長","answer":"一部業務委託しているすまいるスクールにつきましては、それも、請負契約という形でやっておりますので、実際の人材を配置している会社のほうに、その部分の責任があるという形です。","voiceIndex":49,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"法的に不可能なものは別として、委託ができる事業で、現在、委託をしているのが何事業、どれぐらいになっているのかということを、今、説明いただければありがたいですし、後ほどでも構わないんですが、説明いただきたいというのが１点です。ちょっとそこの点を説明いただけると、ありがたいんです。","respondent":"榎本行財政改革担当課長","answer":"委託業務の全体の数なんですけれども、実際に委託の契約件数でいきますと、区全体で５,０００件ぐらいあります。それは、施設ごとの清掃委託を１本と数えて、あと警備委託、設備補修委託という形で考えていくと、大ざっぱに５,０００ぐらい件あるという話です。","voiceIndex":51,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"区の負っている多くの事業は、生産をしているわけじゃないですから、やっぱりサービスの提供が多いとなると、いきおい、受けた側は、人件費を節減をしていくということになって、そのことが、結果的に、低賃金で、非常勤、パート、自立できないということになるというのは、デメリットとして、やっぱり押さえておくべきなんじゃないかなと思うんです。その辺は、いかがなんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"委託する場合に、今ある事務事業の単位で委託できるものがあれば、その単位だけで委託すればいいんですけれども、いろいろな事業を集めて、これとこれを集めることによって、それだけの規模であれば委託可能になるというところもありますので、そういった意味で、今。","voiceIndex":53,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"私は、民間活用を、もちろん全部否定するつもりもありませんけれども、特に、民間会社に委託をしていくとなりますと、そこはやっぱり営利を追求するというのが、こうした会社の最大の目的ですから、安全性の問題や何かと、当然、バッティングしてきて、今、言われたサービスの向上という点がどうしてもなおざりなりがちだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"事業権利契約の中のＰＦＩ方式について、ちょっとお聞きしたいんですが、品川区の中では、現在、やっていないということが出ているんですが、今後、こういう形の形態を考えていらっしゃるのか。これが、多少、プロポーザル形式とＰＦＩの設計とかという絡みが出てくると思うんですけれども、あれは完全なＰＦＩではないと思うんですけれども、今後、どういうふうに考えていくかという点を教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"指定管理者のプロポーザル方式ですけれども、やはり、その設置目的に合わせて、どういう形の運営がいいのか、どういうつくり始めがいいのかという形で、要は、最初から運営事業者を想定した、実際の運営を想定した施設をきちんと建てていきたいという考え方に基づいて、今回は。","voiceIndex":56,"id":"exchange-013"},{"speaker":"築舘委員","kind":"意見","question":"人材派遣のところなんですけれども、選挙事務ということで、投票所に関して、民間からの派遣ということなんだと思うんですけれども、これは、明るい選挙推進員のような方がやっていらっしゃるのか、どういう方がやっているのかということ。それから、経済効率が、職員採用よりも大きいというんですけれども、必ずしもそうなのかなと、ちょっと疑問があるので、その点に関して。","respondent":"榎本行財政改革担当課長","answer":"経済効率の部分につきましては、よく非常勤職員と比べられるときがあるんですけれども、非常勤職員の場合ですと、事業主負担ですとか、労務管理の部分、そういうものをトータルで考えたときに、業務量が一時的に多くなるようなものであれば、人材派遣のほうが。","voiceIndex":58,"id":"exchange-014"},{"speaker":"築舘委員","kind":"意見","question":"投票所に関してなんですが、業務内容に制約は出てくると思うんですけれども、どういうところに委託をして、仕事をさせるかというのはわかりますか。","respondent":"榎本行財政改革担当課長","answer":"それにつきましては、きちんと守秘義務もかかっていますし、決められた日時に、大量の人を派遣受け入れをして、活用ができるという形をとっています。","voiceIndex":60,"id":"exchange-015"},{"speaker":"大西委員","kind":"質問","question":"私も、品川図書館、大井図書館にたびたび行くんですけれども、非常にいろいろな方々が、私の感覚とすると、非常に庶民性のある方々が、よくカウンターに立たれているけれども、品川区においての図書館では、どのような形になっているか、教えてください。","respondent":"榎本行財政改革担当課長","answer":"図書館の運営につきましては、平成１６年度、１７年度、２カ年に分けまして、窓口受付の業務委託を図ってまいりました。今年の４月から、全１０館が窓口受付事務の委託という形でスタートしております。","voiceIndex":62,"id":"exchange-016"},{"speaker":"川西副委員長","kind":"質問","question":"お願いだけです。それで、いわゆる経済効率、住民サービスというものを、この委員会で１人の委員として評価する意味で、区の中の業務が、どの程度、どこに、どういうふうに人材派遣が活用されて、行政運営がされているかということを知りたいので、この次までに、資料を出していただくことをお願いしたいと思います。常任委員会に抵触しないように、議論いたしますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-017"},{"speaker":"藤田委員","kind":"質問","question":"それから体育館については、品川区スポーツ協会ですか。直営の中で、文化センターと歴史館、これは大まかに言えば品川文化振興事業団でというふうに理解できないことはないんですけれども、これは教育施設としてのあり方というふうに考えていらっしゃるのかもわかりませんが、こうした文化センター、歴史館を、事業団委託にできないという理由が何かあるんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"文化センター、歴史館も、特に委託ということを考えれば、どこに委託するかという手法の問題で、何が一番区民サービスの向上と効率化に結びつくのかという観点から考えた場合に、事業団委託が最適だということであれば、委託ができないという縛りはございません。","voiceIndex":66,"id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"事業団にすると、そういう一つの枠を超えて、区民に対していろいろなサービスが可能になってくるのではないかなと、こういうことも考えられますので、今、縛りがないとおっしゃるんですから、大きく言えば、生涯学習という中で展開されていくということが大事ではないかなと、私は思うんです。これは意見として申し述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-019"},{"speaker":"三村委員","kind":"質問・要望","question":"以前、区民からのお話で、品川区では、区民との協働をうたっていて、事業を手伝ってほしいと言われて手伝いに行ったら、机を並べさせられたと。それは協働でも何でもなくて、単なるお手伝いだろうみたいな、そういうお話を伺ったことがあるんです。そういった点については、どのような認識をお持ちか、お伺いをしたいんです。","respondent":"榎本行財政改革担当課長","answer":"今後も、ＮＰＯがいろいろな事業をやっている中で、区の事業と一致しているものについては、そういう関係をいろいろと検討していく必要があるのかなと考えております。","voiceIndex":69,"id":"exchange-020"}]},{"id":"topic-02","title":"行政評価の検証に関すること","agenda":"行政評価の検証に関すること","exchanges":[{"speaker":"三村委員","kind":"質問・要望","question":"冊子のほうを見たときに疑問に思ったことなんですけれども、内側の左側にある３番目で、「健康で喜びをもって生きられるまち」という項目がありますよね。当事者の求めている必要性の大きさとはまた違った視点で、対象としている人数が多い、少ないによって、重要度が上下してしまうのではないかなと思ったんですけれども、その辺はどのようにお考えでしょうか。","respondent":"榎本行財政改革担当課長","answer":"こういうものがきちんと使えるのかどうかというのも含めて、第２期では、ほんとうにその部分がどういうふうに分析できるかということも含めて、検討を進めているところです。","voiceIndex":76,"id":"exchange-021"}]},{"id":"topic-03","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"今、委員長がおっしゃられた、別々にやるというと、言われたように、８回前後ということになると、単純計算で３回、３回、２回ということになる。それから、きょう、いろいろな資料をお願いした部分もあるし、調査項目の１番、２番については、正副委員長で、どの辺の内容についてというのはご相談されて、委員会運営されると思うんですけれども、毎回取り上げても何とかなる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"というのは合併の特例法で、例えば１年半とか、２年とか、倍ぐらい議員がいたり、あるいは、そんなにもいないけれども、いわゆる法定数を上回っているところがほとんどです。だから、結構参考になる話があちこちの市議会で起きていますので、情報が入れば、聞かせていただきたいと思いますし、今、委員長が言われたような流れをつかんで、正副委員長でご相談いただければいいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":30465,"voices":91}},{"id":"h17-20050609-16","meetingId":"h17-cm06","date":"2005年6月9日","dateIso":"2005-06-09","committee":"街づくり特別委員会","time":"午後１時０４分～午後２時３２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤副委員長","kind":"意見","question":"副委員長の伊藤です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、耐震診断を受けた方が補強工事をやる場合には、０.９％の利子補給を受けられると、こういうことだというふうに思うんですけど、その辺の確認と、今現在その事業が開始されていると思うんですけど、どの程度優遇があるのか、あるいは説明もどの程度になっているのかというのをちょっと教えていただければと思います。","respondent":"片田建築課長","answer":"それともう一点、今回耐震診断を受けたものについて利子補給等を含めて低利で融資あっせんするという事業につきましては、今年の４月から実施しているものでございまして、その実績については、まだ始まったばかりですので、それに伴う件数は出てございません。","voiceIndex":47,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"４２件の申請で取りやめが２件だということなんですけれども、割と私は区民の方の関心は高いと思うんですよね。だから、４０件想定なのに４２件あった。それと、２件取りやめになったというのはどういう理由なのか、全然該当しないからだめですよと区側が申請を受け入れなかったというふうにはちょっとさっきとれなかったので、取りやめたという表現ですから、その辺のことをもう少し教えていただきたい。","respondent":"片田建築課長","answer":"引き続き区民の方に融資あっせん等の内容も含めて周知してまいりたいということで考えてあります。","voiceIndex":49,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問・要望","question":"１３３ページの住宅改善資金融資あっせん助成事業について、これは住宅ということなんですけれども、共同住宅の区分所有者というのはここの範疇に、融資あっせんの対象になるのか。地域によっては、普通の、いわゆる一戸建てよりも共同住宅の多い地域があるんですけれども、そこの部分で丸々１棟になった場合、どういうふうな形が受けられるのかというのをまず１点お伺いしたい。","respondent":"片田建築課長、中島街路事業担当課長","answer":"ただ、共同住宅ということになりますと、委員おっしゃるように、複数の所有者がいらっしゃるところですので、耐震診断そのものについては、まだ現時点で共同住宅までは対象ではございませんので。今の感触ではなかなかまっすぐな道路になりますので、東急バスとしても非常に興味を持っておりまして、検討していきたいというような回答を得ているところです。","voiceIndex":51,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"もう一点、バスのことについての質問なんですけれども、大井町から直通で２６号線の開通をにらんでということで、おそらく武蔵小山駅というのは、まさに品川区と目黒区の境目ですので、ぜひ予定があれば、１路線だけではなく、強力に進めていただければ、より身近に品川区役所と武蔵小山は近くなると思いますので、バスのほうは要望いたします。","respondent":"片田建築課長","answer":"共同住宅というのは、いろんな難しい問題があります。というのは、１人でお持ちになっていて、お貸ししているという、いわゆるアパートとか、賃借されているといったようなものがあります。","voiceIndex":54,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか確認したいんですが、聞き漏らしたらまた教えていただきたいんですけれども、まず、地域危険度のご説明をいただいたんですが、調査の見直しという点で、現在はマンションの建設等々で既に現状は変わってきているんじゃないかなと思うんですが、その辺の図面の調整というのは、どういう形でしていかれるのか。","respondent":"久保田防災課長","answer":"したがって、前回の調査と今回の調査を比較して、ランクが上がった、下がったというふうに単純な比較ができないというのが、これがちょっとこの調査の難点でございまして、その辺については、東京都も反省しながら次回の調査にはというような見解は出しているんですけれども。","voiceIndex":56,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"そうすると、今のところ判断基準というのは、東京都のこの調査によって判断されるということなんですが、品川区として、やはり一番品川区のことを知っていなければならないとは思いますし、この委員会の中でも審議するためには実情を踏まえた形での審議をしていかなきゃいけないというふうに思うんですが、その辺の考え方、それから、報告をどういう形で今後していただけるのかなと思っているんですが。","respondent":"久保田防災課長","answer":"先ほどまちづくり事業部のほうからご説明があったとおりなんですが、この危険度調査の中で出ているいわゆる危険度の高い地域については、品川区でも独自の調査等を踏まえて今後のまちづくり対策の施策の参考にしていくという形でやっておりますので。","voiceIndex":58,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"そういった中での審議というのはあまり身にならないと思いますので、これから視察もしていくと思いますので、ぜひいろいろ状況が変わった中での危険度というのはどういうふうに考えていったらいいのかなというところで議論していきたいと思いますので、そこのところをよろしくお願いしたいと思います。それで、企画部がどういう関係から担当になっているのかなということを聞かせてください。","respondent":"榎本行財政改革担当課長","answer":"それからあと、転用のこういう決め方とか、そういう形なんですけれども、実際には公有財産の活用検討委員会というのが庁内にありまして、その中で実際にこういう空き施設が出てきたときに、企画のほうで全体を調整しまして、必要な。","voiceIndex":60,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"できれば、平成１８年度もいろいろ考えられているようなところもありますので、その経過、それからどういう内容でこういう使い方になっているのかということも含めてご説明をいただきたいなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"活用に当たって、どのような、区民の参加ですとか、要望があったのかというところをちょっと聞きたいんですけれども、もちろん敷地面積の大小にかかわらず、大切な区民の財産の場所ですから、区民の要望に沿った施設に活用していくという点はもちろん重々承知だとは思うんですけれども、第三次長期計画に書かれている区民との信頼の懸け橋。","respondent":"榎本行財政改革担当課長","answer":"公有財産の活用検討委員会の位置づけですけれども、総務部長が委員長ということで、総務部、企画部、それから財産管理をしている副収入役等が入った委員会です。","voiceIndex":63,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望を受けながらこの検討委員会でやっているというお話ですけれども、その検討委員会の中には、いわゆる地域の方ですとか、学校でしたらＰＴＡの方ですとか、それと区民の方というのは入っているのかどうかを教えていただきたいのと、要望は受けているとしながら、これといった調査活動をしたわけじゃないというところがちょっと矛盾しているかなと思うんですけれども、第三次長期計画には。","respondent":"榎本行財政改革担当課長","answer":"それで、この学童保育クラブについては、比較的小規模なものが多いものですから、まだ具体的には検討という形になっておりませんけれども、今後ほかの耐震診断の計画を立てる中で、順次必要性があれば、それぞれ検討していくという考えです。","voiceIndex":65,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"確かに今子どもの施設を優先にやっていくというのは承知していますけれども、ここを利用する高齢者の方、障害者の方、あとヘルパーステーションの職員など、やっぱりまずは公共施設の耐震化というのが今一番求められていると思いますので、これは必要性があってからじゃなくて、必要性はあると思うんですけれども、ちょっとそこを教えていただきたい。ちょっとその進行状況を教えてください。","respondent":"榎本行財政改革担当課長","answer":"それから２点目の要望なんですけれども、日野中学校近辺での具体的な要望というのは、今のところ、特に区政協力委員会、世論調査等でもそういうものを聞いておりませんので、今の検討としては、区としての原案をまとめてから。","voiceIndex":67,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"耐震診断はわかりました。日野中学校のほうは、現段階で聞いていない、寄せられていないということなんでしょうか。つまり、住民からの要望はもちろん来ますけれども、区からも接近して、いろんなご要望を聞いていくと、こういう姿勢に立っているのかどうか伺いたいと思うんですね。日野中学校は平米が書いてあるけど、１万２,０００m2ですか。これは膨大な土地ですよね。ここをどんなふうにしてほしい。","respondent":"榎本行財政改革担当課長","answer":"先ほど言いました公有財産検討委員会の部分は、ある程度学童保育クラブのほうで活用しまして、日野中学校のほうは区として重大な取り組みという形になっておりますので、公有財産の範囲を超えて、直接事業部経営会議のほうでやるべきという形で今とらえております。","voiceIndex":69,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"日野中学校の場合はそうではないので、どういう使われ方をするかまだわからないものですから、その辺で今年度、平成１７年度は日野中学校は教育、学校ということで使っていくということで、タイミングというんですか、課題を検討していく中で、今学校で使っているんですけれども、その辺の進め方について、タイミングといいますか、タイムスケジュールというか、その辺で。","respondent":"榎本行財政改革担当課長","answer":"それで、タイムスケジュール的には原案をしかるべき時期に出した上で、幅広い意見を受けて、それを固めていくというような形で今のところ考えておりますので、もうちょっとしかるべき時期にちょっと検討の時間をいただきたいです。","voiceIndex":71,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問","question":"当然検討されているのはわかるんですが、学校で使っているんで、何かまだ平成１７年度は学校じゃないですか。それで、１８年度以降の使い方をある程度決めていくのは時期尚早とか、何か問題があるのかなと。なきゃないでいいんですが、それだけちょっと教えてください。","respondent":"榎本行財政改革担当課長","answer":"特に平成１８年以降につきましては、日野中学校は大崎のほうへ移転しますので、その後の部分については特にしばるわけじゃありませんので、今検討しているところで十分いろんな活用等を幅広くとらえた上で原案をまとめるです。","voiceIndex":73,"id":"exchange-015"},{"speaker":"山村委員","kind":"質問・要望","question":"私も日野中学校のことでご質問します。それとも、全然そういう、ちょっと私も知識が浅くてわからないんですが、そこら辺のことはどういうふうに考えられているのか、教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"その避難場所等も含めて検討しておりますので、もう少し原案が出るまでお待ちください。","voiceIndex":75,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"しゃれた街並みづくりの関係なんですけども、先ほどの説明では、前年度に継続してというお話だったんですけど、前年度、ちょっと不勉強で議事録も何も読んでいないで今日臨んじゃったので、どういうふうになっているのかわからないので質問させていただきたいんですけど、地権者が何人ぐらいいらっしゃるのかとか。","respondent":"伊勢住環境整備担当課長","answer":"この事務事業概要の図ではちょっと載っていないんですけども、先行しているのはいわゆるＤ地区と言われるところで、そこでは都心共同住宅供給事業が予定されてあります。そこの地権者については、２９名いらっしゃいます。","voiceIndex":77,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"地権者２９人のうちの内訳、そしてその他の部分の説明をいただいたんですけども、全員合意ということなんですが、それは地権者、いわゆる２９人の部分のところを言うのか、多分そうだと思うんですけど、そのほかに６１人の借家人がいらっしゃるということですが、そういう方たちの権利というのはどういうふうに担保されるんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"基本的には全員合意というのは所有者、それから借地権者です。それから委員お尋ねの借家人の方ですが、借家人の方は大家さん、所有者の方との関係になりますので、その関係で対応が出てくると、こういうふうに考えてあります。","voiceIndex":81,"id":"exchange-018"},{"speaker":"南委員","kind":"確認","question":"そういう場合、大家さんとの関係で、そこが協議をして、新たなところを見つけると、こういうふうになっていくんだろうと思うんですけども、だから、当然大家さんとしては、そういう店子さんの立場も考慮しながら、この計画については参加をしていかざるを得なくなると思うんですけど、その辺の確認と、それから、今のＤ地区の状況がどういうふうになっているのかちょっと伺いたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"この辺を踏まえながら近隣への説明、こういうものも予定して進んでいくというふうに考えております。","voiceIndex":83,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"その日程的なスケジュールは先ほどの説明でいただいたところなんですけども、私が今一番伺いたいのは、今のＤ地区の進行状況の中で、全員合意がとれているというお話なんですが、店子の部分の借家人の方々のところが、この計画についてどういうふうな理解到達になっているのかというところが聞きたいところなんですけど。","respondent":"伊勢住環境整備担当課長","answer":"１カ月ぐらい前の時点ですけれども、２件営業されている方で、お話を継続してやっているということで、つい最近の現状をちょっと聞いていなくて申しわけないんですけども、引き続き営業できるかどうか、継続的にお話をされていると。","voiceIndex":85,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"それをしっかりと進めていかないと、今の私が質問したい、申し上げたいことは、この計画に限らずの話なんですけども、全体にかかわることだから、改めてしっかり伺いたいというのが、一つ最後にこの問題ではあります。それで、交通広場の整備が今されようとしているというところなんですが、この駅舎がどういうふうになっているのか。その上に上部の計画が東急の計画としてどうなっているのか。","respondent":"伊勢住環境整備担当課長、中島街路事業担当課長","answer":"南委員からそういう立ち退きのお話をいただいている方を大事にしてほしいというお話ですが、区の立場といたしましては、しゃれた街並みづくり、それからこの武蔵小山の駅前の都心共同の建設、当然支援していくわけですので。目黒線の連続立体交差事業の関係ですけれども、現在工事をしておりまして、武蔵小山につきましては地下化されるということで、平成１７年度中に地下切り替えをしていくということで工事を進めてありますけれども、東急電鉄の説明では。","voiceIndex":87,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"そういうのができると、やっぱり地元商店街にはかなり大きな影響があるというふうに思うので、白紙というのは非常に不安が広がっていく一方なんじゃないかなというふうに思いますので、区としてはその白紙という言葉、表現をどういうふうに見ていられるのか、東急のほうに何らかの形で意見として区のほうが言っていられるのか、その辺、言っているとしたら、何をどういうふうに言っているのか。","respondent":"中島街路事業担当課長","answer":"東急電鉄と私どもは事業の関係で話し合ったりする機会はあるわけですけれども、そういった中では、現時点で、先ほど申し上げましたけれども、東急は駅ビルをつくりますとか、つくりませんということは言ってございません。そういった意味の白紙です、です。","voiceIndex":90,"id":"exchange-022"}]},{"id":"topic-03","title":"のその他","agenda":"のその他","exchanges":[{"speaker":"南委員","kind":"意見","question":"あれこれと具体的な項目をちょっと今挙げられないんですけども、調査項目として災害に強い街づくりとか、安全対策だとか、いろいろあるわけですが、例えば防災の先ほど説明いただいた危険度調査で随分危険度が高いというふうに示されたああいう地域の状況がどうなっているのかとか、表現としていいか悪いかは別としても、ハーモニカ長屋だとか、そういうふうな言われ方をしているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":27161,"voices":97}},{"id":"h17-20050704-6","meetingId":"h17-cm07","date":"2005年7月4日","dateIso":"2005-07-04","committee":"区民委員会","time":"午前１０時０４分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)第３３号議案、品川区特別区税条例の一部を改正する条例","agenda":"はじめに、(1)第３３号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"一番はじめの、区民税非課税なんですけれども、まず、１２５万円以下の者に対するということですが、これがこうなる形によって、どのぐらいの対象者数が増えるのかということ。それから、転出、転入というのはありますが、大体の予想でいいんですが、どのぐらいの税金が増えていくのかというのはわかりますか。","respondent":"太田税務課長","answer":"所得割については、その世帯の所得の控除、医療費控除とか、扶養の控除等々がありますので、どのぐらいということは、個々によって違ってくるということなので、少なくとも、均等割が全員に課されますので、それでいきますと、平年度ベース。","voiceIndex":5,"id":"exchange-001"},{"speaker":"藤原委員","kind":"意見","question":"対象者に対してのお知らせですが、区として、どういう仕方をするのかということ。それから、そのお知らせを読んでくださる方はいいんですけれども、突然、税金が来たよとなると、区に対しての問い合わせ等もあると思います。その職員の方々の応対の仕方とか、どういうふうに指導しているのか。２点、お答えください。","respondent":"太田税務課長","answer":"一斉の賦課の前には、改正の注意すべき点等のマニュアル等を配付していきますので、今までも丁寧な対応ということを心がけてありますが、対象とされる方が、今回は６５歳以上の方が多くなってありますので、より丁寧、十分な説明をしていきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に１点お伺いしますが、４番ですけれども、言葉がわからないので教えていただきたいんです。特定中小企業が発行した株式云々と出ていますが、このことが、何でエンジェル税制とついたかわからないんです。エンジェル税制という言葉の意味といいますか、株式の譲渡で、何がエンジェルになるのか、説明していただけますか。","respondent":"太田税務課長","answer":"エンジェルというのは、そのベンチャー企業に資金提供や経営アドバイスを行う個人投資家を、そういうふうに呼んでいるです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは大きな改正ですので、確認したいことが何点かあります。そうならば、ホームページで広報するということも、もちろん必要なんですが、もっとダイレクトに、６５歳以上が対象となるとわかっているわけですから、個々の６５歳以上の対象者にＰＲするということを、改めて確認させていただきたいことが一つ。それから、最も大きなことが、なぜなんですかと、なぜこういうふうに税制を改正するのか。","respondent":"太田税務課長","answer":"それからあと、ちなみに、税務署等を含めまして、税の相談会というのを毎年やってあります。例えば、今年であれば２月の上旬に３日ほど申告相談というのを実施していますので、そうした部分のＰＲもして、ご相談を受けながらやっていきたいと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"少子高齢化社会というのは、いくらでも出てくる話なんです。それから、それをカウンターに置くとか、申告相談に来たから配るということではなくて、もっともっと、対象者にストレートにダイレクトにお願いしたいし、少子高齢化社会というのは、これからいろいろなところで出てくるわけじゃないですか、だからこそ必要なんじゃないでしょうかということを聞いていますので、もう一度、答弁をお願いします。","respondent":"太田税務課長","answer":"私どもも、常日ごろ、わかりやすく説明責任をしているつもりですけれども、さらに今回の改正については、どれだけ特定できるかは別として、ご指摘の趣旨を踏まえたことができないかどうか、今後、検討をしていきたいと思ってあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、それをわかりやすい形で説明していただきたいのと、あとは、国からの押しつけをそのまま出すのではなくて、行政でもこういうような努力をしていますよ、それから、国単位でもいいでしょう、品川区単位でもいろいろあるかもしれませんけれども、こういう努力をしておりますけれども、でも支えきれないので、こうですというようなことを、具体的にわかりやすく説明していくことを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ほかに、リンクしてといいますか、同時という言い方ですか、並行して負担が上がるものというのは、どういったものがあるのか。金額というか、大きさも含めて、ちょっと教えていただきたい。それからもう１点、この理由の中で、少子高齢化の説明がありましたけれども、教えていただきたいのは、そもそも税金の集め方の原則というのも、どういうものなのか、ちょっとそこを教えてください。","respondent":"太田税務課長","answer":"１点目の影響のほうですけれども、私ども、すべて把握しているわけではございません。税をもとにして事業を実施しているものについては、やはり、税が賦課をされれば、その部分の影響は出てくるかなと思ってあります。ただ、額とかは、私のほうでは把握をしてございません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"はじめの質問ですけれども、税をもとにしている事業が変わるというところで、具体的にどんなものが変わってくるのか、そこを教えてください。そういうわけではなくて、ここでは能力に応じて負担してもらうんだと、社会全体、それぞれの住民の経済的な負担に応じていくんだということだと思うんですけれども、ここをちょっと、もう一度説明してください。","respondent":"太田税務課長","answer":"後半の２点目ですけれども、先ほど申し上げましたように、地方税、住民税というのは、そもそものことから申し上げると、あくまでも社会を共同してつくっていこうと、安定して継続的な社会、住みよいまちをつくっていこうという趣旨から出ていると、私は理解しています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜかというと、開けると、高齢者ですから、なかなか難しいのかもしれないけれども、負担増のお知らせが多いんですよね。新たに負担が求められたりとか、役所から手紙が来るのが怖いなと話していました。今回、単純に、国の税制が変わったから、こっちもはいどうぞというのではなくて、やっぱり区として、一番身近に住民に寄り添っている自治体として、国に対してものを言うべきことも必要だと思うんです。","respondent":"太田税務課長","answer":"今回の改正の内容についても、私ども担当者としては、先ほど、改正する理由を申し上げましたけれども、６５歳という年齢だけをもって税制上の優遇をしていくことが、今後の少子高齢化社会を考えた場合に、今後も。","voiceIndex":20,"id":"exchange-009"},{"speaker":"木下委員","kind":"質問・要望","question":"だから、ぜひ説明責任を果たしていただきたい。その中で、チラシをつくるというお話があったんですけれども、例えば各町会に、なぜそういう形で非課税措置廃止をしなければならないのかというものを取り入れていただいて、先ほどご説明されたように、負担していただくという説明を入れていただくと、町会の回覧板などでお流しいただきたい、これは要望としてお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"先ほど、出たかもしれないので、ちょっと聞き漏らしたかもしれないんで、もう一度教えてもらいたいんですけれども、例えば改正されて、具体的に、年金収入が２１２万円以上の方は住民税が課税されるということだと思うんですけれども、金額はどれぐらい、大体のところなんですけれども。","respondent":"太田税務課長","answer":"ただ、２４５万円の年金収入の方を前提にして、単純に計算しますと、個々の生命保険とかのことを考えないでやりますと、税負担で、年間で約２万５,０００円前後になる。","voiceIndex":23,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"当然、今おっしゃったように所得のいろいろな控除によって、また世帯の構成によって違ってくるということなんですけれども、やはり、私たちも、なかなか具体的にどれぐらいというのが、モデルケースみたいな感じで、全部のモデルケースも難しいんですけれども、いろいろな案内の中に、その辺のところをやっぱり、これだというのではなくて、例えばここからこれは入るとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"年金収入しかなくて、かといって、アルバイト等も、６５歳以上、７０歳になると、ほとんどありません。それから、第２点で、では、今の不公平感を是正するということで、今回、ある意味で、高齢者に対して一部増税になりますけれども、その増収分は実際に何かに使われるとか、どこかに回すとか、そういうようなことはあるんでしょうか、国の考え方として。","respondent":"太田税務課長","answer":"今、政府税調の中でも、今後のさらに住民税、地方税のあり方について検討して、先般、課題と整理というものも出されましたし、それから、三位一体改革の中で税のフラット化の問題も議論をされているようですので、今回、増収になった部分というのは、当然。","voiceIndex":26,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"すみません、１点だけお話ししますが、区として、アカウンタビリティが大事だと思うんですけれども、それで、いわゆる、区民に対してお知らせ等で、印刷物をつくると思うんですけれども、１,５００万円ぐらい税収が上がるわけですよね。その税収に対しての印刷物等のいわゆるお知らせにかかるお金がありますよね、その辺のバランスはどのように考えているんですか。","respondent":"太田税務課長","answer":"印刷物等の経費といっても、基本的には庁内印刷なりをやってまいりますので、そういった面では、ＰＲ経費というのは、そんなにはかからないと思っています。","voiceIndex":28,"id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"態度表明としては、私は反対です。理由を言いますと、３,５００人の方に、新たに負担があると。それに伴って、今後、介護保険、年金の負担が増える。とてもこれだと高齢者の暮らしが苦しくなって、今でも大変なのに、これはやるべきではないというのが一番の理由です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１点だけ教えてほしいんですけれども、能力と行為能力との違いは何なのか。","respondent":"中山清掃リサイクル課長","answer":"あくまでも、これは法律行為が成し得ない場合のものに対して、例えば無能力者という表現があったり、法律行為が成し得る場合に能力者ということで、あくまでも、この辺を明確にしようということで、法律行為に限った能力という意味で、行為能力と変えたと認識しております。","voiceIndex":39,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、民法上で、本人の知識や能力がないということではなくて、法律上の権限なり、責任をすることができる能力というふうに考えていいんですか。","respondent":"中山清掃リサイクル課長","answer":"そのように考えていただいて結構です。","voiceIndex":41,"id":"exchange-017"}]},{"id":"topic-02","title":"専決処分の報告について（報告第１３号）","agenda":"専決処分の報告について（報告第１３号）","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"となれば、確認したいのは、運転手に説明を聞いたということでしたけれども、いわゆる直営であっても雇上であっても、それは同じでなければいけないと思いますので、そのことについて、どう対応されていますかということを一つ確認したい。そういうふうに、もう少し安全対策を具体的に進めていく手だてを物理的に考えていくお考えがおありでしょうかということをお伺いしたいと思います。","respondent":"冨岡品川清掃事務所長","answer":"２点目ですけれども、なかなか物理的には経費のかかる問題もあります。とにかく、研修自体も、今までの通常の研修以外に、事例をもとにした研修とか、そういうものを積み重ねてまいりたいと考えています。","voiceIndex":50,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要は、このケースは、今聞いた限りでは十分に防げた話だと、私は思うんですよ。カメラは一つの例として挙げましたけれども、要は、今回のケースについては、明らかに防げたであろう事故というふうに、私は思いますので、そういうケースについては、十分に研修とか、研修でないにしても、自覚していただきますように、改めて安全の徹底をお願いしますということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"損害賠償を、損害保険から払ったということですけれども、私なんかも車を持っていたときに、任意保険とかに入っておりましたが、無事故だと、保険を使わなければ何等級とかと安くなっていくと思うんですけれども、この清掃車両等に関しても、こういう無事故割引というんですか、使わなければどんどん安くなっていく、そしてこういうふうに使うと、事故をするごとに。","respondent":"冨岡品川清掃事務所長","answer":"自動車保険の関係ですけれども、事業用の自動車総合保険というものに入っておりまして、品川区の今の環境清掃事業部の車両全体で３４台ありますけれども、これを一括して保険に入っている状況です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"本間委員長","kind":"質問","question":"私のほうから、今定例会の一般質問に係る所管質問について、ご案内申し上げます。本件は、委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問に係る当該委員会の所管質問を行うというものです。質問をなさりたい委員がいらっしゃいましたら、委員長に通告し、翌日、理事者に答弁していただくこととしております。本会議での質問の繰り返しにならないようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":21354,"voices":61}},{"id":"h17-20050704-7","meetingId":"h17-cm07","date":"2005年7月4日","dateIso":"2005-07-04","committee":"厚生委員会","time":"午前１０時０２分～午前１０時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、議案審査","agenda":"の２、議案審査","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"勉強不足の分が１つです。養育者という用語を除いたという社会的背景といいますか、歴史的な流れというのがおわかりでしたら教えていただきたいと思います。それから、かなり養育困難な家庭というのがありますが、今の説明からいきますと、品川区には５人の里親がいらっしゃって、２人しか、２件しか今実績がないということなんですけれども、それだけ必要性がないから今日に至っているのかどうか。伺います。","respondent":"辻田児童課長","answer":"平成１６年度１年間です。そういう中で、やはり里親家庭の状況であるとか、子どもの状況とのマッチングというのがありますので、里親があれば、そこに預けたほうがいいという形には必ずしもならない。いわゆるベストの選択をする中で、里親というこの選択をしたのが２件だです。","voiceIndex":9,"id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"品川区は始まったばかりで、まだそこまでないかと思うんですけれども、広域だとそういう目の届かないところで、ほんとうに困った人を安心して育てられるかというのが非常に疑問に思っていたんですけれども、そういう心配はないかどうか。それと、預かる側の調査というのもどういうふうにやられるか、説明をちょっとお願いします。","respondent":"辻田児童課長","answer":"この制度は、一定の、例えば申込者の年齢が２５歳以上６５歳未満であるとか、居室の広さが２室１０畳以上ある、それから居室は台所から独立していますよというような家庭環境の条件のほかに、当然東京都がこの養育者と認定する場合、当然そこでの調査というのはあるです。","voiceIndex":11,"id":"exchange-002"},{"speaker":"山路委員","kind":"質問","question":"そういう意味では、東京都の広い範囲から品川区ということで、地域の方もいろいろな情報が豊富にこれからあるでしょうから、こういう親がなくて育つ子どもが幸福に育っていくんじゃないかと思うんですね。そういう意味では、この条例は非常に私はいいと思います。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明のところに入居要件等を改めるとあるんですけれども、第４条の居宅受給者証について、もうちょっと詳しく教えていただきたいのと、あと、支援費の国庫補助が受けられるということで、この辺の補助の負担割合を改めて伺いたいのと、品川区においては、財源がどのように具体的になるのかというのがわかったら、教えていただきたいです。","respondent":"西島障害者福祉課長","answer":"ちなみに、私ども試算をいたしましたところ、若干東京都の上乗せの金額が入ってありますので、西大井つばさの家の支援費ですが約７８０万円余ですが、それが都と国を合わせて５００万円弱の数字が区のほうに補助金として歳入されるということになろうかと思います。","voiceIndex":20,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"受給者証のところは、区が手続きが必要になったということで、そういった面では、ご利用されている入居者の方々に従来と変わったことがないというか、言ってみたら不利益がないということに受けとめてよろしいんでしょうか。","respondent":"西島障害者福祉課長","answer":"利用者につきましては、特に従来と変わっているところはございません。それから、提供されるサービスも、区が実施していた事業は基本的に支援費の対象としている事業とほぼ同じような事業を実施してございましたので、入居者については何も不利益になることはないです。","voiceIndex":22,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"条例には、さして意見はありませんが、関連で伺います。そういうので、１回入ってしまったら、同じ人が２０年も３０年もいるようになるのか、自立生活ということで社会に出せるのか、その辺についてが１つ。この生活寮に入れない対象者で、これらのアイウエの援助が必要な人たちは、どういうところで区は支援といいますか、応援していけるか、すみません、教えてください。","respondent":"西島障害者福祉課長","answer":"いろいろな形があろうと思いますが、現在、この１つの形としてグループホームの中で、日中は別の場で働くなり、あるいは通所施設へ通所するなりして過ごしていただいて、夜間、グループホームで過ごしていただくというような形で実施をしています。","voiceIndex":24,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"自立をして、金銭管理ができない、食事は何とか今コンビニとかいろいろありますからできる。そういう点で、健康管理と金銭管理、大きな生活をしていく上での問題なので、その指導員の方というのは、そういうホームあるいは区に何人か配置されているのかどうか。自立した人たちの金銭管理や健康管理を指導する指導員というのはどこに区は配置されているのですか。","respondent":"西島障害者福祉課長","answer":"財産等があって単身ということになりますれば、当然、将来のことを考えますと成年後見の制度を利用していくということもあります。それで、昨年度は実は３件、知的障害者の成年後見の手続きを実施をしています。","voiceIndex":26,"id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"例えば住んでいるアパートへ行ってみたら、１年も２年も掃除しない状態だった。ですから、手当の中で暮らしてはいるけれども、２０日過ぎたらもう何も金は持っていなかったというような状況の人たちもいるかと思います。あるいは今カードローン等もありますから、非常にそういう点で指導、育成、自立というのを、この条例とは直接関係ないかもしれないんですけれども、ぜひお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お手元に既にお届けしています議員提出第３号議案、あと資料をお配りしています。条例改正の内容なんですが、この１枚の条例改正案を見てお話をしたいと思います。これを右の表に改めます。充実を希望する施設や制度に関しては、子どものいる人は子育てのための経済的援助を、子どもを持たない人は子育てしやすい職場環境などの要望が高い」とありますが、特に一番下のところを見ていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"理事者のほうにお尋ねします。保育料を品川区で昨年度から改正してきましたけれども、それ以前は少子化という傾向はいかがだったんでしょうか。それからもう１点、他地区で保育料を改正していない地区がありますけれども、その辺は少子化がとまっているんでしょうか。少子化の傾向を教えていただきたいと思います。","respondent":"小林保育課長","answer":"少子化の流れですが、こちらと直接保育料との関係ということから言えば、少子化の社会的な状況の流れというのは大きくは変わっていない、こういうふうに考えております。","voiceIndex":34,"id":"exchange-010"},{"speaker":"須藤委員","kind":"提案","question":"ですから、全体をやはり見ていかないと、少子化の問題というのは、なかなか、これだけすればいいという話ではないんだろうと思うんで、この議員提出の議案に対しては、なかなか賛成いたしかねるというのが我々のところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-011"},{"speaker":"山路委員","kind":"質問","question":"確かに少子化の環境整備というのは、今言われているときでありますけれども、全体的に見ていかなきゃいけないんですけれども、保育料の値上げというのは、それなりの理由がたしかありましたね。要するに、他区に比べて非常に厚いので調整をするような意味での昨年１０月からじゃなかったんでしょうか。その辺ちょっと詳しく説明していただけますか。","respondent":"小林保育課長","answer":"前回ご審議いただきました保育料改定の考え方ですが、具体的にはまず品川区の保育サービスの水準が、例えばゼロ歳児保育あるいは延長保育を全園で実施する、また夜間保育、８時半、１０時半までの実施等、十分なサービスを提供してきたという実績もあります。","voiceIndex":39,"id":"exchange-012"},{"speaker":"山路委員","kind":"意見","question":"そういう流れがあって、次世代育成支援法では、特に在宅の子育て支援が大事だということはうたってありますね。現場でいろいろお話を、ご意見を聞いていますと、非常にオアシスルームとか評判がいいんですね。そういう状況の中でのバランス的には、私のほうにいろいろご意見をいただいている中では保育料が特別高いというのはありませんので、結論を言えば賛成しかねるというところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-013"},{"speaker":"川西委員","kind":"質問","question":"一方では、１カ月通わせると週１回で月に４回ですね。６,０００円から６,５００円。ですから、繰り返しますと、楽しい子育てというふうなことで区がいろいろな施策をとっていますが、これらをもう少し、もっともっとですね。若い人たちに子どもを産んで育てることは楽しいことだということをわからせるというのは、どういうことをしていったらいいかというふうに思います。やはり問題は家庭。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"自民党の鈴木真澄委員の一般質問の中で、介護保険制度改正についての中身なんですけれども、特に旧都南病院跡地の問題について、もうちょっと詳しくお伺いをしたいなと考えていますので。跡地利用のところでよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":15470,"voices":48}},{"id":"h17-20050704-8","meetingId":"h17-cm07","date":"2005年7月4日","dateIso":"2005-07-04","committee":"建設委員会","time":"午前１０時０６分～午後２時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３９号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３９号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"一つ一つについてはないですけれども、武蔵小山駅東地区のことでちょっとお聞きをしたいんですけれども、今回Ｄ地区のみということで、主体が３.１ｈａですか。それから、都心共同で建物を建てるということですけれども、総工費と補助金の額を教えていただきたい。例えば組合施行の場合だと、最終的には補償は組合がするという形だそうですけれども、ちょっとそこを教えていただきたい。","respondent":"片田建築課長、伊勢住環境整備担当課長","answer":"それと、地区整備計画自体も幾つかの地域に分かれて、全体として都市計画決定していますので、もし、将来的に地区としての調整の中でまた精査するということになってくれば、当然整備計画の変更なり。都心共同の協議会のメンバーに借家人の方はどうなのかというご質問だと思いますが、これはあくまでも所有者と借地権者ということで考えてあります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"最初に建築課長がご答弁なされたと思うんですけれども、協議会で権利者の皆さんが、いわゆる何人かの権利者の皆さんでお話を進めているということなんですけれども、当初の全体構想と違うものが、この協議会の中で話し合われてまとまっていくというような場合、要するに自分の持っている権利を最大限活用しようとしたときに、これじゃあ採算が合わないので、もっと違う構想というのが生まれてきたときに。","respondent":"片田建築課長、伊勢住環境整備担当課長、岩田まちづくり事業部次長","answer":"特に商業機能の活性化の問題とか、都心共同の問題とか、居住性の向上、そういうものを地域としてどう対応するのかと。それで、先の２名の方のということで、１.７倍の価格になってということと、あと裁判になっていると、その辺はちょっと私のほうで聞いていないんですが。ところが、その建物の減価償却は終わって、そろそろ建て直さなきゃいけないとなれば、その土地所有者の方あるいは建物。","voiceIndex":10,"id":"exchange-002"},{"speaker":"菊地委員","kind":"提案","question":"だけど、営業されている方が、ほかに行っても商売としては成り立たないというふうに、行きようがないといって、そこで商売を続けた場合、再開発みたいな、こういう地区計画がかかっている場合に、強制的な執行とかというのはあり得るのかどうかということと、権利者の場合、都市計画決定との関係ですけど、３分の２で開発の提案ができて、それで行政がそこに介入するというか、手を入れるわけですよね。","respondent":"岩田まちづくり事業部次長","answer":"ここの場合は都心共同住宅という手法を用いた開発を行います。委員がおっしゃった法定再開発の場合は、いわゆる強制的な手法が法で定められておりますので、もともと原則型は反対者がいても、４分の３の合意があれば執行できるという法律の定めがあります。","voiceIndex":14,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"これからのブロックのところで、すべて都心共同を使うわけでは当然ないでしょうから、そういうところでの合意の成立というか、そこがちょっと聞きたい。住民の権利者がいますよと。１人、２人が反対をしました。その場合、都心共同という形ではなくて、要するに３分の２の権利者がまとまれば、整備計画がまとまったという形になるのかどうか、要するに条例に出していけるのかどうかというところ。","respondent":"岩田まちづくり事業部次長、片田建築課長","answer":"地区計画は、大きく二つのものを決めることになっておりまして、一つは大枠のこの地区全体の今後の望むべき姿、開発保全の方針という漠然としたものですね。これをまず決めるのが大事なんですね。望ましい姿。次長のほうから申し上げたとおりですけれども、もうちょっと補足いたしますと、今回の用途の制限、これについては、特に１階部分は店舗とか飲食店以外は原則禁止というふうな内容になっております。","voiceIndex":16,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"確認というか、建築基準の法が改正されて、この制限の緩和ということなんですけど、実際にどのように今までから緩和されて、どういうふうな街づくりにするか、変わるのかということを教えていただきたい。","respondent":"片田建築課長","answer":"ただ、前段のほうの、たしか１７条の条文構成になってありますけれども、大くくりの中で、改正する場所については、建築基準法の中で、ここにはちょっと記載してございませんけれども、一部変更になったりとかして、５２条という項がございまして。","voiceIndex":19,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"先ほど課長が店舗のところで、仮店舗が要らなくなったと言いましたけれども、実質的には要らなくなったんじゃなくて、それじゃあ営業できないということが前提にあるというふうに聞いています。抽象的に住民主体といいますけど、その中身はそうはなっていないですから、やっぱりこの条例というのは、もともと適用していく上でおかしなものを持っているんだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-006"}]},{"id":"topic-02","title":"の専決処分の報告について、報告第１４号","agenda":"の専決処分の報告について、報告第１４号","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"この被告である借家人の方は、入居された時期はいつごろからで、家賃は幾らなんですか。それから、滞納した期間というか、いつごろからいつごろまでですか。","respondent":"浜脇住宅課長","answer":"入居の時期は平成１６年３月というふうにたしかなっております。","voiceIndex":29,"id":"exchange-007"},{"speaker":"林（和）委員","kind":"質問","question":"じゃあ、まるっきり最初から払っていないということですか。","respondent":"浜脇住宅課長","answer":"１回は滞納ということで払っていただきましたけれども、またすぐその次から払っていないという状況が続いてあります。","voiceIndex":31,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"区民住宅というと、ここに入居されるに当たり、ある程度の収入があったりとかという条件があるかと思うんですけど、原因がただ支払いができなかったとか、ケースとしてやむを得ないケースなのか、それともただ払わないのかよくわかりませんけど、その辺の状況はいかがなんですか。","respondent":"浜脇住宅課長","answer":"ただ、この人の場合には、ほとんどなしのつぶての方たちで、３月ごろから何回も催促、督促、あるいは職員が行ったりしても、会わないといいますか、払う意思がなかったです。","voiceIndex":35,"id":"exchange-009"},{"speaker":"井上委員","kind":"確認","question":"こういうふうに長くやって、結果こういうことになって、裁判費用とかいろいろかかるという状況では、形式的に事務的に淡々と行っていくというよりも、何か原因があるとか、そういうことを確認した上で対応していくことも必要なのかと思うんですけれども、そういうことはされないんでしょうか。","respondent":"浜脇住宅課長","answer":"原因というふうになりますと、やはり生活状況とか、そういったものがわからないというんですか、そういうお話し合いのきっかけすら、この方についてはなかったというふうになっておりますので、ちょっと今のところ原因というのはこれだということは。","voiceIndex":37,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"区民住宅ということは、これは家賃ではなく使用料なんですよね。もう少し違う対応を考えられることはないのか。額がどんどん大きくなっていけば、対応するほうもお互いに大変な思いをしていくわけですから、決定をしたのは品川区ですから、もう少しきちっとしたことができないんでしょうか。","respondent":"浜脇住宅課長","answer":"今後とも入居資格がありますけれども、そういった相手のそういった連絡とかについては、やはり今後とも淡々とやるような方法をこれからは考えていくことが軸になると考えています。","voiceIndex":39,"id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"有価な物、価値のある物があるかどうかもわからないし、よく言う給料の差し押さえ的なことまでできるのかできないのかという問題もあるし、その辺はどのように考えているんですか。","respondent":"浜脇住宅課長、岩田まちづくり事業部次長","answer":"現実的には今委員おっしゃったように高額なために回収できないといった場合に、やっぱりそういった給料的なものを差し押さえる方法はないかということで、今弁護士と相談しているんですが。それからもう一つは、今までたまった債権、これは別問題として、税金にかわるものと同じものですから、これはあらゆる手段を通じて回収に努力すると、この２本立てで行ってまいります。","voiceIndex":41,"id":"exchange-012"},{"speaker":"林（和）委員","kind":"質問","question":"裁判官立ち会いで７月まで延ばしたんだけど、どういうことなんですか。明け渡すのか、それともお金を用意するのか。","respondent":"浜脇住宅課長","answer":"このときの裁判官からの発言なんですけども、一つは移る予定の住宅はあると。しかし、まだそちらのほうがあいていないと。だから、住まわせてくれ。","voiceIndex":44,"id":"exchange-013"},{"speaker":"林（和）委員","kind":"意見","question":"そうしますと、７月２１日とさっき言っていたけども、それまでに回答がなかった場合、どうするのか。","respondent":"浜脇住宅課長","answer":"今のところ、借家人のほうからそういう話があったということは聞いていませんので、私どもとすれば、７月２１日は淡々と強制執行といいますか、執行してもらいたいということで、裁判所に連絡するつもりでおります。","voiceIndex":46,"id":"exchange-014"}]},{"id":"topic-03","title":"の目黒川右岸排水施設（高台部）の供用開始","agenda":"の目黒川右岸排水施設（高台部）の供用開始","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"一番最初に工事がなされない場合のときに、低地部の浸水被害は雨量がどの程度で出るのか。それから、今度一番最後になりますけど、幹線を敷くときには、どの程度の能力があるかということ。それから、ちょっと聞きたいんだけど、今日は立坑のところ、上が公園みたいになっていますよね。あそこは随分深くものすごく掘っていましたよね。あれは全部埋めたんですか。","respondent":"矢部下水道河川課長","answer":"それが、最終的に一番下の段になりますと、東京都のほうで計画基準となっております５０mm対応、それが達成されるです。ですから、ちょうど現在真ん中なんですけれども、それの真ん中程度４０mm対応ぐらいの排水能力があるというふうに考えてあります。","voiceIndex":56,"id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"今のお話だと、時間当たりの対応が５０mmに近づきつつあるという話ですね。この間問題になっているのは、短時間に、もっと短時間に１０分間で何mmとか、そことの関係というのは、例えば１０分間で何mm程度までは大丈夫なのかというのはわかりますか。","respondent":"矢部下水道河川課長","answer":"結果として、そういう効果があると。だから、どのぐらいまで耐えられるかということははっきり申し上げられませんけど、そういう実証面としてかなり強い雨でも短時間であれば、それが１時間続いちゃいますと厳しいかもしれませんけど、かなりの効果が出てくるということです。","voiceIndex":58,"id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"本質的な質問じゃないんだけど、備考の部分なんですけど、これは経路変更というか、工事のやり方も手法も含めて変更しなきゃならない中身だったというふうに思うんですけれども、どういう形のものをつくりたいから、東急電鉄と協議をやっているのかというところをちょっとだけ聞かせてください。","respondent":"矢部下水道河川課長","answer":"一応ルートをちょっと変更したいということで、東急と協議しておりますが、ちょっと歩道側の部分に少し管を寄せまして、鋼矢板という昔の杭が出てきてしまったんですが、それを避ける形で歩道側にちょっと寄せた形のルートを今考えております。","voiceIndex":60,"id":"exchange-017"}]},{"id":"topic-04","title":"の目黒川右岸低地部排水施設整備工事の事業説明会開催","agenda":"の目黒川右岸低地部排水施設整備工事の事業説明会開催","exchanges":[{"speaker":"井上委員","kind":"質問","question":"先ほど見た公園のところの広場になっているところで、もう少し奥にも公園がつながっていたように思うんですけど、公園の半分ぐらいの敷地のところなのかということと、あと車で走ったときに、その辺に保育園とかそういう施設があったかと思うんですけど、どういう車の動きになるか、工事の車両がどうなるかわからないんですけど、その辺の対策とかはどのようになっているんでしょうか。","respondent":"矢部下水道河川課長","answer":"沿道の保育園等についてですけれども、その辺につきましては、工事が契約された後、また、工事説明会等開きますので、その辺で工事車両がどうなるかとか、詳しいお話をしていきたいと考えていますけれども、基本的にいきますと、シールド工事ですから。","voiceIndex":66,"id":"exchange-018"},{"speaker":"井上委員","kind":"確認","question":"あそこから残土とかを出すというと、今日マイクロバスで走った逆方向には出られないんだろうと思うので、当然保育園の前とかということで、出す時間が日中なのか、夜間にやるのかというのはわからないので、その工事、説明会をするということだけれども、あの通りしかないんですよねということの確認と、日中そういう残土を運ぶ車とかが走るのか、それとも夜間を中心にして走るのかということと。","respondent":"矢部下水道河川課長","answer":"ただ、あそこは一応底地のほうは都市整備局、東京都のものになっておりまして、品川区のほうで管理を委託されているままでやっているところが主流ですので、復旧に当たりましては、東京都と協議しながら最終的に決めていきたいというふうに考えております。","voiceIndex":68,"id":"exchange-019"},{"speaker":"林（和）委員","kind":"質問","question":"その公園の下、立坑の工事とかは随分下まで掘るわけだね。広く掘るわけだよね。穴があくわけでしょう。さっきもあそこに埋めたのかと聞いたんだけど、歩道じゃないけども、活用する空間というものができるわけでしょう。何かそういうことは考えているんですか。","respondent":"矢部下水道河川課長","answer":"埋めるというか、公園につきましては、全部掘削するんじゃなくて、道路側部分の一部分を掘るだけですので、それ以外はトラックが出入りしたりとか、そういうための作業用地として使うという感じです。","voiceIndex":70,"id":"exchange-020"},{"speaker":"築舘委員長","kind":"質問・要望","question":"１３万３,１００円ということで、訂正いただきたいです。ほかにありますか。なければ、私のほうから２点お願いを申し上げます。なお、委員会終了後、これまでの建設委員会の行政視察の日程等について、書記から参考資料として配付をいたしますので、ご確認をいただき、そして希望をいろいろ言っていただければというふうなことでお願いをいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":28146,"voices":76}},{"id":"h17-20050704-9","meetingId":"h17-cm07","date":"2005年7月4日","dateIso":"2005-07-04","committee":"文教委員会","time":"午前１０時０４分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"続きまして、２番目の報告事項に入りたいと思います。 最初に(1)近隣セキュリティシステムのモデル実施","agenda":"続きまして、２番目の報告事項に入りたいと思います。 最初に(1)近隣セキュリティシステムのモデル実施","exchanges":[{"speaker":"山村委員","kind":"質問","question":"配ったところは一たん回収するということなんですが、その理由を知りたいのと、７月２日のＰＴＡ幹部研修会で出た質問を何個か教えていただけますか。","respondent":"市川庶務課長","answer":"１番目の回収の理由ですけれども、今回のモデル実施につきましては、この近隣セキュリティシステムの子機に、いわゆるオプションサービスというのがついてあります。","voiceIndex":12,"id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"オプションのサービスに関しては、本格実施のときにどのぐらいオプションを利用する方がいらっしゃりそうな感じの評判なのかということと、幹部研修会でのその質問には、大体どんな感じでお答えになられたのか、そこら辺教えてください。","respondent":"市川庶務課長","answer":"何を基準にこの見込みを立てているのか、そこまでは私どもは承知していないんですが、先ほどちょっと説明し忘れたんですが、基本料金が１カ月約１,０００円かかります。通常の通話料金がそこに加算されるというものです。","voiceIndex":14,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それから二つ目には、２学期から実施で、４カ月で全校に実施するということなんですが、生産が月産２,０００台ということなので、そういう事情もあるのかなと思って伺ってはいたんですけど、４カ月のタイムラグというのはちょっと大きいんじゃないかなと思いますので、その辺の事情をちょっと教えていただきたい。とりあえず２点、お願いします。","respondent":"市川庶務課長","answer":"１点目のご質問ですが、これについては、２学期以降の本格実施に向けて、現場の教員の意見も十分聞きながら、安全指導に努めてまいります。","voiceIndex":16,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それと、伺いそこなっていたのが二つあって、一つはモデル実施、まだ実施途中なんですが、規模によってと地域によってという話なんですが、これは、３週間近い検証をしているんですけれども、検証を次回の本格実施にどういうふうに持っていくのかというところを、１カ月半ぐらいあるわけですけれども、夏休みですよね。","respondent":"中島指導課長、市川庶務課長","answer":"中には、これは防犯ブザーの話ですが、例えば今、引っかかるとぱっととれるようなストラップがありますよね。そういったものを親との契約の中で導入して実施しているというところもあると聞いております。現実に、そういう取り組みは、このモデル実施をした学校の中でも出てきているところが既にありますので、そういったソフト面での対応を進めていきたいと思ってあります。","voiceIndex":18,"id":"exchange-004"},{"speaker":"南委員","kind":"意見","question":"私は、こういう時代になっちゃっていますので、治安が非常に悪くなる一方という時代になっているので、さまざまな機器を活用して子供の安全を守るということをやらざるを得ないというのは、それはそれとしてやむを得ないというふうには思っているんですけど、基本的には、そんなことが必要ないような社会にすることが基本でありますので、教育委員会のサイドでも、そういう方向で、ぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-005"}]},{"id":"topic-02","title":"の(2)平成１７年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"の(2)平成１７年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"指定校以外の区立中学校に入学するというのがだんだんふえてきていますけど、区としては、このアンケートの中身というものの考え方の問題で聞きたいんですけど、これを、希望者は全員受け入れて拡大していく方向なんでしょうか。あるいはどこかで、例えば全体の３分の１を超えたら考え直すとか何とか、そういうのがあるんですか。","respondent":"古里学務課長","answer":"通学区域の弾力化の問題につきましては、象徴的にあらわれているのは、大井第一小学校がありまして、幾ら希望が多くてもハードウエア、施設面で制限がありますから、当然そこではセーブがかかってくるということになろうかと思いますけれども、通学区域の弾力化自体は。","voiceIndex":28,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"弾力化を進めれば進めるほど、違う学区域の子供さんが入ってくると、子供の安全というんでしょうか、そうした問題だとか、地域と学校、家庭の協力関係だとか、これは繰り返し言われてきているので、親の学校を選びたいという問題と、それから安全性の問題はどうなるんだ、あるいは学校を、地域と、家庭と、学校が共同して子供たちを守っていくんだというのと。","respondent":"中島指導課長","answer":"学校が、地域とともにさまざまな安全対策の取り組みをしているところもあります。この、選択制を実施している部分と、そして子供たちの安全というものは、その中で私達は取り組んでいかなくてはならないものだと考えています。","voiceIndex":30,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"だから、学区域外から入るというのをどんどんやれば、そういう子供さんがふえていってしまう。今の説明ですと、その説明にはなっていないんじゃないかと思うので、そこらをもうちょっとわかるように説明してほしいと思うんですね。親が、学校公開なんかでその中身を、熱心な親もきっといるとは思うんですけれども、こういう選んでいく上での基準みたいなものは示されているんですか。","respondent":"中島指導課長","answer":"ただ、この保護者の方でごらんいただきたいのは、例えば１ページですけれども、下の方に「どのような方法で学校の情報を得ましたか」というあたりを見ますと、例えば今年度の部分につきましては、「学校説明会に参加して」という部分は。","voiceIndex":32,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"ほんとうは、運動会なんかでも町会が一緒に出て行って、町会と一緒になってやるようなときもありますし、それからＰＴＡの安全パトロールなんかも、文字どおり自分の学区域内だとか、お祭りがあれば集中してパトロールをやったりなんかしているわけですから、学校と地域と家庭が大事だと言いながら、これが拡大していくと、そこのところがどんどん薄まっちゃうんじゃないかなというのが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"二つあります。こういうケースです。そういう部分をどういうふうにフォローしようというふうに考えているのか。その辺が、そういう意味で、学校選択制についての不満というんですか、保護者の側での不満というのが膨れてくるような、やればやるだけ膨れてくるような気がするので、その辺はどういうふうに受けとめていこうとされているのが、この二つのケースで。","respondent":"中島指導課長","answer":"小学校の方で、施設上、どうしてもそれが可能になっていないところがありますが、今後の状況等は、また、今、新しい学校がたくさんできてきておりますので、それらを見ながら検討していくという形になるのではないかと。","voiceIndex":36,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"キャパがないから仕方がないんですということだけで押し通してしまって、公の教育というのが、理解も含めて、果たしていけるのかなというのをちょっと心配するものですから、いい機会なので、意見として申し上げたんですけど、その方には、それを受けたときには、はっきりと、住民がどういうふうに思っているのかということは、直接教育委員会におっしゃった方がいいですよということを言って。","respondent":"古川教育次長","answer":"今の兄弟関係を聞いた場合に、じゃあ、兄弟関係が優先するということになりますと、そもそもの考え方がまたおかしくなってまいりますので、大原則としては、親の学校選択について、一定のとりまとめをする。","voiceIndex":38,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"最後に聞きたいと思うんですけど、選択制のところなんですけど、住民の側から見たときに、ご近所の別の家庭は、兄弟で希望する学校に入れた。ですから、もっと慎重に、こういう問題には対応していかないと、小さな子供のときから一定のいろいろな影響を与えてしまいがちですから、その辺も教育行政としては、十分な教育的配慮が必要なんじゃないかなと思いますので、その意見だけは言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-012"},{"speaker":"西本委員","kind":"確認","question":"質問内容がどういう形であったのか確認したいんですが、例えば、親側に対したものと、小学校６年生に対したもの、これは、羅列でこういうふうになっているのか、先ほどもご意見があったんですけれども、習熟度別学習とか、合同部活動とか、その言葉が理解できるものなんだろうかと。変わっていかないとおかしい話なので、昔と状況は変わっているわけですから、その辺はどうなっているんでしょう。","respondent":"古里学務課長、中島指導課長","answer":"それで、小学校６年生、これから新１年生になる子供ですから、その子供たちが理解できるであろうという言葉を選んで、既に平成１３年度から全く同じ言葉でやっておりますので、そういう意味では。実際に、４ページにあります小学校６年生の児童への質問の項目をごらんいただくとわかるところですが、習熟度別学習につきましては、既に小学校全校で実施されておりますので、子供たちはその内容についてよく知っているところです。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"実際大井第一小学校ではそういうことがあるわけですから、それを含めて、当然学校内において決めていただくんですけれども、でも、受け入れ枠も当然あるわけですから、どれもきちんとしていって、将来にわたっての見通しを見ながら、自分の子供を兄弟としてどこにしたらいいのかというのを考えられるような、そういう情報は伝えていただきたいなととても思っているんですが、この二つ。","respondent":"古里学務課長","answer":"アンケートですので、その中でどれぐらいのことまでが探れるのかということもありますので、そういうことも含めながら、じっくり考えさせていただきたいと思います。就任したばかりで十分な回答ができませんで、申しわけございません。","voiceIndex":47,"id":"exchange-014"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"「男子校または女子校だから」ということで、実際にそれもあるのかどうかということですが、これを何年に１回見直しをしているか、私はわからないんですけれども、実態に即した質問の見直しをもう１回していただきたいと思いますし、子供は６年生ですから、確かに質問の精度を高めるということでいっぱい伺いたいのはわかるんですけれども、もうちょっと子供のたえ得る限りの質問の形といいますか。","respondent":"古川教育次長","answer":"先ほども、学務課長の方からご答弁申し上げてありますけれども、同じようなご質問をいただきましたので、アンケートを実施するかしないかということについては、実施することによって保護者の方々のご意向なり、あるいは児童、生徒の考え方を知る機会でありますので。","voiceIndex":49,"id":"exchange-015"},{"speaker":"山村委員","kind":"質問","question":"同じような質問で申しわけないんですが、例えば、問２ですか、「どのような基準で中学校を選びましたか」というところは、選択じゃなくて書かせるという方法は。","respondent":"古里学務課長","answer":"用紙にはそれぞれ「その他の理由」というところで、具体的に書いていただく回答場所はつくってあるんですけれども、アンケートとして実施するからには、類型化した質問にしないと、これはアンケートになりませんので、例えば、全部書いてもらうということになってしまうと。","voiceIndex":51,"id":"exchange-016"},{"speaker":"山村委員","kind":"質問","question":"ある意味では１０年とか、５年とか、そういうのを１回やってみてもいいかなと私は思っているのと、それから、その他で、類似点でもどのようなことが書いてあるのか教えていただけると。","respondent":"古里学務課長","answer":"申しわけございませんが、今、手元にそういうデータがまだ上がってきてございませんので、それぞれの学校に、また詳細な報告をする予定になってあります。今、職員がそれをやっている最中です。","voiceIndex":53,"id":"exchange-017"},{"speaker":"山村委員","kind":"意見","question":"アンケートは難しいと思いますが、それは文章によって全然変わってくると思うし、逆にこれは否定的なものが１個もないから、絶対悪い意見が出てこないという見方もあるし、そういう意味で、いろいろとこれからもアンケートに関してはいいアンケートをつくれるように努力していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-018"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"山村委員","kind":"質問","question":"一番出しやすい、学校の安全対策について。これは入れておいた方がいいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-019"},{"speaker":"沢田委員","kind":"意見","question":"品川も、全国的に学校改革の努力をしているんですけれども、学校の学力問題だとか、もろもろ言われている問題解決に当たって非常に努力をしているような、先進的なところがあれば。私ども、視野に入れているのは愛知県の犬山市では、品川区と並ぶ学校改革を実現しているところですし、そんなところをぜひ勉強したいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":27980,"voices":75}},{"id":"h17-20050704-5","meetingId":"h17-cm07","date":"2005年7月4日","dateIso":"2005-07-04","committee":"総務委員会","time":"午前１０時０３分～午後３時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"三村委員","kind":"質問","question":"初めてなので、いろいろ質問したいんですけれども、会社の所在地のところで品川区と入っていますけれども、品川区の会社ということで限定されているのかということと、ほかにも入札する際の条件がつけられていたら、その条件について教えていただけますか。","respondent":"鷹倉経理課長","answer":"ここで言いますと、例えば安藤・大旺建設共同企業体と載ってありますが、最初のほうは第１グループ、第２グループという言い方をしていますが、第１グループにつきましては、区内外の企業を指定しています。第２グループにつきましては、区内業者ということになってあります。","voiceIndex":11,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"今回、アザラシ館の増設工事で２カ所の観覧席の新設は別途ということでいいわけですか、合わせて契約になっているのですか。","respondent":"鷹倉経理課長","answer":"先ほど申し上げましたとおり、今回はアザラシ館の部分と観覧席の部分を二つ合わせた形になってあります。","voiceIndex":13,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"今の水族館の採算ベースと入場者の推移はどういうふうになっているかというのを聞きたいのですけれども。二、三年前に伺ったときには、大分お客さんも減ってきていて、サメの水族館もこの後どうなっているのということと、ずっとお客さんが少なくなってきている中で、将来的な規模はどういうお考えを持っているのかということ。","respondent":"藤田道路公園課長","answer":"入館者と採算ベース等の関係ですけれども、さまざまな形、いろいろな場面で状況が変わってきてありますけれども、おおむね６０万人というのが一つの境目になるかなというふうに考えております。この間のさまざまな施設の関係ですけれども、私どもの水族館も増加の傾向にあります。","voiceIndex":15,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"年間６２万人の入館者が採算ベースということで、長期的に見るとその線に近づいてきているのかなという感じがするんですけれども、心配なのは今の採算ベースを割り込んだらどうするのか、将来的には心配な点が出てくるんですけれども、これはサンシャインに任せて、そこの発想でこういうものをやっているのだと思うんですけれども、集客ということのあり方というのは。","respondent":"藤田道路公園課長","answer":"現在、私どもとしては健全運営のために、一つは入館者増加のためのいろいろな工夫をしていこうということで、夏休みに三宅島の特別展等をやろうということで検討しています。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何点か教えていただきたいと思います。先ほど、バスの中でもお話しがあったんですけれども、日本経済新聞の土曜日版に水族館のことが出ていて１位でした。５ページの配置図を見ていくと、アザラシ館が飛び出している形になります。勝島運河にぬける部分とか、水上バスに向かうところに影響が出ないのかというところを教えていただければと思います。","respondent":"宍戸施設担当課長、藤田道路公園課長","answer":"先ほど、ご視察をいただいたときに、ペンギン水槽のところの空間に出ていただいたと思います。そこからブリッジで向こう側に渡りまして、サメ水槽がある建物とは５ｍ弱空けた形で、向こう側にアザラシ館ができるという形になります。施設担当課長から説明がございましたとおり、デッキ部分はこれまで同様に通行できることになっておりますので、そういった観点から言えば、水上バス関係の通路も十分確保されているです。","voiceIndex":19,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"確認","question":"でも、これを見ていると下からどうやって、２階のデッキから出るというのはわかったんだけれども、そこから抜けるのがちょっとわかりにくかったので、その確認をさせてもらいました。売店もありますけれども、子どもたちが売店で買ったりしても、やはり向こうに入りたいと思っても、並んでいて入れない状況なんですけれども、この辺の今後の展開として何か考えていらっしゃるのでしょうか。","respondent":"藤田道路公園課長","answer":"バリアフリーの関係あるいは席数の増加、メニューの充実等も望まれている声が聞かれてあります。そういった関係から、今年度レストランについても改修をしていこうということで考えております。現在、詳細について検討中です。","voiceIndex":22,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"せっかくですから、どんどんお客さんを呼べるような形を取っていただきたいと思います。イルカショーもいつもほとんど満杯になっていて、なかなか座れない、見えないという子どもの声を聞くことがありましたので、ぜひこれからうまく活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"原委員","kind":"質問・要望","question":"もう一つ、基本的なことで大変恐縮ですが、ここの契約はアザラシ館だけでなくて、今回の１０件全部１回目で落札をされていますが、予定価格が出されてきて、それとどう連動されているのかということも含めて、なぜ１回ですぐ決まっちゃうのかなという部分ですが、教えていただきたいと思います。","respondent":"藤田道路公園課長、鷹倉経理課長","answer":"当時新たな観点から、ほかの館にないような生物の導入といったことも検討されたようですけれども、新たな生物についてはワシントン条約によって、野生動物の取引禁止あるいは稀少動物の保護などによって導入が困難である。予定価格を品川区の場合、公表していますので、あえて予定価格でできないということで全員辞退あるいは不調というようなことにもなりますし、あるいは１社だけ残るとか、通常は普通の会社の方が採用されて。","voiceIndex":25,"id":"exchange-008"},{"speaker":"原委員","kind":"質問","question":"アザラシ館のほうはよくわかりました。もう一方で不調に終わる場合ですけれども、かつてそういう例があったのかどうかわからないと思うんですが、予定価格を出された場合は不調になるケースはあまりないのでしょうか。","respondent":"鷹倉経理課長","answer":"こういう大きな案件で不調になったケースは、ちょっと記憶にありません。日常的に行われている案件で、もう少し規模の小さなもので、かなり予算的に厳しすぎたといいますか、予定価格が業者の思惑と違うという場合、不調になる場合が若干ないこともないという状態だと思います。","voiceIndex":28,"id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"そうすると入札金額のところは大体１回目で採用されるわけですから、１回目とか２回目とか書く必要もないんじゃないかなと思うんだけれども、それはあえてこういう書き方でないと書式上許されないということがあるのでしょうか。","respondent":"鷹倉経理課長","answer":"今回、誤解を招いたようなこともありますので、ここは特に書かなくても大丈夫かなと考えています。","voiceIndex":30,"id":"exchange-010"},{"speaker":"本田委員","kind":"質問・要望","question":"関連して、落札時期についてお伺いしたいんですけれども、納税者の立場から見れば、道路公団の橋梁談合の話で協定が入るというようなことで、指名競争入札に対するいろいろな見方も出ているわけですけれども、アザラシ館の落札率を見ると９７.７１％、他の議案につきましても９８％を超えるものも多いし、高い率で落札しているわけです。","respondent":"鷹倉経理課長","answer":"某公共ダムの関係で落札率について新聞紙上からいろいろ書かれてあります。今回、ご指摘のとおり、この案件については９７％とか９８％ですが、これが新聞紙上で税金のむだ使いではないかという論調については、私どもとしてはちょっと違うのではないかです。","voiceIndex":32,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問・要望","question":"適切な市場原理が働いて、なおかつきちっとした品質が確保できるという形で税金が新しく使われているという点を、納税者が納得できるような形でさまざまな税金がこういう形で利用されるということが大事なわけですから、今後ともそういう点では十分精査しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"藤田委員","kind":"質問・要望","question":"以前しながわ区民公園の中のプールの近くに軽食をするレストランをつくったらどうかと言ったことがあるんですけれども、この段階で都市公園の中で建物を新たにつくるということは非常に難しいという答弁があったように思うんですけれども、今回この中にこれだけ大きな建物を新たにつくるわけですから、どういうような申請の仕方で許可になったのか、その経緯がわかれば教えていただきたい。","respondent":"藤田道路公園課長","answer":"公園の中の建築物の関係ですけれども、都市公園法の中で、一般的な公園につきましては１００分の２ということで、２％までしか建築物として認めないことになってあります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問・要望","question":"改正があったということを、私たちも勉強不足だったものですから、そういう面では公園全体を考えて、ぜひそういうものを検討していただきたいと思います。そういう面では、私たちも期待しているんですけれども、これは要望として終わっておきますけれども、ぜひご努力をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"高星委員","kind":"質問・要望","question":"そこをどんどんアメーバーみたいに入っていって、今まであそこを出ると池があって、解放感があってというイメージが、どうもいまいち崩れてきたという気がする。厳しく積算するのもいいんだけれども、結局安いほうに落としているという中で、区民の大切な税金を扱うのはいいのだけれども、結果として安かれ、悪かれでは意味がなくなってしまう気がするので、その辺の考え方を教えていただきたい。","respondent":"鷹倉経理課長、藤田道路公園課長","answer":"その一方で、当然税金を大切に使わなければいけないということがあります。先ほど一定の金額を積み上げていくということで、当然企業者の利益も当然見込まれているわけです。最初のほうのご質問のキャパの関係ですけれども、図面上でお話しするのもなかなか難しいですけれども、一つは水族館本体、レストハウス、水族館側の駐車場につきましては。","voiceIndex":38,"id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば、あそこの中でもし火災でも発生したらどうするんだろうというような心配を、正直言っていろんなところで思いましたよ。その意味で、今の話で公園も含んでこれから考えるということだけれども、あまり既存の場所にこだわらないで大きな発想でお願いして、１００年先を見据えたような、１５年記念にやったんですから、やっていただければなというふうに思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"談合という話も出ていたので、その点で伺いたいんですけれども、品川区の場合は予定価格の公表をやってきて、契約についてかなり透明性の確保ということでは留意されてきていると思うんですけれども、今の橋梁の談合問題で、談合というより向こう側の話ですから、なかなかそこのところをどういうふうに対応するのかというのは非常に難しいと思うんですけれども、そこの点でどういう対応をされているのか。","respondent":"鷹倉経理課長","answer":"私どもも談合というのはあってはならないですので、そういう形で常日頃やっているです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"いろんな例えば情報があるとか、そういうことで発覚するのだろうと思うんですけれども、こちら側の対応としては、例えば今回問題になったのは指名競争で、相手側の話し合いの土俵をつくってしまうようなことであるし、そういうことは一般競争にしたほうが、より透明性を高めるのではないかといろいろ指摘されていますけれども、品川区の場合、そういう仕組みといいますか。","respondent":"本間総務部長","answer":"今までご答弁していますとおり、特に予定価格の事前公表につきましても、２３区でトップに入れ、なおかつ談合の可能性として指摘されております現場説明会も廃止しています。それから、契約の基本的な方法として、一般競争入札を基本とした入札方法を取っているです。","voiceIndex":44,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど高星委員の質問で要望で終わりましたけれども、下請け、孫請けのことですけれども、特に労賃が確保されていないのではないかということは私も聞きますし、やっぱり大きな問題だと思いますので、今要望されていますけれども、具体的に何か取り組んでいることはあるのか。先ほど悩ましいところだというお話でしたけれども、何か考えていることがありますか。","respondent":"本間総務部長","answer":"基本的に業者間の契約につきましては、直接区がタッチするという立場にはないということをご理解いただきたいことと、今ご指摘のありました、そこに従事する労働者の賃金等につきましては、そういうことのないようにということで。","voiceIndex":46,"id":"exchange-019"},{"speaker":"三村委員","kind":"質問","question":"先ほど予定価格の積算ということで話が出ていましたけれども、国の予算設定が甘いのではないかという話をされていたんですけれども、私は思い込みで国が積算をするときには積算基準価格になるような冊子があるというふうに聞いているんです。品川区でも同じ基準で積算をするのかと思っていたんですけれども、国と品川区では積算価格とか積算基準は異なっているという理解でよろしいですか。","respondent":"宍戸施設担当課長","answer":"品川区の場合は、民間価格等々を研究いたしまして、非常に適正な価格で積み上げた金額で出しているというふうに考えております。","voiceIndex":49,"id":"exchange-020"},{"speaker":"中島副委員長","kind":"質問・要望","question":"皆さんの質問の中で答えが出ていたんですが、ちょっと感じたので話すると、今日しながわ水族館に行きましたときに、子どもたちが歓声を上げて見ておりました。予定価格の中に、その辺のところも、本当に働く人たちに対する思いというものをしっかり取り入れた予定価格をされていると思うんですけれども、重ねてその辺のところを私たちは考えていかなければいけないということを要望したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"},{"speaker":"塚本委員長","kind":"質問・要望","question":"活発な質疑がされましたけれども、私からも伺わせていただきます。要するに、この施策に対する考え方がどうなっているのかということで新たな大きな投資をするということですから、それに対する説明がある程度必要ではないか。都の補助金がかなり入っている施策ですから、品川区のものだから品川区で勝手に判断していいのか、その辺の手続を改めて教えていただきたいです。","respondent":"藤田道路公園課長","answer":"こうしたことで、やはりリニューアルの効果といったものが十分期待できるというふうに考えてあります。今回もアザラシ館を設けることで、さらなる入館者の増加が見込まれるのではないかというふうに考えてあります。","voiceIndex":52,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一昨年のときに１回入札されて、後でジョイント・ベンチャーでやったと思うんですが、今回単独になっているんですが、何か特別な理由があるのでしょうか。","respondent":"鷹倉経理課長","answer":"ジョイント・ベンチャーでやるものというのは、一定の規模ということがあるわけですが、今回たまたま大きいわけですけれども、基本的には外構等グラウンド整備ですので、ジョイント・ベンチャーを組まなくてもいいだろうという判断でこういう契約になったです。","voiceIndex":66,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"このときにＪＶで３社で入っていたと思うんです。このときも第１ランクの会社だけになっていて、第２、第３が入っていないという疑問があったのと、外構工事の全体論で聞いている話では、最初に本体工事を取った業者が外構もそのまま入っているよという話が今まで何回か説明を受けたと思うんですけれども、その辺はどうしても本体工事をやった方が多いというのは、技術的にはどうなんですか。","respondent":"鷹倉経理課長","answer":"基本的に外構は切り離されるというのが通常の考えですが、今回どちらかというと切り離しにくい部分があるということで、本体工事をやった大成建設(株)が金額的にも取りやすかったのかなということも考えられると思います。","voiceIndex":68,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然、入札ですので落札価格が低ければ全く問題ないと思うんですけれども、その辺のところがどう精査されているのかなと疑問を感じているところですけれども、よくチェックしていただきたいということの要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"},{"speaker":"藤田委員","kind":"質問","question":"水はけが非常に悪くて困るんだという説明があったのを記憶しているんですけれども、今回はそういうような対策が十分取られているのではないかなと思うんですが、環境に配慮した外構になっているのかどうか、この辺はわかりますでしょうか、わからなかったらわからないでよろしいんですけれども、そういう説明があったのを記憶があって質問しているんです。","respondent":"宍戸施設担当課長","answer":"ここにつきましては試行というか、生徒たちが使ってもどういう頻度でやれば、あるいはどういう芝の種類を選べば長持ちするかということで実験しているところでございまして、グラウンド周辺を芝張りにしているというのが、環境に配慮しているところだというふうに思ってあります。","voiceIndex":72,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"細かいことですけれども、伺いたいと思います。通常の小学校、中学校の改築あるいは新築の場合と小中一貫校の場合というのは、国あるいは都からの補助金だとか、そういう関係では変化があるのかどうかということと、今回の場合、国あるいは東京都からの補助金はどういうふうになっているのかお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"ただ、小中一貫校の場合は、申し上げるまでもございませんけれども、小学校と中学校がセットになりますので、そういった意味では小学校と中学校を合わせてワンセットということで補助の対象になるということで、基本形は変わりません。","voiceIndex":80,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"建物は一つですけれども、要するに小学校分、中学校分で出てくるということになるわけですか。","respondent":"日下部企画財政課長","answer":"基本的には、そういうことです。例えば、今回は４階建てだとすると、小学校相当分は１・２階、中学校が３・４階ということであれば、それぞれ小学校分、中学校分ということで合わせて補助金が交付されるという仕組みになってあります。","voiceIndex":82,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"プールの件ですけれども、温水プールという話で、夏になると天井を開けてという説明だったんですけれども、そういうプールにする目的と温水プールにするときの熱源だとか、ランニングコストがどうなるのか、利用は小中一貫校ですから小中学校でやるのか、どういうふうになるのかわかりますか。","respondent":"宍戸施設担当課長","answer":"温水プールにした場合の費用ですけれども、設備工事費としては約５,０００万円余のアップになりますけれども、ランニングコストについては、使用頻度その他によって大分変わるということで算出してございません。","voiceIndex":84,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういうものに対して、区長部局ではいろいろ国に要望をしたりしているのだろうと思うんですけれども、小中一貫校あるいは一貫教育の問題については、教育委員会はどんどん進めていますけれども、区長部局としてはどういうふうに考えていますか。区民の意見だとか要望だとかも含めて、どういう認識なのかお伺いしたいんですけれども。","respondent":"濱野助役","answer":"先ほどの水族館では、アメーバーとかタコ足とかという形状のことにも係わってまいりまして、それはこの中でお示ししている図面についてのご質問ということで、いろいろお答え申し上げましたけれども、小中一貫校教育云々については、もう既に予算審議を終えて。","voiceIndex":86,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"意見","question":"その段階に来ているのは承知しているんですけれども、やっぱり私は小中一貫校、一貫教育されていくというのは、住民の合意を得ていない中でどんどん進めるというのは問題だと、改めて反対していきたいと思います。百歩譲っても大崎地区でどうなのか、やっぱりやってみた効果、評価が全くない。私は反対の態度を表明しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"外構工事が大崎地区でございましたけれども、この件に関しては外構工事がこの中に含まれているのでしょうかというのが１点。それから、先ほど視察させていただきましたけれども、解体されていました。仮設工事も終わっている段階で、この金額というのは幾らぐらい、仮設工事と解体部分の金額がどうなっているか教えていただきたいと思います。","respondent":"鷹倉経理課長","answer":"校舎の解体工事ですが、６,０４０万円ということでやってあります。それから、仮校舎というお尋ねだったかと思いますが、仮校舎につきましてはリースということでやってございまして、１カ月７００万円ちょっとということで、２１カ月分を今回予算計上しています。","voiceIndex":89,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えば、今度の契約案件の中に、ここだけではないと思うんですけれども、流れ方で確認させていただきたいのですけれども、新規で契約する段階において、契約前に壊したり、建物を解体したり、仮校舎をつくりますね。もし議案が通らなかったらどうなってしまうのかと、その辺はどう考えたらいいのですか、単純な考え方で、その辺がどうなるのかなと思って、流れ的なものが。","respondent":"鷹倉経理課長","answer":"確かに、ご指摘の点があるわけですが、当初開校年度を目標に予算をご承認いただいて、それに並行するような形で解体なり、校舎のリースなどが進んでまいります。本当に管理的にやらせていただいているのが現状だと思います。よろしくお願いしたいと思います。","voiceIndex":91,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう１点、完成時期の問題ですけれども、平成１８年１２月に完成だったと思うんですが、１２月に完成すれば、卒業するまでに移転したいなということが前提だと思うんです。一昨年の臨時会の中で、やはり完成時期が台場小学校が卒業までに使えるようにしてあげたいという話があったと思うんです。どうしても完成時期はずらせないような状況に、今の生徒のためにぜひ日程的な調整もお願いしたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-034"},{"speaker":"高星委員","kind":"質問・要望","question":"せっかく税金を使って、高いお金を借りていろいろと契約確定する。それを議会として、少しでもいいものと思っての思いなので、少しお許しいただきたいなというふうに思うんです。そういう機械になるんですか。確かに、水そのものは循環させてきれいになるかもわからないけれども、床についた汚れをどうやって除去していくのかというのがわからないので、納得できるように説明していただきたいと思います。","respondent":"宍戸施設担当課長","answer":"今のご指摘の床の汚れの部分ですけれども、ほかの事例等々を研究して、実際に工事するまでの間に精査してまいりたいと思いますけれども、汚れそのものというものに関しましては、研究させていただきたいと思います。","voiceIndex":94,"id":"exchange-035"},{"speaker":"高星委員","kind":"意見","question":"可動式の床の部分はさしたる問題じゃないと思うんですが、あれが動くというのはすき間があるから動くんですね。底の部分。だけど、可動している一番下の底のこすらなければ落ちないような汚れは、どうやって処理するのかということは大事なことだと思うのだから、せめてプールと一般的に言うと、髪の毛が抜けたり、いろんなものがあるものだから、それを気にしたいなと思うんです。","respondent":"宍戸施設担当課長","answer":"こういったような可動式の床を採用している現場は既にありますので、そういうところも含めて調査研究させていただきたいと思います。","voiceIndex":96,"id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"電気設備工事のところで、学校のセキュリティについて、出口をどういうような形でするのかわかりませんけれども、学校全体でセキュリティが保てるような電気設備を考えていらっしゃるのか、そこだけ聞かせていただきたい。","respondent":"宍戸施設担当課長","answer":"それと電子錠のシステムと連動させて、そこで開け閉めについての管理をするということをやってあります。それとテレビカメラを校門の付近、それから出入口付近に設置いたしまして、それぞれ３カ所で監視できるようなシステムにしているというようなセキュリティ関係です。","voiceIndex":98,"id":"exchange-037"},{"speaker":"原委員","kind":"質問","question":"そうすると、例えば温水プールの開閉とか、学校開放の部分もいろいろ出てくるだろうと思うんですけれども、そういったところは出入口を別にしてやるのか、それとも今みたいな出入口は１カ所ですという話になると、そういったところの対応の仕方はどうなるのか教えてほしいと思います。","respondent":"宍戸施設担当課長","answer":"動線を分けるということ、それからどういうケースを想定して、やはり同じようにセキュリティチェックをしていき、電子錠で管理できるようなシステムにするというふうに進めております。","voiceIndex":100,"id":"exchange-038"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、その辺のところの管理はおそらく大井地区でもやられている部分だろうと思うんだけれども、もうちょっと明確にしておいていただきたいなと。これは要望しておきますけれども、ここは管理できるけれども、ここのところはできない、あるいはここは後からつければいいという話ではないのではないかなと思いますので、何かお答えがあればお願いします。","respondent":"宍戸施設担当課長","answer":"エリア分け等々について、細かい部分についてということで、基本的にそういうセキュリティシステムを取っていくということは決まっております。","voiceIndex":102,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、セキュリティが出てきた中で、２１ページの１階平面図の右上のほうに駐車場が４台分確保されております。大崎地区のときも駐車場をつくらなければいけないという話があったと思うんですけれども、目的としては、駐車場４台分のスペースは何のスペースとして考えたらいいのですか。","respondent":"宍戸施設担当課長","answer":"この駐車場については、学校で決められたりしているんですけれども、これについてはある程度業者や何かが来校するとき用の駐車場という位置づけで、門扉の外側にあたりますので、建物の中というわけではなくて、供用部分の一部のような形で駐車場が設けられております。","voiceIndex":104,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ここは入り口も入っていますね。心障の方の駐車スペースも別にありますし、ちょっと気になったので、そこにまた自転車置場４２台分というのがあるので、どうもあまり納得していないのでどうなっているのかなという気がするんですけれども。自転車というのは地域開放なのか、まさか生徒が置いていく場所ではないと思うんですけれども、４２台というのはそんなに要るのかなという気もしたので。","respondent":"宍戸施設担当課長","answer":"自転車置場の４２台に関して言えば、地域開放をした場合の台数を設けているです。駐車場については、学校関係の出入りの業者が置くスペースということで、場所としてはぐるっと回って入れるようになろうかと思います。","voiceIndex":106,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この中の空気調和設備工事ですが、大井地区小中一貫校と全部ＪＶが一緒なんですね。こういう組み合わせというのは、やはり区のほうである程度つくっているのか、それとも偶然なのか、どうしてなのかなと。もう一つの給排水設備工事もほとんど同じなんですね。なぜこんなに同じなのか疑問があったので、教えていただけませんか。","respondent":"鷹倉経理課長","answer":"空気調和設備工事は第１グループ、第２グループともに区内ということにしています。組み合わせは第１グループ、第２グループにエントリーした中でお互いに決めていくという性格になってありますので、そういう結果になってしまったです。","voiceIndex":122,"id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"要するに、業者同士で一緒に組もうということで、こういう結果が出てきた。ただ、一覧で両方を見ると、全く同じだったので、どういう意味かなということで、逆に給排水衛生設備工事は１カ所だけ違ってほとんど一緒だったので、そんなに業者同士で組み合わせがきちんとしているのかなということで伺いました。別に金額的なものではなく、理由がわからなかったので、それはわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-043"},{"speaker":"藤田委員","kind":"質問","question":"先ほど、５,０００万円プラスすればできるという話だったんですけれども、この際、５,０００万円プラスしてでも、ここは温水にすべきではなかったかと思うんです。そういうようなことも考えて、ぜひやるべきではなかったかなということが一つ。これだけの建物ですから、大変な車の量になると想像するんですが、この辺はどうなっているのか２点お聞きしたいと思います。","respondent":"宍戸施設担当課長","answer":"工事をどういうふうに進めればいいかというのは、私どものほうも非常に苦慮しているところですけれども、今考えているのは幾つかルートを幅広く設けまして、あまりどこかだけにご迷惑をかけるということではなくて。","voiceIndex":125,"id":"exchange-044"},{"speaker":"藤田委員","kind":"質問・要望","question":"プールの件については、１億数千万円の話になるんだというのはよくわかりますが、やはりこれからの学校は地域に対して開放していくという、学校を利用してもらうというような考えが必要ではなかったかなというふうに思います。それから、現在でもやはり緑道に駐車をして、地域に対して迷惑をかけているわけですので、できれば敷地内で対応できるような体制を要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-045"},{"speaker":"高星委員","kind":"質問","question":"今の話と関連するんですけれども、工事単価というのは、例えばこの間台場小学校をやったときに、あそこの取り付け道路はどうなんですかと、１０ｔ車も入れない。これは全部工事の積算単価に入ってくるんです。今になって、規制を解除するかしないかというようなことがはっきりしないで何で積算になるのか、その辺がわからないんだけれども、どうなんですか教えてください。","respondent":"宍戸施設担当課長","answer":"ここにつきましては、重量規制を解除するという方向で、荏原警察署とも既に１年ぐらい前から協議をしていますし、説明会自体も３ｔ車規制解除ということで２月に開いております。","voiceIndex":128,"id":"exchange-046"},{"speaker":"高星委員","kind":"確認","question":"大事なことなので確認したいんですけれども、例えば西大井駅のほうは確か６ｔ車規制がかかっていると思ったけれども、今度は１０ｔの規制解除という意味を説明してもらいたいんですけれども、１０ｔの規制解除というのは、どういう意味なんですか。今、１０ｔの規制がかかっているんですか、それを解除するんですか。","respondent":"宍戸施設担当課長","answer":"具体的には、実際に工事会社がはっきり決まりまして、工事会社のほうで具体的にさらに警察署と詰めることになると思いますけれども、いずれにいたしましても解除していただけるという方向については、荏原警察署と協議済みというか。","voiceIndex":130,"id":"exchange-047"},{"speaker":"高星委員","kind":"質問","question":"だから、最大積載量１０ｔというのは、あの手のトラックは大体２０から３０ｔ以上ありますから、そうしますと今言われたように２０ｔくらいまでなら通行可のような規制解除の話を取るのだろうと思うんけれども、今はおおむね取る方向でという、おおむねが具体的なところ積算の中で、おおむねで済む話になっているのかどうか、そんなものでいいんですかと聞きたいんですけれども。","respondent":"宍戸施設担当課長","answer":"第二延山小学校については、おおむねという言葉はまだ施工業者が決まっていないので、そういう言い方になりましたけれども、ほぼ２０ｔ車は通行させていただけるということで、荏原警察署からも了解していただいていると考えています。","voiceIndex":132,"id":"exchange-048"}]},{"id":"topic-02","title":"第５０号議案、職員用回転椅子の買い入れ","agenda":"第５０号議案、職員用回転椅子の買い入れ","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"我々も仕事をやっていますけれども、そんなにいい椅子を使わせてもらっているのかなと。高いのはわかります。耐用１５年と見ていますけれども、１５年も耐用する椅子でなくても、もっと次で切り替えるものもできるのではないかなという気がするんですけれども、そういう考え方というのは、１５年という基準は何が１５年なのかという、その辺が教えていただけますか。","respondent":"鷹倉経理課長","answer":"そうすることによって、１年間当たり幾らということも出てまいろうかと思いましたので、できるだけ丈夫で、毎日座り続ける椅子ですので、できるだけ丈夫で、途中でがたがたしないような形のものを選んでいるという考え方です。","voiceIndex":144,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、係員用は３万１,８９２円ですけれども、この椅子は１脚単価で買うともっと高いものがこういうふうに下がっているという判断でよろしいんでしょうか。","respondent":"鷹倉経理課長","answer":"通常、競争入札であれば安くなるということがありますが、ただ予定価格を公表した場合にどうなんだということが実はあります。したがって、私ども今回落札率は九十数％になってありますが、予算は通常の価格からかなり切れ込んだ形のものを設定しています。","voiceIndex":146,"id":"exchange-050"},{"speaker":"三村委員","kind":"質問・要望","question":"一括で２,０００脚というふうに、さっき入札の方法というふうにおっしゃっていましたけれども、こういうやり方しかないんですか。先ほど鈴木真澄委員からも言われていたみたいに、期間を決めて一括でがんというのではなくて、その部署ごととか個別に使えなくなったり悪くなったらかえていくという方法は高くなってしまうのですか、その辺のところを教えていただきたいと思います。","respondent":"鷹倉経理課長","answer":"今回はメーカーだけではなくて、販売店がいろいろ参加できないといけないのが制限付一般競争入札ですので、門戸を広げているということです。前回指名競争入札で、値段的には今回より物価的にもあれでしょうけれども、若干今より安かったのかなと、最終的な落札額としては。","voiceIndex":148,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もちろん職員の方がちゃんとできるような形ではいいんですけれども、さっきの１５年にこだわるんですけれども、民間でいうと減価償却ではないですけれども、一般的に民間企業ですと減価償却を考えた場合、椅子は何年ぐらいを考えているのか、調べていないのでわからないんですけれども。当然、１５年という計算というのは、その辺が入っているのかなと。１５年のところが引っかかっているので。","respondent":"鷹倉経理課長","answer":"２０年でも３０年でも使えれば一番いいわけですけれども、交換部品が供給できるのか。最長というのは確認したところ１５年、もう少し長いところも当然あるわけですけれども、１５年がラインだなと。したがって、１５年以上のものでという形で説明させていただいたです。","voiceIndex":150,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１５年使えということではなくて、もっと短くてかえてあげてもいいじゃないですかというのが感覚なんです。逆に言うと、例えば８年後にもう１回同じようなものを買ってもいいのではないですか。そのほうが職員からしたら、１５年も使わなければいけないというより、同じ金額でできるのだったら、そこで買ってあげたほうがいいのではないかなと、そっちの感覚なんです。その辺で何で１５年なのと。","respondent":"鷹倉経理課長","answer":"確かに、１５年というのは結構長いわけですけれども、しかし現に我々が座っているものは、新ししく座ったときにはいいなと思いましたけれども、あっという間に１７年経っているです。実際問題、毎日仕事をしていく中で１５年もあっという間に過ぎてしまうかなと思います。","voiceIndex":152,"id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"２,０００脚ぐらいの数になりますと、例えば今回はイトーキですけれども、いろいろなメーカーと直に話というのはないのでしょうか。私どもだと、大体このぐらいかかると、メーカー直であるイトーキと交渉にあたるというのが普通のやり方かなと思うんですけれども。","respondent":"鷹倉経理課長","answer":"今回は物品４,０００万円以上ということで、初めてこういう案件が出てまいりましたので、あとでどういうものが出てくるかなかなかないと思うんですが、物品でこれだけのものはまずないだろうということで、制限付一般競争入札でやりました。","voiceIndex":154,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1688#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":42781,"voices":169}},{"id":"h17-20050705-6","meetingId":"h17-cm07","date":"2005年7月5日","dateIso":"2005-07-05","committee":"区民委員会","time":"午前１０時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成１７年度区民まつり","agenda":"の平成１７年度区民まつり","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしますが、今年でもう何回目かになる区民まつりですが、何か今年の目玉とか、何回もやられているんですけれども、去年とこういう面で変えたようなものはあるんでしょうか。","respondent":"田村地域活動課長","answer":"私も昨年、一通り回らせてもらいましたけれども、それぞれ特徴があります。例えば荏原第四なんですが、一番下から２段目に書いてありますけれども、花火がメインで、その花火を期待して、地元に花火師の方がいて、手づくりでやっているんです。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"のキャリア支援塾の開設","agenda":"のキャリア支援塾の開設","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"その確認を１ついただきたいのと、それから無料ということですので、裏返しで言えば、こういう高い人件費とか場所代、すべて行政の負担になってくるわけですよね。そういうことを冷静に考えていくと、２０名枠、この考え方、例えばこれをふやしていくのか減らしていくのか、それからこの事業そのものをこれからどういうふうに将来展開をしていくのかということも含めて確認いただきたいんですけれども。","respondent":"金子産業振興課長","answer":"ただし先ほど申し上げましたとおり、雇用政策そのものは国あるいは東京都の施策ですので、その意味ではそちらの施策の推移を見ながら、連携できる部分については連携しながら実施を、今後の展開については考えていきたいと考えています。","voiceIndex":11,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"それからそれで聞きたいのが、ニートとか、いろいろ言われている問題も、そんなに例えば品川区でも深刻なんでしょうかね。そういう働きたいけど働けないというんですか、能力はあるけど働けないというんですかね、表現は難しいんですけど、要はここまで予算を組んでやらなきゃいけないぐらいに問題は深刻化しているんでしょうかというの確認なんですけれども、いかがでしょうか。","respondent":"金子産業振興課長","answer":"一方では中小企業の振興というのが区の非常に重要な施策でありますので、その意味ではこの両者をあるべき形に持っていくというのは、国・都と連携しながら、区のやるべきことというのを見定めてやっていくということが、私どもにとっては必要なことだろうと考えているところです。","voiceIndex":13,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後の方におっしゃっていた区内の中小企業の支援策の一環としてということですけれども、私たちの考え方としては、ニートの問題とか、働く意欲がない青年の問題というんでしょうかね。それはまずは個々人の問題だと私たちは思っているんですよ。ですから、区内中小企業の支援策ならば、その成果をどう考えているかということも答弁をお願いします。","respondent":"金子産業振興課長","answer":"後段の方の区内のいろいろな中小企業との接点はどうかということですけれども、私どもとしましては、この趣旨を考えたのが区内企業の就業体験ですけれども、そういう意味では中小企業のＰＲということも効果があることかなと思いますので、今後の塾の展開の中で。","voiceIndex":15,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"キャリア支援塾ということですが、この施策についてキャリア支援塾とつけた理由を教えてください。","respondent":"金子産業振興課長","answer":"キャリア支援塾という命名のご質問ですけれども、私どもとしましては、事業の目的、内容については先ほどご説明したとおりですけれども、それをどういうふうに表現していこうかというところでは難しい部分もあるかなと考えておりまして。","voiceIndex":17,"id":"exchange-005"},{"speaker":"藤原委員","kind":"意見","question":"受け入れ期間が３日間ですよね。『体験しよう！』も３日間ですよね。そのうちの３日間か。とにかくそんなに日数ないですよね。それがキャリアになるのかということと、それともう１点がいわゆる人材、働き手で困っている中小企業と、働きたいという方をマッチングさせることが目的なんですが、民間の人材派遣とこれの大きな違いというのは何かということなんですけれども。","respondent":"金子産業振興課長","answer":"３日間というこの就業体験のことだと思うんですけれども、これがキャリアの支援になるかというお尋ねかと思いますが、私どもこのキャリア支援塾というのはあくまでも１つのとっかかりというふうに考えておりますので。","voiceIndex":19,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"の欄なんですけれども、区内企業のご協力と書いてあるんですけれども、今、何社ぐらいが協力しますと言っているのかということと、それとマッチングのことの具体的なことというのをお伺いしたいんですけれども、この塾に入られて、Ｓｔｅｐ.３で区内企業で体験をして、ぜひ体験した会社に入りたいというふうになったときに、受け入れは可能な企業が多いと思うんですけれども、その辺。","respondent":"金子産業振興課長","answer":"就業体験の企業ですけれども、私どもとしては工業系、商業系含めて約２０社のご協力をいただくことになっています。これはオプションとして考えているところなので、実際に何人の方がご希望されるかわかりませんので、２０社全部ではないということがあります。","voiceIndex":21,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"２点ですが、７月１日から始まっていますけれども、まだ３日しかたっていないんですけれども、今のところ応募がどれぐらい来ているのかということと、あとは必修コースのＳｔｅｐ.１で８月４日の１６時から合同就職面接会ということで、ハローワーク品川の協力で面接会をやるとなっていますけれども、ここで例えば面接して、お互いがいいなとなったときには、このＳｔｅｐ.３はやらなくてもいいのか。","respondent":"金子産業振興課長","answer":"具体的な応募の数ですけれども、先週の段階でお問い合わせが２件ありまして、２件申し込まれています。それが今のところの件数ですね。","voiceIndex":23,"id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"そうすると、例えば今、２件お申し込みがあった方でも、必修コースＳｔｅｐ.１をやった段階で本人がＳｔｅｐ.３に行かないということもあっていいということでしょうか。","respondent":"金子産業振興課長","answer":"今のご質問ですけれども、Ｓｔｅｐ．２、Ｓｔｅｐ.３に関してはオプションで自由に選択になっていますので、この部分については第１段階のところで一定の就職が決まって、インターンシップはキャンセルしたいということがあれば、それはそれで尊重するといいますか。","voiceIndex":25,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問したいのは、目的に働く意思を有しながらというところで、この若者がふえているというところですけれども、現在の若い人の雇用環境の実態、完全失業者数の世代別の推移ですとか、あと高卒や大卒の就職率の推移ですとか、この１０年、２０年、どういう変化が生まれているのか、まずそこをちょっと説明していただきたいのと、あと中小企業の人材確保の点ですけれども。","respondent":"金子産業振興課長","answer":"もう１点は中小企業の人材確保ということですけれども、これにつきましては、品川区の実態調査を以前実施しまして、その中で中小企業の経営者の方々が抱えている悩みの大きなものの１つとして。","voiceIndex":27,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"大学の学生課というんですかね。ぜひそこに行政が間に入ってやってほしい。こういう経験がありますので、ぜひキャリア支援塾の新しい事業のノウハウを生かしていただきたいなと思うのが１点ですけれども、要望で結構です。意欲や力は必要ですよ。改めて伺いたいのは、働く意識を有しながら、就職の機会に恵まれない若者がなぜふえてきているのか、ちょっと教えていただければと思います。","respondent":"金子産業振興課長","answer":"というのは、フリーターの中では、将来的なことを考えて当面フリーターをやっているという方が結構多いわけで、それはある調査によればフリーターの中でも６割ぐらいに上がるわけで、そういう意味では、それでも自分の生活が現状できているというところで。","voiceIndex":29,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"失業者の方やニートの方のあせり度というんですかね、そういうことをおっしゃっていましたが、今、ベストセラーにもなって雑誌やテレビでも紹介されましたけれども、ニート・フリーターに学ぶ失業者と。簡単に言いますと、失業者よりもニートの方が仕事をしていないことへのあせりというのは多いんですよね、２倍ぐらい。採用枠の全体が狭まっている中で、自分のやりたいことや適性が見えなくなっている。","respondent":"金子産業振興課長","answer":"その意味でこういったことを中小企業振興策と絡めてやっていくというのが、現在の私どもの施策ですので、雇用そのものの施策は国・都が所管をしているところですので、そういったところの調査等々も見ながら、私どもは施策を実施していきたいと考えています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"さっきも本で紹介しましたけれども、日経・経済図書文化賞を受賞したらしいんですね。なぜかというと、よくニートやフリーターの話、この問題になると、本人の努力不足だとか、必ずこういう議論というのがあるんですよ。最後に伺いたいのは、区政モニターとか、直接行政も話を聞く仕組みがありますよね。どういうところでそういう声をくみとっていくのか、お考えがありましたら教えていただきたいと思います。","respondent":"山田区民生活事業部長","answer":"一般的なことについては広報、広聴の全体的な中で考えるし、または世論調査等が活用できるのではないかと思いますけれども、あくまでもこのキャリア支援塾、このカリキュラムを見ていただければ、いわゆる動機づけ程度の部分の内容かと思います。","voiceIndex":34,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうことで積極的にやっていただきたい。ただちょっと話を聞いていましたら、就業体験につきまして、会社がまだ２０社程度だというところで、もっとふやせないのか。実際２０社というのもどういうふうにふやしていったのか、努力はあると思うんですけれども、できるだけ多くの会社を、中には元気な会社もあります。もっとふやす努力を今後もしてほしいと。！ちょっとその３点だけお答えいただけますか。","respondent":"金子産業振興課長","answer":"３番目の町会の掲示板ということですが、今回町会の掲示板は考えておりませんが、私どもはこのポスターを、先ほど申し上げたとおり、若者がよく行くようなところ、コンビニエンスストアであるとか、ファーストフードのお店というところに張らせていただくように考えておりますが。","voiceIndex":36,"id":"exchange-014"},{"speaker":"木下委員","kind":"質問・要望","question":"就業体験の事業、先ほど公募ということだったんですけれども、２０社の協力を求めるという、ここら辺の反応といいますか、お願いしての２０社なのか、それともぜひ参加させてくださいということなのか、要するに１日から広報が始まって２人の方から申し込みがあった、若い人の反応は聞いたんですが、就業体験の企業の方の反応はどうだったのかという思いがありますけれども。","respondent":"金子産業振興課長","answer":"私ども、今回はこの就業体験、先ほど言いましたように定員が２０名ですので、マックスが２０名と考えて２０社の方にこちらからお願いしたという経緯ですので、その意味では会社を公募したとか、そういうことはございません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"林（宏）副委員長","kind":"質問","question":"中途半端なんですよ。それから簿記３級は３日じゃ取得できないんだよ。答えはいいですから、こういうのをやるときは受ける人にもっとアピールするような、我々に説明したときに、説明を聞いた人が、ああなるほどとわかるように、賛成か反対かは別として、なるほどとわかっていない中で質問をしているから、あっち行ったりこっち行ったり、それをお願いしておきます。さっきのファーストフードの話だけ１点。","respondent":"金子産業振興課長","answer":"商業関係の就業体験のところですけれども、１つはスーパーマーケットです。細かい店舗に関しましては、物販の部分が多いです。もう１カ所、商店街連合会という事務局が私どもの建物の中にありますが、そちらでも就業体験していただこうというふうに考えてあります。","voiceIndex":40,"id":"exchange-016"}]},{"id":"topic-03","title":"の品川清掃工場更新事業に係る事後調査報告書（工事の施工中その２）","agenda":"の品川清掃工場更新事業に係る事後調査報告書（工事の施工中その２）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"勉強不足で申しわけないんですけれども、平均値の測定方法だけ教えてください。","respondent":"田中環境課長","answer":"それぞれ検体を採取する形になります。平均値の部分については、１日２４時間、１時間ごとにとっていくという形で２４回とって、それを２４で割る。それで平均値を出すという形になっております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけなんですけど、すべて基準値を上回ったのは自動車の影響ということになっていましたよね。この部分はわかるんですが、観測地点が建設仮囲いの外ということで、すべて道路周辺にありますよね。それはある意味自動車の騒音・振動を出すのは当然の結果であるはずですから、確認したいのは、工事に係る大気汚染、騒音、振動の調査であるならば、この観測地点をもっと中にするべきでしょう。","respondent":"田中環境課長","answer":"環境アセスメントではかる場所が決まっていまして、敷地境界ではかるということになっております。","voiceIndex":48,"id":"exchange-018"}]},{"id":"topic-04","title":"川崎天然ガス発電所に係る環境影響評価準備書に対する区長意見","agenda":"川崎天然ガス発電所に係る環境影響評価準備書に対する区長意見","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２点だけなんですが、広報とか住民周知はどういう形で今、説明というんですかね、教えていただきたいと思います。微量であっても窒素酸化物というのは出るわけですよね。夏なんかは光化学スモッグについてスピーカーで流れますけれども、ああいう影響というのはどう変わってくるのか。","respondent":"田中環境課長","answer":"２点目の窒素酸化物の寄与度ですが、先ほどご説明しなかったところですが、下のところに寄与高濃度日というところがi、iiとそれぞれありますが、理論値では０.０００２４ppm、実測の高濃度日ですと０.００００１ppmということで、若干はふえますが。","voiceIndex":54,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"若干はふえるけれども、影響は少ないという話ですが、光化学スモッグ、今の状態ではまだ今年は聞いていないですけど、夏になるとよく出されますよね。家に入ろうとか、ありますよね。そういう影響が出てくるんじゃないかなと。微量であってもふえるわけですから、それで影響が少ないというのもよくわからないんですけれども、そこだけちょっとお願いします。","respondent":"田中環境課長","answer":"ただ、全体的にＮＯｘ規制等を含めまして、全体的に東京の空気はよくなる、大気汚染はよくなってきておりますので光化学スモッグの発令等は少なくなってきております。","voiceIndex":56,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"同じ業者が京都の方でも、正確じゃないかもしれませんけれども、１５カ所ぐらい葬祭場をつくっているというのをちょっと聞きまして、各地で同じような、土地柄、向こうはお寺が多いですから、何でこんなお寺が多いところに葬祭場なんだというお話もありながら、町並みと商業地域とあと住環境という中で、同じ課題を背負られているという話を聞いたので、ぜひ斎場問題についてというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"今、所管事務調査で産業振興でしたっけ。そのことが出ておりますので、具体の都市名までは絞り込めていませんけれども、いろいろなケースがあると思います、この産業振興については。それは所管事務調査の一環としても、それから、品川区内の産業振興の一環としても非常に役立つことだと私たちは思っておりますので、産業振興の観点から、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-022"},{"speaker":"武内委員","kind":"意見","question":"都市は特に私も調べていませんが、毎回取り組んでいるようですけれども、商店街の振興ということで、そういった元気のあるような商店街、または空き店舗が品川区内の商店街で出てきて、そういったものをうまく活用して成功しているような例があれば、そういうところに行きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"視察となりますと、対象として品川区の今の現状とあまり離れた地域は難しいんじゃないかと。こちらの参考になるような状況というのは、ほかの委員会でもあったんですけれども、なかなか難しい。見てみたいなという感じでいます。地名云々というのはなかなか今出ないんですけど、できれば都内で、品川区に類似しているような場所がすごく勉強になるんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-024"},{"speaker":"木下委員","kind":"質問","question":"ですから、なかなか産業振興策といっても、例えば今までと違った雰囲気、今までの違った沖縄のものが食べられるだとか、沖縄情緒を味わえるだとかということでかなり成功していると言っています。それと絡めて、沖縄の都市も行ったらいいんじゃないかというふうに僕自身は思っている次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは直接には街づくり特別委員会になると思うんですが、災害に強いまちづくりの中で、たまたま品川区には東京都の地域危険度の中で上位に入ってしまったところがあるわけなんですけれども、そのことについては当然区としてもいろいろとやっていただきたいと思うんですけれども、それは先進事例として取り組んでいる自治体、そういうことについては同じような悩みもあると思われますので、それに対すること。","respondent":"本間委員長","answer":"ほかに。よろしいですか。ただいまの意見を参考に正副で調整し、次回以降お示しします。なお日程についてですが、調査項目も出てまいりましたので、ここで日程についてご意見をいただきたいと思いますが、いかがでしょうか。","voiceIndex":71,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"意見","question":"日程なんですけど、普通ですと、本会議、委員会の絡みで決まると思われますが、いつがいいということじゃなくて、例えばその事業を展開している中で、視察をする中で、そのときしか見えないこととか、そのときしかやっていない事業がもしあるとするならば、それを優先に考えていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":25511,"voices":77}},{"id":"h17-20050705-7","meetingId":"h17-cm07","date":"2005年7月5日","dateIso":"2005-07-05","committee":"厚生委員会","time":"午前１０時０５分～午後１２時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今までの福祉のサービスが充実をしていくということで受けとめていますけれども、今までのこういった給付事業がどうだったのかをお伺いしたいのと、どのくらい負担がかかるのか、自己負担の部分をもうちょっと詳しく教えてください。","respondent":"谷田部健康課長","answer":"先ほど、冒頭説明申し上げました、小児慢性特定疾患治療研究事業というのが次官通知で都道府県事業として行われてございました。これはあくまでも治療の研究ですとか、実際の医療の支給です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"自己負担のところが所得制限があるということですけれども、要綱をいただいたのですが、この辺で、今後のことですけれども、例えば、無料になる方がどのくらいいるのかが把握されているのかどうかと、疾患によって使われる用具っていろいろありますよね。一つ一つについて、利用料金が定められているということなのでしょうか。その辺をもう一度。","respondent":"谷田部健康課長","answer":"費用徴収基準です。先ほど補装具と同じ基準を横引きしているということでございまして、該当する対象者という話ですけれども、現在私どもに問い合わせが来ているのが、頭部を保護するいわゆるヘッドギアでの方が１件、現在来ております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"確認","question":"確認しますけれども、いただいた徴収基準表を見ると、徴収基準というのが所得制限別にずっと書かれていますよね。この金額を全額負担するということなんでしょうか。","respondent":"谷田部健康課長","answer":"残りの７万８,０００円は公費で見ますと、そういう関係になってありますので、例えば２万円のものを、２万２,０００円の徴収基準で払うとなると、それは２万２,０００円払わなきゃなりませんから、ご自分で２万円を負担する、そういう関係にもなります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"何点かお聞かせください。小児慢性疾患１１疾患群、５１０種類というので、主なものはどういった疾患があるのか。というのは便器と書いて、特殊便器と２つ書いてあると、それから特殊尿器とか、その人にとってはこういうものが使いたいといっても、これがここに入っていないからだめですよというようなことがないようにしていただきたいと思うんですけれども、その辺はいかがでしょうか。","respondent":"谷田部健康課長、鶴見品川区保健所保健サービス課長","answer":"これは国が定めている要綱が１３種目ということで、品川区も１３種目を用意させていただいてあります。これまでさまざまな状況の中で、１３種目あれば在宅での支援ができるだろうということで、私どもは１３種目をそろえている状況です。小児慢性疾患の疾患群の中でのばらつきにつきましては、特に疾病構造が変わっているということはございません。ただ、小児医療費の拡充に伴いまして、申請のほうが少し減っているといったことはあるかと存じます。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"それはそれでいいんだけど、国のほうでそういう基準を決めてくるんだけれども、区のほうに来たらば、またこういうものが必要だということの対応はできないのかなということをお聞きしているんだけれども、そのあたりはいかがですか。もう一度、１３種目というから、あと１種目あるんだろうと思うけれども、それでなければだめですよという形になっちゃうのかどうか。","respondent":"谷田部健康課長","answer":"この種目の拡大という話ですけれども、これまで、昭和４９年から医療等での現場においてさまざまな研究、それから医療の研究が行われてきたという実績の中で、在宅で生活を支援していくための必要な品物ということで、１３に絞り込んでいるというものですので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に定員のところの３倍も園児さんを預かっているところがあるという、この辺がちょっと、私は私立の幼稚園がどうなっているかよくわからないのですが、２１園中、半分が定員をかなり超過して受け入れているところがあるので、まずその辺の数字の考え方というか、どういうふうになっているのか、基本的なところを教えていただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"そういう部分については、設置基準の中で、昭和３２年２月１日以前の場合と、それ以後の基準ということが基準として違ってきているということで、品川区の場合は多くが古くから設置されているということでは、昭和３２年２月１日以前に認可された園といったところが多いので。","voiceIndex":21,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"平成１７年度の５月１日現在では２１園ですけれども、廃園とか、今後廃園予定のところもあると思うんですけれども、その辺で動向がどうなっているのかと、これから多分人口が増えたりとかいろいろその辺を。私立ですから、区が関われる部分というのはそうないかとも思うのですが、その辺をどうとらえているのかというあたりが１点。お願いします。","respondent":"高橋幼保一元担当課長","answer":"委員の、そういった一方では入園者数が多くなって、一方では廃園というところで、その辺の動向はどうなっているかというお尋ねですが、今現在、先ほど言ったように、品川区総数としては９１％の方が入園されているというところで、若干の余裕はある中で。","voiceIndex":23,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど預かり保育、きんだぁくらぶを７園実施しているということですけれども、私立幼稚園の預かり保育というのは、どのくらい利用されているのか。時間帯の問題、どのくらいの時間が多く利用されているのかと、何％ぐらいの方が利用されているのか、その辺が、もしつかめましたら教えていただきたいのと、あと利用料金、それから補助金が少し変わったと思います。ちょっとその辺も教えてください。","respondent":"高橋幼保一元担当課長","answer":"利用の内容についてですが、きんだぁくらぶは品川区７園で実施していますけれども、２１園それぞれ時間帯はまちまちですけれども、やっているところは多くなっています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういういった面では、このごろ幼保一元化とかいろいろ言われていて、保育園でも幼稚園でも、ある程度お仕事している方も利用できるように、これからも変わっていくと思うのですけれども、その辺で、４時間が基本のところで、預かり保育をお願いした場合、料金的に保育園と比べた場合は、どのくらいの負担になるのかなというのが気になるんですけれども、その点１点教えていただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"料金的には保育園と比べてどうなるかですけれども、きんだぁくらぶを設置している実施園が、料金的にもまちまちであるということと、それから幼稚園の保育料についても、各自それぞれ補助金等もございまして、違うというところで、こちらの手元にはございませんけれども。","voiceIndex":27,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結構負担に感じていらっしゃるところもあると思うんです。もう一点は、経営者側が預かり保育を運営していく面で、人員的な配置とかでかなり困難があると思うので、先ほど１３５万円ぐらいというお話がありましたけれども、私はぜひ、この辺の補助金のところも拡大して、幼稚園のところでノウハウを持っていらっしゃるので、ぜひ預かり保育が広がる方向にあるといいなと考えています。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-010"},{"speaker":"川西委員","kind":"質問","question":"今の質問の続きが一部ありますけれども、人数のアンバランスという点ですが、昭和３２年の２月１日以前の認可、それ以後の認可と多少違うということはわかりました。例えば、定員の何倍ぐらいまでは補助金の対象になって認められるのかという、その基準が都と区の運営費補助金が多少ありますが、その辺ではいかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"お尋ねの人数、何人以上は補助金幾らぐらいという部分のお尋ねですけれども、ちょっとこちらには資料がございません。","voiceIndex":31,"id":"exchange-011"},{"speaker":"川西委員","kind":"質問","question":"例えばこれを見ていますと、２倍、３倍の園もあります。そういう点では、どこまで認められるのかという。限度というのはあるんでしょうか、その辺いかがですか。","respondent":"高橋幼保一元担当課長","answer":"園全体で最低でも１００m2以上ということになっていまして、学級数によって平米数が異なる。１学級については３５人までというところで設置されています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"川西委員","kind":"質問","question":"わかりました。１人当たりの平米数。それから園庭も平米数の基準があると思うんです。幼稚園の場合は本人が選択して希望するから、特段詰め込まれても、その園がいいんだということで希望されるから問題はないかと思いますけれども、その辺の監督というのはどうなっているんですか。","respondent":"高橋幼保一元担当課長","answer":"直接の指導については園に行くんですけれども、問い合わせ等については、こちらにも電話がかかってくる場合もありますので、連絡が参りましたときには、その園に行って指導するなり、設置基準に合っているかどうかということを指導しているところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"川西委員","kind":"意見","question":"先ほど、つくし幼稚園の定員がこのような現況で廃園予定の話があるやにご答弁があったようですが、例えば具体的に名前を出して悪いんですけれども、５番目の大崎幼稚園なんかは３分の１ですよね。おそらく今後二、三年後に再開発されて、あの辺に住居ができるから、それを期待されてじっと我慢していらっしゃるのかもしれないけれども、ご相談というのはありますか、具体的に。","respondent":"高橋幼保一元担当課長","answer":"特には、お聞きしていません。","voiceIndex":37,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"「ぷりすくーる西五反田」は新しい施設、保育園と幼稚園と両方加味備えているというところで、利用率のところで、特に保育部門のところですけれども、保育園と比べてどうなのかというところが１点と、延長夜間保育と預かり保育、上と下と違いますけれども、内容的に、時間的なものがどうなのかなと思うのが。","respondent":"高橋幼保一元担当課長","answer":"９８％というところでは、こちらの見込んだとおり、まあまあ執行できているという状況です。もう１点、補助金の関係ですけれども、補助金につきましては、保育部門の延長夜間の部分だけが補助金対象で、あとについては、ないです。","voiceIndex":43,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"予算の中に保護者の補助金というのが、幼児教育施設、園児保護者等補助金という項目があったんですけれども、この辺が、やっぱり、新しい施設ということで、私立の幼稚園なんかの補助金との違いですか、多分違いがあると思うんですけれども、ちょっと、普通の、先ほどのところの説明があった、幼稚園に対する補助金と、このぷりすくーるに対する保護者の補助金というのがあるんですけれども。","respondent":"高橋幼保一元担当課長、辻田児童課長","answer":"私のほうから２点お答えしたいと思います。それで、予算的には１,３００万円ぐらいの予算で、６００万円ぐらい、この中のやりくりで、子育て支援部門のほうに、幼児教育部門のほうから入ってきている、これは人の配置の部分で、どちらに置くかということは。","voiceIndex":45,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、さっきの保護者等補助金のことなんですけれども、私立の幼稚園のところは、結構手厚く補助が出ているというのを以前伺って、その中に入園料の補助と、あと、園児保護者等補助金と、あと、就園奨励費補助金というのがあるんですよね、これを全部合わせた分ぐらいは、このぷりすくーる西五反田の保護者のところに手当てができていると受けとめてよろしいのでしょうか。","respondent":"高橋幼保一元担当課長","answer":"保護者の月額の保育料につきましても、ぷりすくーるの設定については今、私立幼稚園の平均的な保育料といたしまして、２万３,０００円ぐらいを設定しているんですけれども、その中で、今言いました、園児の補助金等につきましては。","voiceIndex":48,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"保育料なんかも違うし、入園料も違うというので、いろいろとあると思うんですけど、すいません、わかったらでいいのですが、園児保護者等補助金の１人当たりというか、平均は出ないのでしょうか。もしわかったら、どのくらいの、ここのところで手当がされているのかなというのを知りたいので、１人当たり、平均でも何でもいいのですが、わかったら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問","question":"高齢化の推移なんですが、６５歳以上が、平成１２年度、保険制度が始まったときですが、１７.１％で、平成１７年、ことしが１８.６％という、当然、高齢化の推移をしているわけなんですけれども、これは介護保険制度が始まったときからの、高齢化の見込みというんですか、それと現状、実数、どの辺、どういうふうにとらえているのか、教えてください。","respondent":"早津高齢福祉課長","answer":"高齢化の見込みですが、制度発足当初の見込額、今、手元になくて大変恐縮です。全体的に言えますことは、委員ご指摘のように、増えてはいるんですが、品川区の特徴としては、この増え方が非常に鈍化しているというところが特徴です。","voiceIndex":57,"id":"exchange-019"},{"speaker":"本多委員","kind":"質問","question":"区全体の施策のそういうものが絡んでいると思います。それで、ケアプランの策定も、これは必ずしも比例しているわけではないと思うんですけれども、むしろいろいろな施設とか、グループホームの関係もあってなんだと思うんですが、ケアプランの策定のほうが、かえって減っているんじゃないかなと思うんですが、その辺はどのように考えているんでしょうか。","respondent":"早津高齢福祉課長","answer":"先ほどの説明の中でもありましたけれども、高齢者の中でも後期高齢者が増えておりますので、やはり介護を必要とする方の人数というのは増加傾向にあるという、これはとめることはなかなか難しいという全体的な流れになります。","voiceIndex":59,"id":"exchange-020"},{"speaker":"本多委員","kind":"確認","question":"平成１６年度だけが資料が出ていて、普通徴収については８７.２２％ということなんですけれども、今後の保険料を、今後、考えていったときに、この普通徴収の１００％に当然向けて努力されているのはわかりますが、１００％にいかないこの部分をですね、今後の介護保険料を考えたときに、この部分のウエートといいますか、どういうふうな取り扱いといいますか、考えていくのか教えてください。","respondent":"早津高齢福祉課長","answer":"この点につきましては、少しでも徴収率を上げるべく、昨年の夏ぐらいに徴収員制度を導入いたしました。今年度、高齢福祉課に介護保険料係ということで、組織が変わった後、滞納している方への電話督促等も開始したところです。","voiceIndex":61,"id":"exchange-021"},{"speaker":"川西委員","kind":"質問","question":"１９ページの苦情の件なんですが、この数値を見ますと、最初に比べて減ってきているということで、やはりこれは事業者、あるいは訪問ヘルパーの方々の資質の向上というのが反映しているのかどうかということなんですが、こういう苦情があった場合には、年に１回ぐらいヘルパー派遣の事業者に対して、こういうような苦情がありましたというようなお知らせというか、あれはしているのかどうか伺います。","respondent":"早津高齢福祉課長、上山介護保険担当課長","answer":"実際上、ショートステイは私どもの印象としましては、満杯状態で使用されているというふうになってあります。申し込みの待ち状況ですけれども、昨年から申し込みの方法を変更いたしまして、２カ月前の１日から申し込みができます。こういった苦情に対する対応ですけれども、在宅介護支援センターとか、各民間事業者も含めまして、サービス事業者等を集める説明会とか、打ち合わせを年数回開催しております。","voiceIndex":63,"id":"exchange-022"},{"speaker":"川西委員","kind":"質問・要望","question":"ありがとうございました。やっぱり公設民営の施設ですから、もう少し検討していただきたい。在宅で、やっぱり高齢、病気を持って暮らしている人たちが、やむなくそういうショートに行くわけですから、もう少し環境整備をお願いしたいと思います。ですから、一般質問みたいになっちゃうけれど、これから品川区は、ショートに対しても少し心を配って重視していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、ほかの方がどこを利用されているのかということと、老健を利用されている方がどういった方たちなのかというとらえ方の認識をお伺いしたいのは、私たちは特養に入れない方たちが待機状態で老健施設を３カ月ごとに転々とされて、ご苦労していると受けとめているんですけれども、その辺についてのお考えを１点と、あとそこの下の欄に、特定施設。","respondent":"早津高齢福祉課長","answer":"在宅では難しいから、特養をというような方も中にはいらっしゃいますけれども、委員ご指摘のように、特養待機の方ばかりというような考え方は、私どもはとってございません。","voiceIndex":69,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"は移る、ストレッチャーを使ったりとかいろいろ、そういった面で移送のところでも苦労をされているというのがかなりあるので、その辺をどのくらい把握をしていらっしゃるのかなというところを１点お伺いしたいと思います。１６ページの普通徴収のところの徴収率が８７.２２％となっていますけれども、１３％弱の方が支払っていないというところで、この未納者の理由を教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"といいますのは、老健の入所を希望された場合は、あまり深くそれを立ち入って、特養の入所と違ってどういう状況かとかというようなことを、そう聞くわけではありませんで、老健に入りたいということで、在宅が無理だということであれば、例えば近くがいいのか。","voiceIndex":71,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"最後の未納の理由のところなんですけれども、はっきり中身的にはよくわからなかったんですが、中に、本当に払えない方、払わない方って、力があって払えないというところは、徴収の仕方の工夫もあると思うんですけれども、払えない方に対しての把握がどのくらい実態を把握していらっしゃるのかなというのが１点と、あと、このように未納の方が介護が必要になった場合にどのようになるのか教えてください。","respondent":"早津高齢福祉課長","answer":"本当に払えないのかどうかというのは、慎重に考えないと、なかなか難しいところかと思いますので、先ほど申し上げたように、督促をはじめとして、実態を把握するという中で、全員が支払うというのが法の精神ですので、納付のほうにつなげていきたいというふうに考えてあります。","voiceIndex":73,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"意見","question":"最後なんですけれども、二期の介護保険制度の推進委員会なんですけれども、そのスケジュールを見ると、７月に第７回が開かれるんですけれども、この中に、第三期の課題といって、在宅介護支援システムと生活圏域の設定についてというのと、もう一点、認知症ケアについてということが上っているので、ぜひこの中身も報告をお願いしたいんですけれど。","respondent":"早津高齢福祉課長","answer":"制度推進委員会の予定は、今、委員がおっしゃられたとおりですけれども、制度推進委員会の報告を厚生委員会でするようにということでございましょうか。","voiceIndex":75,"id":"exchange-027"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"旧都南病院跡地に関する質問に対してのご答弁の中に、ショートステイ等について、交付金対象から除外となっていますというご答弁があったので、ちょっとこの中身を一つお伺いしたいのと、あと、新制度を活用して、区民ニーズにより的確に対応した施設にすべく、ご提案の趣旨を踏まえて検討を行ってまいりますというご答弁だったので、この辺、区民ニーズをどうとらえていらっしゃるのかなという点。","respondent":"早津高齢福祉課長","answer":"都南病院の取得を予定している土地は１,５００m2ぐらいですけれども、三方道路というようなものとか、規制があるために、そう高いものは建てることは難しいというような状況でございまして、３階建てぐらいが大体限度ではないかというふうに考えているところです。","voiceIndex":82,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"建物について、高さ制限、高さの問題を今お答えいただいたんですが、特養とか老健施設ができる施設なのかどうかというところを、ちょっと具体的に答えていただきたいのは、先ほど区民ニーズのところでグループホームとか特定施設が多いというご答弁があったんですけれども、ここのところ、都内を見ても、ケアハウスとか、有料の老人ホームって、結構民間で建てている、建設が進んでいて。","respondent":"早津高齢福祉課長","answer":"しかしながら、再三この件につきましてご答弁申し上げておりますように、区の基本姿勢としては、いわゆる特養、老健といった施設系サービスではなく、在宅系のサービスの施設として構想していく予定で考えているところです。","voiceIndex":84,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"厚労省のほうに問い合わせをしたら、平成１７年度はショートステイとかを除外しているということはないし、平成１８年度についてはまだ決まっていないというふうなことで、そういう施設を除外しているということはないはずだというふうなことで聞いたんですけど、そこら辺のところが、東京都の計画というふうなこととか、そういうふうなもののかかわりというふうなものがあるのかどうか、そこら辺の仕組みと。","respondent":"早津高齢福祉課長","answer":"国のほうで認めているショートというのは、特養に併設するショート、つまり品川区の場合でも特養８０人のところに４つないし６つぐらいのショートステイがありますが、そういうものは特養の附属施設としてのショートは認めますということですが、単独型。","voiceIndex":90,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"わかりました。そういう点では、なぜ特養や老健が区として方針を持たないのか。そこのところを改めてもう一回教えてください。","respondent":"早津高齢福祉課長","answer":"そうこうする中で、また、この介護保険制度の今回の改正の中に見られますように、在宅生活をできるだけ変えないようにというような、地域に密着したようなサービスをしていくのが大事なことであり。","voiceIndex":92,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、個室ニーズということですが、特別養護老人ホームも、今、個室というふうなことの方向になっていますし、区民の大変な状況というのは特別養護老人ホームを申し込んでも本当に入れなくて、しかも老健施設も入れなくて、区内に１カ所しかないというところで、ほかの区に実際お世話になっているわけですから、そういうふうな点では、老健施設、それから特養ホームも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-032"}]},{"id":"topic-03","title":"ままいてください。すいません。本当はお２人だけと言ったんだけど、すぐ終わりますから。 それでは、本当はお２人だけ残ってやっていただこうと思いましたが","agenda":"ままいてください。すいません。本当はお２人だけと言ったんだけど、すぐ終わりますから。 それでは、本当はお２人だけ残ってやっていただこうと思いましたが","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"意見じゃないんだけど、まず日程をセットさせていただいて、今、正副で何点かあったんで、先様の都合もあるでしょうから、それである程度決まってこないと、我々がここで何を調べてくれ、何をしたいと言っても、全然とんでもないところにいって、まただめですよという話になっちゃうといけないので、そこを先に固めていただいて、先様のほうと、ある程度正副でつかまえたところで合致するようであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":33426,"voices":103}},{"id":"h17-20050705-8","meetingId":"h17-cm07","date":"2005年7月5日","dateIso":"2005-07-05","committee":"建設委員会","time":"午前１０時０４分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「しながわ水族館（仮称）アザラシ館増築について」","agenda":"の「しながわ水族館（仮称）アザラシ館増築について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"きのう視察に行ってきたところでの３ページのところからだと思うんですけれども、アザラシ館ができる水辺のところをすべて改築して、あとの周りというか、緑があったところとか、そういう部分は残して、ある程度はもちろん改築するんですけれども、他は残していくという計画なのでしょうか。","respondent":"藤田道路公園課長","answer":"３ページで申し上げますと、網かけになっております部分が新設工事にかかわる部分ですので、基本的には周囲についてはそのままという状況になります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"そうすると、レストランのところは残して、ここの池の中にボンと総体的にドンと円柱というか、その施設ができるということでいいんですか。水槽のイルカショーをするようなところは、結構狭かったと思うんです。増設するに当たって、すごく混んでいるので増設するのか、たまたま工事をするからそこも一緒にやりましょうということなのか、観覧増設する根拠は何ですか。","respondent":"藤田道路公園課長","answer":"こちらのプールですけれども、大変人気が高うございまして、その中で実際には１８０席と、今、現状がいすの席があるわけですけれども、その周りの立ち見というような形でごらんになっている方もたくさんいます。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"そのイルカショーを、済みません、１回も見ていなくて言っているので申しわけないんですけれども、もっとそこに新設するところで広くするとか、そういう計画、観覧席だけではなくて、そっちのスペースということは検討にはならない。それで十分だということでしょうか。","respondent":"藤田道路公園課長","answer":"なかなか何をもって大丈夫というか、これは非常に難しいところです。ただ、現在のプールの大きさ、それに合わせて正面がちょうどショーを見せるため、あるいはアシカのショーもそこで行っております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"わかりました。可能な限りということだから、やっぱりここを広くするということは検討をして、プールの方を広くしてもう少し、人気があるということであれば、アザラシ館もそうなんですけれども、イルカの方に力を入れようとか、そういうスペース的にプールを広くしようという検討はされなかったんですか。","respondent":"藤田道路公園課長","answer":"今回、イルカのプールにつきましては、既存のプールを活用するということを前提に考えてありますので、アザラシ館を新設することで魅力をアップさせていこうということがメーンの工事です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"その団体の休憩所とか、いろいろな方たちの要望の声とか、利用者の声とかがあると思うんですけれども、そういうものをどう反映されているのかということと、その詳細を詰めていて、詰められる、計画が出されるのはいつごろになるのでしょうか。","respondent":"藤田道路公園課長","answer":"今後、詳細について、今、設計をしています。工事につきましては、一応、年度内に行うといったような予定になってありますので、よろしくお願いいたします。","voiceIndex":15,"id":"exchange-005"},{"speaker":"井上委員","kind":"意見","question":"そのレストハウスの利用者アンケートというのは、もう実施をされたのか、済んで集計がされているのかとか、二、三、どういったご意見があったのかということをご紹介いただければありがたいんですけれども。","respondent":"藤田道路公園課長","answer":"アンケートの方は既に実施をして集計の結果が出てあります。大きな意見としては、やはりなかなか洋食メニューが大分多いので、来られる方が、おじいちゃんがお孫さんを連れてくるとか、そういったケースも結構あります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"建物的に改築するわけですから、何かそういったところの要望とかはあったんでしょうか。","respondent":"藤田道路公園課長","answer":"バリアフリーの関係で、やはり段差の解消とか、部分的にはできているんですけれども、もう少し配慮する必要があるのかなというふうに考えてあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"公園内の今回は池の面に建つんですけれども、公園の中に建物等で利用を図る、無限にあるわけではないと思うし、そこら辺はどういう規制等、許可とか、申請とか、同じところなので出すことになるのかもしれないけれども、それはどういうふうになっているのか、ちょっと聞かせてください。","respondent":"藤田道路公園課長","answer":"通常の公園については２％というふうな規制になってありますけれども、こういった水族館等を設ける場合、それについては供用施設ということで、１０％まではいいですよというような形になってあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと所管が違うのかもしれないですけれども、こういう形で施設が増えていきますと、当然、施設が増えれば、保守費用ですとか何とかといろいろ増えていくのだろうと思うんですけれども、サンシャインとの入場料に対する割合とかというのは、６対４とか何とかと割合がありましたよね。その辺の割合は変わっていくんですか。","respondent":"藤田道路公園課長","answer":"入館者数がこれからどう推移していくか、そういったこともあります。そういった中で適宜適切な時期に見直しを図っていくものかなというふうに考えてあります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"井上委員","kind":"確認","question":"今のちょっと確認ですが、配分のところはそうなんですけれども、利用料については、変更があったり、今後そういうこともあるんですか。","respondent":"藤田道路公園課長","answer":"そういった中で、どういった形がいいのかという検証も今後またされていくと思いますけれども、今の段階では、こういった景気の動向もありますので、最終的に料金を変更するかとか、そこまで最終的な結論は出ておりませんけれども。","voiceIndex":27,"id":"exchange-010"},{"speaker":"井上委員","kind":"意見","question":"ということは、先ほどおっしゃったように、施設が増えていくことによってどう変化していくということではなくて、全体を見て料金を設定することを検討していくということでいいですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"こういうのは、区の方が主体的に、今度はこういうものをというようなお考えになって全部つくっていく、でき上がったものを従来通りサンシャインの方に委託するという形なのか、あるいは委託を受けてサンシャインの方で、例えばある時期が来た段階で区の方に、今度はこういうものをつくってもらえないかとかというような向こう側からの要請があって、それでこれを検討して、じゃあ。","respondent":"藤田道路公園課長","answer":"そういった観点からも、区の方で施設としてのあり方を検討するのがベースだというふうに考えてあります。ただ、当然、サンシャインの方も水族館運営ということでさまざまなノウハウを持っております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"そうすると、何かまたお客さんを呼ぶために何かをというときに、例えばまた何かどこかに増設して新たなものをというふうになると想定すると、もう場所が、今回のアザラシ館は池の中にという、手いっぱい、めいっぱいというんですか、だから、その辺も何かよく、ただ単に何か増設をして新たなものを、そういうふうにしないと人が呼べないのかもしれませんが、その辺のところを。","respondent":"藤田道路公園課長","answer":"公園の面積も限られてあります。そういった中で区の経済的なこともあります。もう１つは、区民のニーズがどこまであるか、その辺もあわせる判断の中でやはりそういった施策は進めていくべきというふうに考えてあります。","voiceIndex":32,"id":"exchange-013"}]},{"id":"topic-02","title":"の「運河ルネッサンス推進地区の指定について」","agenda":"の「運河ルネッサンス推進地区の指定について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"全体的にわからないんですけれども、東京都がここを推進地区として指定して協議会みたいなものが発足してというところでは、どういうふうな人たちがそこに協議会で集まって、どういう流れでこれを進めていこう、どういう機関、こういう水上レストランのイメージとか、こういうイメージ図ではあるけれども、これはもうどのぐらいの計画がもう進んでいるのかとか、そういう、ただ立ち上がっただけなのか。","respondent":"上野都市開発課長","answer":"こういった設置に当たりまして、今後、都の方で水域占用許可などの緩和をやっていくということになってございまして、具体的な計画といたしましては、寺田倉庫のところでの水上レストラン設置計画が、今年の９月を目途にオープンの予定での計画が進んでいるところです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"ごく入り口のところになるかもしれないんですけれども、ここのところをこういうふうにしたいという協議会が立ち上がって、その人たちがグループでこういうことをしたいんだということを計画して、その計画書で登録したら都がそれを認めたというところでは、そこのそういう人たちがかかわって進めていかれるのはいいんですけれども、そういうことに意見というか、声を出すとか、意見を拾うとか。","respondent":"上野都市開発課長","answer":"ここは地元の方々が主体的になって取り組むということを前提としているものです。そういう仕組みでございまして、その中でも特にモデル地区として先行的にこの天王洲地区、あるいはこの港区側になります芝浦港南地区を先行的に設置したものです。","voiceIndex":41,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"結果、いつもこういうふうなスタートをしていったときに、そこら辺の、どんどん計画があって動いている人たちは動いているんだけれども、そのことを知らなかった人たちというか、そこではその人たちの、そういうことだったら意見が言えたのにとか、こういうことを聞いてほしかったとか、いろいろな問題が出てきているわけで、そのときにこういう計画がありますというようなことを広報するのはどこなのか。","respondent":"上野都市開発課長","answer":"この仕組み全体につきましては、今、お手元の資料にもありますけれども、東京都の方でもこういうホームページなどで表示して広報等に努めているところでございまして。","voiceIndex":43,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"地元が主体でやっていくと言っても、最終的にはいろいろなかかわりとか、地元が知らせるのではなくて、ここは品川区の新たな運河を利用した水辺の構想というのは品川区にもあるわけですから、そこは品川区がこういう形でこういう動きがありますよとか、そういう広報は必要だと思うんですけれども、地元にお任せというのではなくて、品川区が取り組んでもいいかと思うんですけれども。","respondent":"上野都市開発課長","answer":"区としての広報につきましては、今後、この指定につきましてどういう形で広報するかは検討させていただきたいと思います。","voiceIndex":45,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"本当にいろいろなところでいろいろな計画があって、いいものもたくさんあると思うんですけれども、そのことがほとんど決まった状況で区民が知るということで、いろいろな問題とか、計画形成段階でもっともっと区民の方が知っていれば、流れもわかったり、理解をしていただけることがあると思うので、前向きにこういったいいまちづくりになる計画に対しては本当に広報していってほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"今、地元の方たちが主体でということですが、そもそもこれは観光が目的ということなんでしょうか。","respondent":"上野都市開発課長","answer":"もともとこの運河ルネッサンス構想なるものは、運河を新たに観光の視点から見直してまちづくりと一体となって運河の活用を目指すというものでございまして、こういう水辺の資源などを観光資源として活用していくということを目的としているものです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"地元の人への利益というのは、どういうものがあるのでしょうか。","respondent":"上野都市開発課長、岩田まちづくり事業部次長","answer":"こういった観光の視点からの活用を図って水辺のにぎわいを創出していくことが地元の利益になるというふうに考えてあります。この水というのは、やっぱり区の中期計画にもはっきりうたっておるように、水辺に接する品川区としては非常に貴重な資源ですので。","voiceIndex":50,"id":"exchange-020"},{"speaker":"大西副委員長","kind":"質問","question":"私は、先ほど井上委員からありました広く住民の方々からの意見を取り入れていくということについては、今、天王洲のポンプ場跡地といいますか、あの辺の近隣に公園をどのようにつくっていくかということで、区の方で近隣５００メートル程度でしたでしょうか、ペーパーを入れて意見を聴取したいということで、もう何回も住民の意見を聞いて、そういう点で住民の方々から駐車場問題。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問・要望","question":"要望になってしまうかもしれませんけれども、品川に来て海に面しているはずだと言って、海の水のすぐ直接に、目の前に行くことが極めて困難な施設づくりになってしまっていますね。埠頭なんかへ行ってもはるか向こうに荷物の陰にまたバリケードをつくられて入れない。そういう形になっている。行ってみたらどこもないんですね。ぜひそういうところを少し大事にしていかなければいけないところだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認といいましょうか、教えていただきたいのは、要するに、これはここに書いてあるのをそのまま読むと、東京都が２つの地区を推進地区として指定したという言い方になるんですね。東京都は指定をしたけれども、取り組むのは指定された側が主体にやってくださいということですか。これはだれがつくるのか。あるいは、観光桟橋、これは東京都でつくるんですか。その辺の仕組みを教えていただけますか。","respondent":"上野都市開発課長","answer":"この財源につきましては、まずこの取り組みの中身につきましては、地元が、民間企業も含めて地元の方で費用負担をするというのが基本でございまして、東京都の方では、お手元の資料にありますように、その水上レストランの設置ですとか、桟橋の設置をするに当たって。","voiceIndex":55,"id":"exchange-023"},{"speaker":"堺委員","kind":"質問","question":"去年、地元と東京都と協議してきた、それはさっき説明があったのかどうか、説明にあったとしたらごめんなさい、聞き漏らしてしまったのだと思います。その辺がちょっとよくわからなかったのでもう１回お聞きしたい。そうすると、ここで区はどういうふうにかかわってくるんですか。決まったら区はこういう形で今度やりますよというようなお知らせだけやる。その辺はどういう仕組みになるんですか。","respondent":"上野都市開発課長","answer":"区としましても、地元の利益にかなうものかどうかという視点からの助言などをこれまでしてきたです。","voiceIndex":57,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"今おっしゃっておられたように、この観光とか景観とか回遊性などを重視した魅力ある都市空間としての再生を目指すという表現の中には、やっぱりさっきおっしゃった地元の利益、これも僕は重要なポイントというんですか、何かやるにしても、地元にプラスになるものが何もないとなってはこれは意味がないので、そういう点では、地元の利益もこういうことをやることによって当然プラス要素がそれなりにある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"先ほど堺委員がおっしゃったような水上バスの発着場などの水上交通の拠点という、こういうところになると、地元主体のという水上バスが今ある中で、それの運行をするとかという、ただ遊覧船みたいな水上バスということではなくて、常にある水上バスがあるわけですから、そういったところの発着場というふうに考えたりすると、地元がやるということではないと思うんですけれども。","respondent":"上野都市開発課長","answer":"その中に定期船の就航も含めた形での船着場としての整備を地元の方で考えてございまして、具体的にその実現に当たっては、区としても調整などについて協議に応じていく考えです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"井上委員","kind":"意見","question":"そういうふうな具体的なものになってくると、定期船の発着場とかというのが、本来、地元につくる。そういうものであれば公のものかと私は思っていたんですけれども、そこは観光としてそういうふうに今走っていますよね、水上バスが。あれとは違うものということではないんですよね。","respondent":"上野都市開発課長","answer":"地元が主体的に整備したものをそういう公的な利用をするということも可能とすると、そういうことを目指しているものです。ですから、地元があくまでも整備する、それに公的な機能も併せ持つような形での整備を考えていく、そういうものです。","voiceIndex":63,"id":"exchange-027"}]},{"id":"topic-03","title":"の「区営住宅（空き家）入居予定者登録募集について」","agenda":"の「区営住宅（空き家）入居予定者登録募集について」","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"今、１０戸の登録募集とのことですけれども、この近年の状況、登録された方の出入りといいますか、入居状況といいますか、それを教えてください。","respondent":"浜脇住宅課長","answer":"これまでの中では、１年間で団地ごとに１０戸登録したけれども、１戸か２戸が空き家になる可能性があるということで準備をしてやっているです。","voiceIndex":69,"id":"exchange-028"},{"speaker":"林（和）委員","kind":"意見","question":"それを先に言ってくれなければわからない。だから、品川区内にどれだけあって、１０戸の募集の登録をするわけだから、今のお話では大体その１０戸が入っているわけでしょう。全部の団地を合わせたらやっぱり１０戸程度のあきがあるということでしょう。","respondent":"浜脇住宅課長","answer":"ですから、各団地１０戸ぐらい登録してもらいますけれども、現実的には、せいぜい１つか２つというのがここのところの傾向です。","voiceIndex":75,"id":"exchange-029"},{"speaker":"林（和）委員","kind":"意見","question":"品川区全部の区営住宅は、団地は何個かあるわけでしょう。その何個かの１団地で１戸、今の話ではあくというようなことを言っているんだけれども、そうすると、全部ひっくるめると、１０団地あれば１０戸があくということになるでしょう。なんかよくわからないんだけれども。","respondent":"浜脇住宅課長","answer":"これに対してご自分が希望したいところにエントリーするわけでございまして、そのときに大体、南大井１丁目でしたら１０戸ぐらいがこれまでのところ登録していただいていますけれども、結果として１つか２つぐらいしか空き家になってございませんということを申し上げたわけです。","voiceIndex":77,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、１０戸程度募集しますよと、登録してもらいますよと。登録してもらいますけれども、１２団地のうちの団地ごとに登録をするんですか。だから、全体に年間に品川区内の団地の中で１０戸程度大体出入りがありますから、その１０戸程度の部分を登録していただくんですよ、スムーズに入っていただくんですよ、そういう募集の仕方も含めての説明をしていただければわかるんじゃないですか。","respondent":"浜脇住宅課長","answer":"申しわけございません。今回、１２団地ありますが、１２団地ごとに募集しています。１０戸登録をしてもらって、希望する団地があいた場合に順位の最高からご紹介をして入っていただくという仕組みです。","voiceIndex":83,"id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"ということは、１団地に１０人ずつなんですか。となると、もうほとんど入れない人が１０人、だから、そういうことなのかどうかということが知りたいんだと思うんです、皆さんは。","respondent":"浜脇住宅課長","answer":"こればっかりは、いろいろな案があったかなと思いますけれども、今までの中では各団地１戸か２戸が出ますし、もしかすると出ない場合もあります。しかし、私どもとすれば、各団地ごとに１０戸登録をさせていただいているです。","voiceIndex":85,"id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"だから、それは正しいのか、そういう仕組み自体が正しいのかどうかは我々が決めなければいけないかもしれないから、それで伺っているわけです。だけど、そうじゃなくて、その仕組みがそうだとすれば、我々がその仕組みを考えて、場合によっては提起をして、区営住宅ですから。今まで都でやっていた時代とは違うんだからということでやれないかというアイデアを浮かばせるために、今、伺っているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-033"},{"speaker":"林（和）委員","kind":"質問","question":"今後、それだと今も土井委員が言っていましたけれども、１２０人が登録しても１０人程度しか入れない、０の場合もあるわけでしょう。やはりそのせいか、そんなこと、場所なんか言っていられないから何とか入れてくれという人が多いと思うんだよね。だから、その考え方というか、将来の考え方というのを教えてください。","respondent":"浜脇住宅課長","answer":"それで、収入や家族構成などがありますので、そういう方に応じた団地です。これまでは団地でこの条件なら入るという方をピックアップといいますか、確実な方を登録していただいて、そのままスムーズに入っていただくというのが今のやり方です。","voiceIndex":88,"id":"exchange-034"},{"speaker":"土井委員","kind":"意見","question":"団地が違っても、同じタイプ、もしくは類似のタイプがあるわけで、用途別ぐらいは少なくともできるはずですよ。少人数家族向けだとか、単身に近い人たち、もしくは２人暮らしの人たちだとか、そうすると、今、仮に１２団地あっても、３つぐらいにブロック分けをして、このグループのところで募集したら、もっと困窮している人の住民が入り得る、抽せんに当たっても入り得る可能性がないわけです。","respondent":"福田まちづくり事業部長","answer":"それから課長が言いました間取りの問題もあると思います。これは事実だろうと思います。しかし、もう１つ、先生方がおっしゃるように、困窮度、どこでもいいからという方のお考えにどうやって沿えるかということについては十分検討させていただきたいというふうに思います。","voiceIndex":92,"id":"exchange-035"}]},{"id":"topic-04","title":"の「平成１７年度マンション管理セミナー（第１回）の開催について」","agenda":"の「平成１７年度マンション管理セミナー（第１回）の開催について」","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"かなり盛況というふうに伺っておるんですけれども、その意味では、逆にもっと増やしてくれとかというような要望があるのかないのか、ちょっとこの機会に伺っておきたいと思うんです。場合によっては、今、第１回ということですから、何回かやって、次の機会も含めて需要が足りているのかなというか、ちょっとその辺を。","respondent":"浜脇住宅課長","answer":"第１回が８月を予定してございまして、第２回も実は予定しています。これまでも最初の第１回目を８月にやりまして、来年の２月ごろに第２回目を予定しています。","voiceIndex":102,"id":"exchange-036"},{"speaker":"土井委員","kind":"質問・要望","question":"要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"周知の方法なんですけれども、これまでここのセミナーに来た方には個別にお伝えしているということを聞いていますけれども、今、区内でかなり巨大なマンションというか、４００戸だ、５００戸だというマンションがポツポツ生まれてきていますけれども、新しいマンションに対する働きかけというものは何かやっていらっしゃるのかどうか、ちょっとそこだけ教えていただけますか。","respondent":"浜脇住宅課長","answer":"ちょっと今、新築は考えてございませんで、どちらかというと、対象はもうちょっと老朽化したような感じで、もう少し中規模な管理ということで、これまでの参加者に対して聞いても、そういう方々が参加してくれているのだなと思いますので、今、委員がおっしゃったように。","voiceIndex":105,"id":"exchange-038"},{"speaker":"菊地委員","kind":"意見","question":"老朽化したことのみが問題というよりも、マンションの場合、私もマンション住まいですけれども、どういうふうに管理組合が運用していくかというのは非常に、修繕のことだけではなくて、大きな問題がいくつもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-039"},{"speaker":"大西副委員長","kind":"質問","question":"だから、そこの子どもたちがお祭りに参加しづらい状態にもなってきているということがあるけれども、それに対しての働きかけを行政としては全くやっていないという状態のものがあって、なかなか町会としてもどうやって働きかけていったらいいかわからないとか、そういう部分があるんですけれども、その地域と新しい、要するに、町会レベルのものと、そういう大きな集合住宅の管理組合というんですか。","respondent":"浜脇住宅課長","answer":"それから２点目の大きなマンションといいますか、新築マンションに関しては、開発指導要綱の中で町会への入会ということで、窓口ですけれども、町会に入って地域の交流をするようにということで私どもは必ず指導はしています。","voiceIndex":108,"id":"exchange-040"},{"speaker":"大西副委員長","kind":"質問","question":"１段目のところは、要するに、今、私なりに解釈しますと、管理組合がないといろいろな面で不便ですよとか、また管理組合はこういう管理会社というのは適正ではないので、こういう方向でいろいろな物事を管理会社とかは考えていかなければいけないんですよ、諸問題がこういうふうに発生していますよということの意味でのこの上段の部分というふうに解釈してよろしいわけでしょうか。","respondent":"浜脇住宅課長","answer":"私のほうは、そういう問題が多いので、一般論としてそういう話をしていきたいというふうに思っています。","voiceIndex":110,"id":"exchange-041"}]},{"id":"topic-05","title":"の「品川区立区民住宅における住替えの募集について」","agenda":"の「品川区立区民住宅における住替えの募集について」","exchanges":[{"speaker":"土井委員","kind":"質問","question":"そうすると、それも同じようなサイズだったらどこでもいいよなのか、それぞれの棟の中で行ったり来たりの話なのかというのでは、どういう募集のされ方をしているのでしょうか。","respondent":"浜脇住宅課長","answer":"これは住んでいる方々の人数の変動があった場合に受け付けるということになってございまして、例えば２人から３人、あるいは２人から４人で手狭になったところから少し広いところへと、あるいは年齢構成も若干変わって、そういうようなことで、当初は。","voiceIndex":117,"id":"exchange-042"},{"speaker":"土井委員","kind":"質問","question":"大きいところに入れる、広いところに入りたい人も、少なくなってきたので狭いところに移りたい人、１、２、３でこうやればいいのでね。だから、棟内移動、同じ棟の中で動く形のものを想定しての形の場合と、近隣、そんなに遠くないところもありますから、これはこっちからこっちもいいんだよという形の図式になっているのかも含めて、ちょっと教えてください。","respondent":"浜脇住宅課長","answer":"同じ棟内でも構いません。構いませんし、３棟の中でも構いませんので、そういう規約はあると思われます。想定してつくってあります。","voiceIndex":119,"id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"環境住宅でいうと、そういった予算もついて募集もあったりするんだけれども、それが結局は使われていないとかというようなこともあると思うので、その計画に対してどういう取り組みをしていて、結果どうなのかというようなところの状況が変化があったり、そういったところの調査をしていきたいと思っているので、報告をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの運河ルネッサンス推進地区の指定についてというところの報告なんですけれども、昨年から区と都と地元が協議していたというところでは、もう少しどういう経過でその方たちが選ばれてとか、この計画に対しての詳細な報告をいただきたいんですが、これだけだとわからないので、次回の委員会で、どういうものでどういうふうに進められて今現在ここまで来て。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺のやっぱり地元というところが、地元住民というには住民も少ししか住んでいらっしゃらないということも聞いて、その辺はきっちりと私たちがそういう話を区民の方にもお知らせするにも、その協議会というものの存在がわからないということであれば、なかなかこういう計画が進んでいるので、計画、まちづくりがあるということもお話ができないわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-046"},{"speaker":"菊地委員","kind":"質問","question":"私も井上委員と同じように、先ほど堺委員がレストランの話で経営主体はどこなのという話にもなった折にはっきりした答えも出ていなかったような気がするんです。基本的に地元の皆さんがこれに対して進めていくんですよという以上は、もっと細かな協議会なり何なりの構成なり、メンバーなり、そういったものが出てきてもおかしくはないかなというふうに思いますので、資料としていいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-047"},{"speaker":"林（和）委員","kind":"質問・要望","question":"資料はこれ以上出ないというわけですから、出してもらうと言っても出ようがないわけですから、今後、それぞれの委員さんがそれぞれの課に行って聞いていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-048"},{"speaker":"土井委員","kind":"質問","question":"だから、今までのお話を伺うと、区にはそれが実態としてはないというのが実態なのだと思います。そしてそれが逆に、今後、区がどうサジェスチョンをして、どう誘導していけるのかいけないのかという論議の筋をつくりたいということなのだろうから、それしか方法はないんじゃないかな。だから今、区に言っても、相談途上なんだから何もないよと言われる、これはしょうがない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-049"},{"speaker":"堺委員","kind":"意見","question":"私も土井委員が言われたように、特に委員会としての資料要求は必要ないと思います。は個々に機会があれば聞いていただいて、都市開発課長の方でもこれ以上のご説明する資料としては特にないということであれば、必要ないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"だから、何がというのが今、私にないので、こういうことを、前回は放置自転車対策のところの視察を見て、品川で何とかできないかということで私はこれを提案していましたけれども、そういう意味では、なかなか調査項目としてその地域を見てどうなのかというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-051"},{"speaker":"大西副委員長","kind":"意見","question":"私は、今回の選挙は大変忙しくない状態でございましたので、視察のコースをいろいろ考えさせていただきまして、今回、アザラシ館という問題が出ましたけれども、これに関しては先ほど堺委員から話が出ましたように、１０周年、２０周年とかということも考えていくと、そういう形でのこういう施設でうまくいっているところを観察するというのも１つの手かなという点に関しては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-052"},{"speaker":"菊地委員","kind":"意見","question":"私は、きのうの条例のところで武蔵小山のところの話で反対をしましたけれども、私はやっぱり今、震災対策ですとか、そういった問題がまた改めてクローズアップされている中で、どういうまちづくりを進めるのかというところで、市民が参加をしていろいろな絵をかいてやっているような場所はないのかなと、ちょっとこれも私もどこがいいのかというのはよくわかりませんけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-053"},{"speaker":"大西副委員長","kind":"意見","question":"前にこれを投げかけられたときに、震災対策ということで、雲仙普賢岳、あの後の復興対策をどういうふうにされていったか。品川ももしあったときに、どういう準備をしておかなければいけないか。は景観を兼ねて、それじゃあ、その近在のところとかということもちょっと意見を出させていただいて、その部分も少し、今、よいかなとちょっと思ったんです。","respondent":"築舘委員長","answer":"部長の方も何かございましたら、ひとつよろしくお願いします。では、以上で建設委員会を終わりたいと思います。ありがとうございました。","voiceIndex":156,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":31458,"voices":157}},{"id":"h17-20050705-9","meetingId":"h17-cm07","date":"2005年7月5日","dateIso":"2005-07-05","committee":"文教委員会","time":"午前１０時０４分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"校舎改築事業の状況","agenda":"校舎改築事業の状況","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"ちょっと大崎の一貫校の問題で、来年３月に竣工、引き渡しという話があったんですけど、心配なのは、あそこに１６０ｍの東五反田地区開発のビルの影響を受けるのではないかと思うんですけど、受けなければそれはいいんですが、どの程度日影を受けるのか受けないのか、ちょっと教えていただけますか。","respondent":"市川庶務課長","answer":"関係部署から具体的な話がまだ来てございませんので、今後の話になろうと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"都市計画でやるのに、しかも、新築の校舎が一番北側で、太陽を受けようとする建物を建てるのに、１６０ｍのビルが、私は感じとして、午後の日差しが影響を受けるのではないかと思うんですけど、その連絡はないんですか。そういうふうに大問題になっているのに、都市計画決定がされたのに、いまだに説明もないという話だったんですけど、幾らなんでもそれはないのではないかと思うんですけど。","respondent":"市川庶務課長","answer":"言葉を足して説明しますけれども、説明とか連絡が全くないということは一切申し上げていませんで、これからの調整だということで、先ほどの答弁させていただいた趣旨を受けとめていただければと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"私は、今の１６０ｍのビルで、どれぐらい影響されるのかと聞いたんですけど。ないならないでいいんだけど、位置関係からすると、全然なくはない。だから、例えば、冬至で１時間とか２時間とか、それをわかっている範囲で教えてほしいんですけど。","respondent":"市川庶務課長","answer":"そのことも含めて、これからの調整だろうということで、先ほど説明させていただいた次第です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"これからの調整って、どうするかという調整はあるかもしれないけど、現状の１６０ｍでどのぐらい影響があるのかというのは、絶対に日影図を含めて言っているはずなんです。そこからやらないというのは、むしろ奇異な感じがします。何か隠しているのではないかという気がするんですけど。住民には大体日影図は配られているんですよ。","respondent":"市川庶務課長","answer":"少なくとも、私のほうは故意に何事かを隠すとか、そういう意図で答弁を申し上げているわけではありませんで、物理的に考えて、影響が出ることは、影響が出ないわけはないわけで、そのもとでこれから調整をするということで、説明させていただいた次第です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"出かけるところ大変申しわけないんですけど、普通、建物が建てば、日影の問題、特に子供たちは非常に敏感なところですよね。むしろこれからの調整って、都市計画決定されてしまっているんですから、調整も何もないんじゃないか。それは建築段階で事業者がいいと言えば別ですけど、そんなことはかなり困難だと。絶対ないと言えないけれども、その前の段階で調整というのは本来あるべきなんじゃないでしょうか。","respondent":"古川教育次長","answer":"今、委員からお尋ねのあった件につきまして、私も無関心なわけではございませんで、当然、地域の特性から申し上げて、現在あるいは将来にわたって、さまざまな開発が予定されていると。こういうことについては、全体計画の中での可能性については承知しているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"教育委員会は、どっちかというと被害者ですから。この段階で、日影時間がどうかということが所管委員会に示されないということ自体、極めて、では、議会とは何なんだ、所管委員会とは何なんだということを思わざるを得ないです。現在、建設中のものが、しかも、１６０ｍというけた違いの建物が道路１本隔ててできるわけですから、文教委員会にいまだにこの問題が出せないというのは、私は非常に残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認したいんですが、まず、大井地区小中一貫校、それから、第二延山のところで、すまいるスクールの部屋が書いてないんです。多分、児童会室というのがそうなのかと思うんですが、文言を変えるというのがちょっと、なかなか、この図面はいろいろなところに行かれると思うんですが、そういう言葉の統一をしてほしいということと、それがどういうふうになっているのかということ。","respondent":"市川庶務課長","answer":"それと、放課後の動線については、これまで基本設計、実施設計の際に一定程度は説明させていただいたんですが、基本的に管理導線と、それから、すまいるを含めた一般開放の動線というのは、極力区切るようにしています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"ちょっと私、言いたいんだけど、１０時半出発で、１０時半だから、終わった後に時間を確保していただけるんだと思っていたのであれですけど、今質問していいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"南委員","kind":"確認","question":"基本的にその他と今日の報告事項１件だけで視察になっているので、ちょっといろいろ３０分だけの覚悟だったから、１件だから３０分というふうには限らないわけなので。要するに、できるだけ聞きたいけども、聞いて解消すればいいですけど、午後の時間もちょっと約束していただければありがたい、ホッとするなというふうに思っておりますので、そのことだけ確認したかったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"三上委員長","kind":"質問","question":"私としては、本日、見ていただいた中から、それなりにまたいろいろご意見等があると思いますので、別な機会にまたそういう場のことでの時間はとりたいと考えております。ですから、今日はそういう意味にあって、できる限り午前中、いろいろな時間帯を使って解消していただければ、そのほかの点で疑問等があったら、別な機会にお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけこういう視察のプログラムは、もう少し時間を確保していただきたいということをちょっとお願いしておきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":8708,"voices":30}},{"id":"h17-20050705-5","meetingId":"h17-cm07","date":"2005年7月5日","dateIso":"2005-07-05","committee":"総務委員会","time":"午前１０時０４分～午後０時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三村委員","kind":"質問","question":"提供する情報に、区の事業のボランティア活動をというふうに書いてあるんですけど、このホームページを見ると、この学区域内の団体というふうに入っているんですけれども、区の事業以外でも特許申請をしてワゴン型の車で移送サービスをしようというふうに区のＮＰＯとかで活動をしたりとか、そういうようなところの情報もとれるんですか。","respondent":"榎本行財政改革担当課長","answer":"品川ボランティアセンターでも、同じく区内のボランティア団体の紹介をしているんですけれども、そこにたどり着くにはかなりページを追っていかないとたどり着かないという形になりますので、もしそういうボランティア団体の方でもっとＰＲをしたいという形がありましたら。","voiceIndex":7,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認させてもらいます。後からもらった資料の右の下、３番に、既存校舎解体、外構工事の２なんですけど、工事搬入車両が左側から入ってきますよね。このグランド部分というのは、全くそのときは使えない状況になるのでしょうか。","respondent":"宍戸施設担当課長","answer":"この時期はグランドは使えない状態になります。逆に、これまで生徒たちが入っていた部分から工事車両が入る。それから、この赤の部分が生徒の動線ということで、こちらの部分は全面的に改修という形になります。","voiceIndex":13,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"そもそも、そういった中間処理施設の必要性といいますか、これで増設してどのぐらいの機能を発揮して、どのぐらいの処理、全体の発生する支援というかどのぐらいの処理をしていくんだろうというのがよく見えないんですけれども、例えば、ペットボトルなんかですと、かなり回収するのが問題になって、このぐらいの処理が困っていて、それでこれを増設をするとこういうふうになりますというような説明というか。","respondent":"日下部企画財政課長","answer":"一方で、荏原清掃事務所の管内のペットボトルについては、先ほどご覧いただいた大井ストックヤード、今度、資源化センターということで名前も変えられたんですけれども、そちらのほうへ運んで処理しているということで。","voiceIndex":20,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そこら辺を、将来的に何というか、一方ではどんどん排出してくる。自治体のほうで一方では請け負ってというやり方がいいのかという気もするんですけれども、その辺の考え方というのは何かあるんでしょうか。","respondent":"日下部企画財政課長","answer":"最近、特に大きな話題になっておりますけれども、例えば民間の事業者、排出する事業者に対して経費の負担をさせようとか、その辺のところが国のほうでいろいろ検討されているという状況もあります。","voiceIndex":22,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"すると、そこの中の効率性を考えた場合に、確かに両方で３億３,０００万円ぐらいかかるということでどうなのかなと。これは契約ですから全体の話じゃないですけれども、その辺はどう考えるか。経費的な面。もちろん、品川として積極的に取り組んでいるということはわかるんですけれども、あまり細かいところじゃなくていいんですけれども、考え方を教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"今区内の事業共同組合にあちらの運営を委託しておりますが、集約化して量も増えますので、その分については、例えば今、現行業務委託の経費が８,０００万円程度かかっておりますけれども、これが見込みでは１億円強ということで、これは処理量が増えますから。","voiceIndex":25,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。その辺で効率的に進めていただければと。それがどこまで計算しているのかというのを、もう少し考え方としてどうなんでしょうか。あくまで公会計なんで抜いていますということになると思うんですけれども、例えば、これが今度は逆に言うと、耐用年数をどのぐらいで見ているとか、そこら辺はどうでしょうか。","respondent":"日下部企画財政課長","answer":"現時点ではその辺整理しておりませんので、また機会がありましたらしっかり検討するべきだと思います。","voiceIndex":27,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"民間だと、はっきり多少高くなるかもしれませんけれども、その辺は計算した上でやっている。単純にどちらが、コスト計算していくと、こっちが安いですよというのはそのまま当てはまらないところもあると思いますので、自分ではそう思っていますので、当然計算していると思いますけれども、もうちょっとその辺が出てくればという気もしましたので。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"やむを得なくて２社でやったということだろうと思いますけれども、この落札した会社の実績とか、品川区の目標に合った施設は間違いなく設置できるという、品質の面において確認できたということなんだろうと思いますけれども、区のほうではいろいろと、この辺のことの期待もあると思うんですけれども、もう一度ご説明をいただきたいと思います。","respondent":"鷹倉経理課長","answer":"上位ということは、当然そのランクに位置づけられるということは会社の規模、あるいは実績等があるということでそのランクに位置づけられているですので、履行能力につきましては心配ないというふうには考えてあります。","voiceIndex":31,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺と自治基本条例というのをとっているところもあったんで、それは東大阪じゃなかったんですけれども。ですから、岸和田あたり、あの辺でそういうのがちょっと出ていたので、項目としてはその辺がどうかなと。日程的には今おっしゃったそこしか、１０月の後半なので、その中で別途でお諮りいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-009"},{"speaker":"藤田委員","kind":"意見","question":"今、委員長の説明がありました人権問題については、生駒市のほうで、奈良県ですね、生駒というところで、人権文化センターというところがあるんですが、生駒ではかなりこの人権に対しての事業展開が広げられているということで、それも１つのテーマかなと思います。これもぜひ１つのテーマにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-010"},{"speaker":"高星委員","kind":"意見","question":"日取りのことなんだけど、さっき委員長言われたように、去年はみんなで行こうとして行っちゃったというと、これはやっぱり、これは議長もおられるようであります。その辺は一考が要るのなという気がします。ずっとここ数年間の資料を見させていただいても、一斉に同じ日で全員が行っているというのは、去年が初めてなんですね。ぜひともこういうことも視察の項目として入れていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと今話題になったんですけれども、同和問題でいくと、いろいろやっているところもありますけれども、実際にやめたというところもいろいろありますので、行くのであればやめてどういう影響が出てくるのかだとか、そういうところもあわせて行かないとまずいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1690#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":14727,"voices":49}},{"id":"h17-20050706-11","meetingId":"h17-cm07","date":"2005年7月6日","dateIso":"2005-07-06","committee":"自治制度特別委員会","time":"午前１０時０５分～午後 ０時３０分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"木下副委員長","kind":"意見","question":"○午前１０時０５分開会ただいまから、自治制度特別委員会を開催いたします。本日、山路委員長から都合により欠席する旨の届け出がございましたので、ご了承願います。本日の予定はお手元の審査・調査予定表のとおりです。なお、本日は１０時１５分から東京区政会館の視察を予定しておりますので、円滑な委員会運営にご協力をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":1,"id":"exchange-001"},{"speaker":"木下副委員長","kind":"意見","question":"基礎的自治体（特別区として品川区）のあり方に関することということで、本日は２３区の共通事務を取り扱う拠点として、特別区人事・厚生事務組合、清掃一部事務組合、清掃協議会等が入居しております東京区政会館の視察を行います。なお、帰りが１時近くになってしまいますが、ご了承願います。説明をお願いいたします。","respondent":"日下部企画財政課長、桑村人事課長、中山清掃リサイクル課長","answer":"説明文が出ておりますけれども、１点目の「新たな街が生まれます」ということで、２行目に「５月末の竣工」とありますけれども。私のほから特別区人事・厚生事務組合のあらましについてご説明を申し上げます。この資料の裏になりまして、２ページをご覧いただきたいと思います。東京二十三区清掃協議会につきましては、自治法に基づく協議会ということで、前回ご説明したとおり。","voiceIndex":2,"id":"exchange-002"},{"speaker":"木下副委員長","kind":"質問","question":"説明が終わりました。時間の関係で質疑につきましては、現地にてお受けいたしたいと思いますが、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-003"},{"speaker":"木下副委員長","kind":"質問","question":"(1)の議会閉会中継続審査調査事項についてです。お手元の申出書（案）のとおりでよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-004"},{"speaker":"木下副委員長","kind":"意見","question":"ないようですので、これでその他を終了いたします。これより視察にまいりたいと思います。すぐに放送を入れますので、第三庁舎前のマイクロバスにご乗車願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":4038,"voices":10}},{"id":"h17-20050706-16","meetingId":"h17-cm07","date":"2005年7月6日","dateIso":"2005-07-06","committee":"街づくり特別委員会","time":"午前１０時０４分～午後０時１０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"これより、特定事件調査を行います。公有地の活用に関すること","agenda":"これより、特定事件調査を行います。公有地の活用に関すること","exchanges":[{"speaker":"本多委員","kind":"意見","question":"全体的に、総合的にいろんな進め方を考えているのだと思うんですが、日野中学校の近隣ですとか、第一日野小学校の近隣ですとか、文化センターとか教育総合会館の近隣の用地をどの辺まで視野に入れて考えているのか。例えば買収とか、当然目的とか使途によって使い方が決まってくるんだと思うんですが、何にするか総合的に考えているところでしょうけれども、どの辺まで視野に入れているのか。","respondent":"榎本行財政改革担当課長","answer":"今、考えている想定範囲は現有用地という形で、すべて外地の部分は区の公共施設のあるところは区有地ですので、その範囲内で考えているところです。","voiceIndex":11,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"周辺の人口の動向といいますか、わかる範囲でいいんですけれども教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"そこまでの数値の手持ちはないんですけれども、大崎地区につきましては人口が増加している地域ですので、減少しているということはございません。","voiceIndex":13,"id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"防災上は、この周辺はどうなっているのか確認したいんですが、グラウンドは避難場所になっていると思うんですが、そこのキャパであるとか、第一日野小学校もあると思うんですけれども、ここの避難場所というのはどういう使われ方をしているのかというのはいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"現在、日野中学校は、計画上は３町会の避難場所という形で指定されてあります。それが学校としての避難場所で、その後広域避難場所としては自然教育園ですとか、清泉女子大学一帯という形で指定されてあります。","voiceIndex":15,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"３町会の避難場所という形になっているんですが、ここを全部潰すような施設をつくった場合に、３町会の避難場所は第一日野小学校になるかと思うんです。そうなってくると、ここに防災上の何かしらの空地といいますか、エリア的なところを保持した形での視野でしていかなければいけないのか、その辺はいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"それにあわせて、区も検討していかなければいけないということがありまして、総合的に避難場所も指定していかなければいけないかと考えております。","voiceIndex":17,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"先ほど、耐震診断をした形で建て替えは順次考えていくと言っていますけれども、全体的に考えたときに、どうしても第一日野小学校も含めた形で考えていくのが効率的のような気がするんですが、その辺の考え方はいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"ですから、ここを一帯の敷地として使うというのが円滑な交通が守れるのかどうかというのと、やはり傾斜地ですので、高さでいきますと日野中学校のところが一番高くて、その次が文化センターで、第一日野小学校はもっと低いという形になっていまして。","voiceIndex":19,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"この地域の公園の充足率というのでしょうか、他の地域に比べてどういうふうになっているのかというところと、公共施設の問題も同じように、どういうようになっているかということ。それから、プランニングをするにあたって、住民の声をどういうふうに聴取していこうと考えていられるのか、その３点をまず伺いたいと思います。","respondent":"榎本行財政改革担当課長、松代道路公園課長","answer":"公共施設の関係ですけれども、公共施設につきましては教育総合会館という形で、文化センター、教育センター、プラネタリウム、図書館が入っておりますし。きちんとした資料が手元にございませんけれども、周辺のところでいいますと、区立公園は西霧ケ谷公園、西五反田公園等々がありますけれども。住民の声ですけれども、今現在原案をどういうふうにつくろうかと多角的に検討しておりまして、原案を出した段階で。","voiceIndex":21,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"公共施設については高い、公園は少ない、端的にいうと、そういうことです。それと、公共施設というのは１カ所に集中することも大事で、規模の大きいものをつくるのも大事だけれども、この地域は人口も密集しているし、人口も増えているという先ほどの話なので、そういう点で、いっぱい集えるようなところを点在させていくということが一方で必要ではないかなと思いますので、その点について伺いたい。","respondent":"榎本行財政改革担当課長","answer":"１点目の文化センターにつきましては、今総合実施計画の中でも文化センターの本館がかなり老朽化しているという形で、その辺の部分は計画として考えておりますので、その辺も含めて、やるかどうかもあわせて考えているところです。","voiceIndex":25,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"公共施設については、点在しているという話ですけれども、どういう施設ができるか、これから議会側のいろいろな議論の中で反映させていかなければいけないと思っていますけれども、地図で見てもわかるように、公有地の周辺は一方通行だし、道路も狭いし、坂もあるしという形で、いろいろ問題がある地域でのプランニングだから、そういうことも含めて検討していかなければいけないと思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、当面は絶好の空き学校ができたわけですから、１年、２年というのではなくて、５年、１０年先を考えた場合、学校改築はしなければいけない。仮校舎云々というと、相当金額もかかる。最後に質問だけしたいんですけれども、日野中学校がいよいよ使わなくなりますけれども、このグラウンドに関しては今後も地域に継続して開放していただけるのでしょうか、そこだけお願いします。","respondent":"榎本行財政改革担当課長","answer":"まだどういう使い方というのができていない段階なので、なるべくそういう声を聞いた上で、総合的に今まで使っていた用途とか、そういうものも含めて一番いい手段を取っていきたいと考えております。","voiceIndex":28,"id":"exchange-009"},{"speaker":"本間委員","kind":"質問","question":"今、日野中学校跡地、公有財産の有効活用という形で議論しておりますが、文教委員会との兼ね合いの部分はどうなっているのか、不思議だなという感じにも見えます。街づくり特別委員会として、議論の対象で進めていいのかどうかということが一つ。それから二つ目、この地域でこれまで学校施設が住民に対して果たしてきた役割についての意見をお伺いたいという２点をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-010"},{"speaker":"本間委員","kind":"意見","question":"そうしますと、そういう視野でものをとらえて、開発というようなことで進めていいと。もちろん教育環境とかそういうものも視野に入るかもしれませんが、事が学校だけにグラウンド、校舎を含めて、枠を抜きにして話を進めていいと。","respondent":"榎本行財政改革担当課長","answer":"この地域で果たしてきた役割という形ですけれども、学校教育の施設としてそれぞれ中学校としての役割を果たしてきた上に、先ほど副校長から説明がありましたけれども、地域にグラウンド開放をしておりまして、それぞれ少年野球、少年サッカー。","voiceIndex":32,"id":"exchange-011"},{"speaker":"本間委員","kind":"質問","question":"防災上の件ですが、どなたかからもお話が出ていましたが、避難所としての位置づけがあるということで、それぞれ学校を主体として避難所連絡会議等々が定められてきた経緯がある中で、そのものの中身がなくなってしまうのではないか、その件についてはいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"ですから、この地域をどのように使うにしても、避難の考え方も取り入れた上で、実際上計画を立てていかなければいけないと考えております。","voiceIndex":34,"id":"exchange-012"},{"speaker":"本間委員","kind":"質問","question":"そういう観点も視野に入れた議論が可能かどうかということも含めて、質問します。","respondent":"榎本行財政改革担当課長","answer":"ただ、そうは言え、スポーツができるような公園という施設は、ここの地域にはありませんので、そういうものも含めてあわせて検討していかなければいけないと考えています。","voiceIndex":36,"id":"exchange-013"},{"speaker":"三上委員","kind":"確認","question":"現実を確認させてもらいたいんですが、資料の裏面に校舎の配置図がありますが、１階平面図の右下が空き地みたいに広くなって書いてあります。ここの部分が含まれた総敷地面積と考えた数字なのか、どういうふうに受けとめたらいいのかということです。教育センターが入っている部分だと思うんだけれども、あくまでも敷地面積の中に教育センターを入れているのか入れていないのか。","respondent":"榎本行財政改革担当課長","answer":"総敷地面積の中には入っておりません。空き地みたいに見えるのは、屋上プールが入っているということで、中学校の施設が入っているという意味で、ここが囲まれているという形ですけれども、敷地としては入っておりません。","voiceIndex":38,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"そうすると、教育センターのプールは確かにプールとして中学校が使っているけれども、検討する範囲の中にそれを入れるのか入れないのかということはきちっと分けておかないと、そっちのほうまで含んだ範囲の議論になってしまう。だから、そこのところはきちっと分けておく必要があるのではないかと思うんですが、いかがですか。","respondent":"榎本行財政改革担当課長","answer":"資料のつくり方の部分ですけれども、敷地の範囲としましては、１ページ目の黒く太線で囲ったところが日野中学校の敷地という形でとらえておりますので、それが１万２,０００m2という形です。","voiceIndex":40,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"グラウンドと校舎の間に渡り廊下があるんですけれども、下は区道になっているんですか。渡り廊下というのは、どういう解釈というか、どういうような地位を持つものでしょうか、それを教えていただきたい。","respondent":"松代管理工事課長","answer":"ちょうど区道の上に渡り廊下みたいな感じで架かっている橋です。横断歩道橋という位置づけでなされていると承知しております。","voiceIndex":42,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、横断歩道橋ということであれば、唯一右と左を結ぶ線として歩道橋があるわけで、これが生きているのであれば、将来的に総合性を持つのであれば、このような形状を取れるんですか。ビルとビルの間に渡るものがありますね。デパートとデパートを結ぶようなものがよくありますが、そういうような形でできるんですか。","respondent":"岩田まちづくり事業部次長","answer":"道路法の規定では、この近くでは丸井、きゅりあんのところが男の館と女の館が上空で２カ所接続していますけれども、あれは上空通路という位置づけで、占用物件として扱っております。","voiceIndex":44,"id":"exchange-017"},{"speaker":"伊藤副委員長","kind":"質問","question":"端的にお伺いしますけれども、一つは今回の計画は黒い線の範囲の中だけでしょうか。なぜかといいますと、隣に教育総合会館とかその他区の施設があるわけで、素人の考え方ですけれども、これを一体にしたほうが有効的なものができると思うんですけれども、なぜそれを外したかということをお聞かせください。そのプールは将来どうするのかということをお聞かせください。","respondent":"榎本行財政改革担当課長","answer":"新館のほうから直接行かれる通路がありませんので、外階段の利用になっているので難しいかなと考えています。","voiceIndex":46,"id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"確認","question":"今、気になったのが、これからの検討の中で教育総合会館も視野に入っているような答弁をなさいましたね。その前提をここではっきり私たちがわかっていないと、これから検討する中で各会派からいろいろなアイデアがこれから出てくるでしょう。その中に黒い線の中だけなのか、もしくは外側も視野に入れていいのかという確認をきちっとしたいと思いますので、いかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"この線の枠内にするというのが、まず出発点ですけれども、そこで第一段階で出発点の部分でどうするかという考え方が一つ。それから、出発点の中で考えきれない場合に、第二段階として枠を広げるのかどうかという形も含めて検討しているという形です。","voiceIndex":48,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"そうすると、まずは黒い枠の線の中で考えるけれども、例えばその中のプランニングで、どうしても隣の教育総合会館も考えていきたいということになれば考えるということでいいんですか。","respondent":"榎本行財政改革担当課長","answer":"併せて考えるということで、そういう形になります。","voiceIndex":50,"id":"exchange-020"},{"speaker":"伊藤副委員長","kind":"質問","question":"そうすると、議会もいろいろ考えていくにあたっては、そういうことも含めてプランニングしてもいいということですか、そこをはっきりしないと、これからそのことを議論していく前提が成り立たないんです。","respondent":"新美企画部長","answer":"ただ、絶対含めるとか含めないということも併せて、そのくらいきちんと今後の計画を、それもまた暫定なのか、完全に長期的な計画をこの段階で固めるのかといういろんな選択肢がありますので、その辺を原案づくりということでこれまでも検討してまいりましたけれども。","voiceIndex":52,"id":"exchange-021"},{"speaker":"宮崎委員長","kind":"質問","question":"ほかになければ、私のほうから１点伺いたいんですけれども、放射２号線との関係で事業化が決定しているんですけれども、その関係で例えば建物を建てるということになると、いろいろな制限が出てくるのではないかと思うんですけれども、そういう関係でここは一部道路で削られると思うんですけれども、その辺もどういう関係になるかなというのがわかりますか。","respondent":"榎本行財政改革担当課長","answer":"ただ、ここの部分で削られますけれども、実際にはここの用地自体は準工業地域ということで、それぞれの規制が大きく変わるとは考えておりませんので、道路に面するところが左側のグラウンドのところにあるというふうに今のところ思っております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"三上委員","kind":"質問・要望","question":"一番心配しなければならないのはそこなんです。だから、そこのところをどういうふうに区としても考えるのか。今確定していない話、１０年間という話が出て、そういう計画がありますよという形でみんなが認識した上で、それをどういうふうに共通する考え方として、とりあえずこういう考え方としていきましょうということでの説明をできるようにしておかないと、それも委員長、考えていただきたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"したがって、今の段階で区として、放射２号線がいつ東京都として着手するのかというのは、全く情報を持ち合わせておりませんけれども、区内全域の都市計画道路の進め方からすると、当分長期的ではなかなか難しいかなと。","voiceIndex":60,"id":"exchange-023"},{"speaker":"三上委員","kind":"質問・要望","question":"今、裁判になっていますけれども。今、裁判を起こした人たちは、直近まで東京都に何回も確認をしに行っているんですよ。「ここはその計画はまだ始まりませんよね、どうなんですか」と確認をしに行っているんです。ある人は３回行って、３回とも大丈夫ですよと言われた。だから、そういうことが決してないような形でやらなければならないわけですから、東京都にそういうばかなことだけはやめてもらいたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":14827,"voices":67}},{"id":"h17-20050707-14","meetingId":"h17-cm07","date":"2005年7月7日","dateIso":"2005-07-07","committee":"行財政改革特別委員会","time":"午後２時１７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に特定事件調査を行います。 行財政改革に関することのうち、１民間委託等に関すること","agenda":"最初に特定事件調査を行います。 行財政改革に関することのうち、１民間委託等に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"委託先の受け皿の形態というのはいろいろある、派遣もあるし、非常勤という形もあるし、アルバイト、パートみたいなものもあるのかもしれないんですが、改めて、品川区で、現在、委託している事業を、個別でなくていいんですが、全体の中で、派遣が何社で、派遣で実際に仕事についている人が何名なのか、あるいは、非常勤がどれぐらいでという、種別の全体的な傾向を教えてもらえればありがたいんですが。","respondent":"桑村人事課長","answer":"それから非常勤の職員ですけれども、平成１７年４月１日現在の数字ですけれども、８８７名です。これは、いわゆる専門の委員等も含んでの数字です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"非常勤が８８７名で、臨時職員が３０名から４０名で、人材派遣については、従業員数が２９９名ということでいいんですか。要するに、会社として受け皿となっているのは何社で、実際に、そこで区の業務についているのが何人ぐらいかということが、わかったら教えてほしいんです。","respondent":"桑村人事課長","answer":"すみません、ちょっと資料の言い方がまずくて申しわけございませんでした。従事者数というのは、例えば保育園ですと６６３名と書いてあるんですが、これはいわゆる保育士と人材派遣の業務が、保育園の保育業務としてやっている人数が６６３名という意味なんです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"何となく、わからないですよね。６６３名は保育士全体の数だというのはわかったんですけれども、１１４名が人材派遣なんだけれども、会社数としてどうなのかというのは、次回、ちょっと教えていただきたいと思います。それからもう一つ、これは意見ですから、あれですけれども、営利企業に委託をしていくことによって、営利が優先されていく。きょうはここまで、意見だけを最後に出しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"委託をされた業者が、どういう仕組みでやっていて、人、それからアイデア、考え方というのか、そういういろいろなものを出してくる、出してもらうということが委託のメリットの一つでもあると思うんです。","respondent":"榎本行財政改革担当課長","answer":"例えば、しながわ中央公園を委託をしておりますけれども、そこにつきましても、実際に、公園管理を直営でやっている公園と、委託でやっている公園を比べて、経費がどれぐらい落ちるのかの比較もしておりますし、当然、サービスの質の部分で。","voiceIndex":14,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"民間委託というけれども、いわゆる民間の事業者、要するに委託をされないで、それぞれ民間として生きているというか、活動している事業者、企業というか、個人企業から、大企業までいろいろある、それぞれの民間が独自に民間としてやる場合に、いろいろな、沢田委員が言うと、利益を上げるためというか、もちろん企業だから、利益を上げるため、個人企業主は生活のために。","respondent":"新美企画部長","answer":"その契約において、どこが成功し、どこがまだ足りないのかは、今回ちょうど、今の管理の委託が指定管理者制度へ移行するということで、先般の一般質問でも、第３回定例会に、現行、管理委託しているものについて、今後、どう切り換えていくかをご提案しますが、この機会に。","voiceIndex":16,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"こういうのは、行政としていいかどうかわからないけれども、やってみなきゃわからないというのもあるじゃないですか。デメリットというか、それをなくすためには、ゼロが理想でしょうけれども、ゼロというのはなかなか、１０人にサービスして、１０人が１００％満足というのはなかなかないわけで、出てきた苦情に対しての対応を、民間委託するときに、契約でどういうふうになっているのか。","respondent":"榎本行財政改革担当課長","answer":"例えば細かい仕事ですと、契約書というか、仕様書できちっと縛ってしまうということで、その仕様書の範囲外は、もうお金の換算にないという形になってしまいますので、その中に、幾つかいろいろな契約、例えば、維持改善、維持補修から保守点検とか。","voiceIndex":19,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"この問題と、さっき出た人材派遣の人の使い方というのか、職員の配置の仕方というのか、これとの関係で、いわゆる行政がやらなきゃいけないんだけれども、職員も、いわゆる区職員に限られるのか、どうか、そこら辺の線引きだけ聞かせておいてください。","respondent":"榎本行財政改革担当課長","answer":"業務委託がよければ、範囲を区切って民間業者に委託する場合、それから、逆に、区の職員のもとで指揮命令をしたほうがいい場合であれば、非常勤職員、もしくは人材派遣という形で、指揮監督をしながら、職員と一緒に仕事をするというような形で。","voiceIndex":21,"id":"exchange-007"},{"speaker":"三村委員","kind":"質問","question":"先ほど、委託先の評価という話が出ていましたけれども、聞いていましたら、提供されるサービスについての評価はいろいろ入っていたんですけれども、実際にその中で働いている人たちが、サービス残業をさせられていないかとか、不当解雇されていないかとか、そういう委託先で働く人たちを、きちんと雇用者側が責任を持って管理していますとか、そういう視点での評価というのは、されているんですか。","respondent":"榎本行財政改革担当課長","answer":"そういう民間企業が、きちんと法令を守って企業として成り立っているかという形は、当然、その法令を守った企業を選んで委託をするという形になりますので、それを直接区が、その企業体自体が法令に適合しているとか、していないとかという形での評価はしませんけれども、実際上。","voiceIndex":23,"id":"exchange-008"},{"speaker":"三村委員","kind":"質問","question":"そういう評価はしなくても、契約の中に、労働者に対して不正行為が認められた場合は、契約を解除しますとか、そういったところまで入れることは難しいんですか。委託先で働いている人も品川区民がそこで働いているということを考えると、働いている側の視点に立って、きちんと労働条件を整備していくという考え方も、今後必要なんじゃないかと考えるんですけれども、その辺について、ご意見がありますか。","respondent":"榎本行財政改革担当課長","answer":"直接、その企業で働く人を評価というのはできないわけですけれども、実際上、区が民間事業者に委託するときというのは、事業者登録という形をやっておりますので、その中で、その企業が、今までどういう形で事業を進めてきたのか、実績等がどうなっているのか。","voiceIndex":25,"id":"exchange-009"},{"speaker":"築舘委員","kind":"質問","question":"ですから、評価とともに、人材派遣、要するに会社に派遣をすることが、具体的にどういうメリットがあって、そして、今までの非常勤、アルバイトの人たちが、どういった形での評価でそういうことにするんだみたいな話を、しっかりとしておかないと、やっと私たち慣れたのに、もう私たちは終わっちゃうのかみたいなことで、せっかく民間の人たちがやる気を起こして頑張っている人たちが。","respondent":"桑村人事課長、新美企画部長","answer":"もう一つはやはり臨時的なもの、あるいは、非常に特殊といいましょうか、一定期限が決められたようなもので、その意味では、人材派遣業そのものは、まだ、非常に長い期間を予定しているものになってございません。ただ、全部が全部そうとは言いきれないのではないかと、とりあえず、認識しています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"そこが１点。だけれども、一般の福祉会社の民間の人たちの給与よりは低いんですよ。結局、全部正職員を採れないわけですから、そこで工夫をしながら、民間からアルバイト、非常勤で採っているわけなんですけれども、それがなかなか給料が低いために、人材が集まっていないというのが、それは調べていただければわかりますけれども、それが一般的ではないかと思うんです。","respondent":"桑村人事課長、新美企画部長","answer":"その意味では、先ほどからいろいろ出ていますけれども、いわゆる違法なことが行われていたり、考え方が少し整理ができなかったりするのは問題だと思ってありますので、これについては。社会福祉法人についてのご質問ですけれども、品川区におきましては、区内の社会福祉法人とは、経営者といいますか、責任者クラスとの定期的な意見交換の場を持っておりますので、そういう場で、できるだけ実態を把握して。","voiceIndex":30,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"委託のメリット・デメリットのところなんですけれども、この間、区のいろいろな行政のところで委託が広がっていますけれども、コストの削減と、質の向上のところなんですね。そういった面で、今のシステムの中で、質が確保できるのかどうか、その点を１点、まずお伺いしたいんです。","respondent":"榎本行財政改革担当課長","answer":"もちろん、それは直営でも同じですけれども、直営の場合については、きちんと中で人材を育てていくという形で、仕事の経験等のレベルアップを図っていくという形ですけれども、そういうものと相まって、委託した場合には、民間の人を使いながらきちんとしていくという形ですので。","voiceIndex":33,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際、その辺をお伺いしたい。私がなぜこだわるのかというと、今、子どもたちの育ちもすごく心配をされているし、高齢者の施設の不備のところで、虐待の問題もありますよね。特に、ちょっと具体的な中身にいかないとわからないので、例として聞いてほしいんですが、保育の質のところで、アメリカなんかは、すごく質とコストの専門性という研究が進んでいるんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面では、先ほども、デメリットのところに、管理が間接であるために、ちょっとその辺が不十分になる場合があると書かれているんですけれども、やっぱりこの辺のことを、賃金も含めて、労働環境の質の確保が重要であるというところを、仕様書の中にどうのこうのと言われていますけれども、きちんと盛り込んでいかないと、確保ができないと思うんです。その辺をどうとらえていらっしゃるのか。","respondent":"桑村人事課長","answer":"人材派遣の部分と、いわゆる民間委託の部分と、ちょっと考え方が違うかと思うんですが、一つは、人材派遣でここに出している数字の単価というんでしょうか、区の職員の比べての単価ということですが、これはほぼかわりございません。","voiceIndex":41,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"わかりました。今、指揮命令系統のところに触れられたんですけれども、労働条件とか、そういった面で、派遣の職員が、会社から言われてきている中身と、派遣された先での内容とのところで、人権を守っていくための歯止めって、どういうところがあるんでしょうか。","respondent":"桑村人事課長","answer":"もちろん、その方個人の問題と、会社とも契約しているわけですので、例えば、１週間以上いなくなった場合に、代替の職員を求めるかどうかについては、また別途の契約になろうかと思いますけれども、基本的に、いわゆる労働者が働く上での労働基準法の権利関係については。","voiceIndex":43,"id":"exchange-015"},{"speaker":"中島委員","kind":"質問・要望","question":"その反面、今、民間でも、一生懸命自助努力というんですか、いかにサービスを向上させるかとか、気持ちよく働いてもらえるかとか、そういう努力をしている経営者も、私も存じ上げております。(2)の中に、委託のチェック体制のとり方によっては、コスト高となるということがあるんですが、これはどういうことなのか、教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"要は、競争がきちんとできて、ノウハウが比べられるもので委託に入るという形が一番ベストな形だと考えております。","voiceIndex":45,"id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、独占的な業者だとか、長期間にわたる委託が続いているところは、品川区内では、どのぐらいあるんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"必ず何年かに１回、契約、プロポーザル等、入札等をやり直しておりますので、基本的には、そういう長期契約というのはございません。","voiceIndex":47,"id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"わかりました。ここにメリットの中に、技術専門家をみずから養成する必要はないということで、プロを養成する必要ないという反面、民間に任せて、こちら側の管理がどの程度まで機能するかということが、私は大事ではないかと思うんですが、その辺の対策はどのようにされているのでしょうか。","respondent":"榎本行財政改革担当課長","answer":"そういう建物の維持管理関係以外に、情報システム関係も同じような形になるんですけれども、かなり高度な部分については、民間事業者という形で活用していきますけれども、それがどういうふうに比較考慮できるのかとか、そういうある程度の知識を持った職員は。","voiceIndex":49,"id":"exchange-018"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、各分野分野に専門家がいるということなんですね、きちっとした人が養成されている。この辺はどうなんでしょうか。","respondent":"桑村人事課長","answer":"まさに、そのような方向で進めているわけですけれども、一ついろいろな考え方があろうかと思うんです。例えば、公認会計士をお願いするとか、区の職員としての一定のレベルというのはあろうかと思うんです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに、チェックする専門家も委託という形もとれると思うんですが、そこのところの機能がしっかりしないと、例えば建物なんかにしても、せっかく建てて、お金をかけているわけですけれども、後からまた経費を追加しなきゃいけないとか、そういうマイナス面も出てくると思いますので、さまざまな面で、その辺のところは対処していただきたいと、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認をさせてもらいたいんですけれども、例えば、派遣会社から派遣されたと、そこにおける指揮命令系統は、当然、担当部署にある。それが、派遣された人材が、どうしても合わない、能力的にちょっと低いようなケースが、ままあると思います。当然、民間の会社ですから、そういうことがないようにするのが一番だし、それを選んでいるはずだと思うんですけれども、その辺の確認をお願いします。","respondent":"桑村人事課長","answer":"いわゆる、契約の中で、その業務に不適当だというようなことになった場合は、取り替えることができるという規定は入ってあります。ただ、これ自体、なかなか判断するというのは非常に難しい部分があります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今、あえて言わなかったんですけれども、特別支援保育の部分が今後どうなるのかなというのが、ちょっと気になったんです。やはり民間企業ですから、当然、受けるためにきちんとやっていると思うんですよ。この辺は、連絡会をとらないで簡単に対応できているのかどうか、その辺の確認をしたいんですが。というのは、ちょっと前にあったんですけれども、夏の暑いときに、温度を２８度設定している。","respondent":"榎本行財政改革担当課長","answer":"苦情の対応の、軽微なものについては、現場でそれぞれ対応できるような形で、あとで報告の件数等が出てくるというものですけれども、実際上、区のほうに、いろいろそういう連絡会等を開かなければいけないような状況というのは、逆に、窓口のほうに言っても解決しないので、直接。","voiceIndex":56,"id":"exchange-022"},{"speaker":"藤田委員","kind":"質問","question":"他の事業部から、ここはこうしたほうがいいんじゃないかというようなこともあるんではないかなと思うんです。そうした意味で、区として、例えば民間委託検討委員会というようなものを設けて、例えば電話交換業務は、区としてどうなっているのか、公用車の運転はどうなっているのかなど、一つ一つきめ細かに、区長を先頭にして検討委員会というのを開くべきではないかなと思うんです。その辺はどうでしょうか。","respondent":"新美企画部長","answer":"当然、こういう新しい動き等も含めて、議題、あるいは情報交換をする場を持っております。その経営会議を活用して、今のご趣旨のような、自分のところだけではなく、他の事業部がどうしているのかといったことも含めて、共通の認識にしていきたいと考えております。","voiceIndex":58,"id":"exchange-023"},{"speaker":"藤田委員","kind":"意見","question":"先ほど、いろいろな委員がおっしゃいましたけれども、人材派遣に依頼をすれば、どういうサービスが行われているのか。これは人材派遣だけではありませんが、民間派遣業者も同じです。やっぱり、チェックをきちっと働かせて、民間事業者はどういう区民に対するサービスを行っているのか、いろいろな声を聞くという姿勢、体制というのは必要ではないかなと、私は意見を申し上げまして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-024"},{"speaker":"川西副委員長","kind":"質問","question":"資料の説明の質問をいたします。３ページの一般事務における委託実施団体比率というところなんですが、一般ごみ収集、２３区、品川区とありますが、これは雇上業者の入れるパーセンテージを指しているのかどうか、伺っておきます。それから、その下に学校給食というのがあります。配送センター方式、あるいは、品川区でやっている調理委託、あれが両方重なっているパーセンテージなのか。","respondent":"榎本行財政改革担当課長、桑村人事課長","answer":"それから保育園の調理の部分につきましては、施設運営のほうの(2)の、保育所の中に、一部というような形での表記という形で入りますので、保育所運営の中で委託業務が入っていれば。７月現在というのは、いわゆる延べ人数ではなくて、７月現在の実人員ですので、私どものほうで調べた限りでは、選挙の部分は当然抜けますけれども、この後、９カ月間、同じような形で続いていくものと思ってあります。","voiceIndex":61,"id":"exchange-025"},{"speaker":"川西副委員長","kind":"質問","question":"保育所の中に調理委託の部分が入っているということですが、調理委託はかなり部分で実施が進んでいる。ですから、一部というのも、数字が全然明確でなく、もうちょっと詳しく知りたかったなと、これは意見だけです、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほど、飯沼委員の質問で、派遣労働で働いている人と、正規職員で差はないという答弁をなさったんですけれども、これまで、民間委託を進めるときに、正規職員は年間８５０万円かかると。平均的な問題でもいいですし、例えば、学校給食の民間委託、これは業務委託ですけれども、それではどうだとか、派遣労働でどうかというのを、ぜひ調べていただきたいということが一つ。以上、３点です。","respondent":"須藤委員長、桑村人事課長、新美企画部長","answer":"資料の要求ということと、数字的なものがわかればと。今、お答えいただければ、お答えをお願いします。これは、求めているものが、一定の経験だったり、例えば保育士の資格を持っていたりして、賃金体系が変わってくると理解しておりますので。社会福祉法人の件ですが、先ほど申しましたように、特に平成１２年を契機に、それまでどちらかというと。","voiceIndex":65,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"私、なぜこれを聞いたかというと、先ほど、公務員並みに、都の職員並みに補助制度があるから差はないと言うけれども、それが今度削られて大変なことになっているというので、事実と違うんじゃないかという意味で出させていただきました。そのときに、やっぱり区のほうがチェックを、そこにも目を届かせていく必要があるということを申し上げたいと思うんですが、それについては、いかがでしょうか。","respondent":"本間総務部長","answer":"先ほど来、ご答弁させていただいていますとおり、同一労働同一賃金と言いましても、それぞれが持って、担っている責任ですとか、資格等々によって、当然、具体的な賃金というのは異なってまいります。","voiceIndex":69,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問・要望","question":"だから、公務員は民間企業に横並びにするけれども、派遣会社は、そこに働く労働組合との話し合いで決めているから、そこにどうのこうのと言っているんですけれども、実態的に見て、頭で考えるんじゃなくて、私は、派遣労働を実際している人の給与や待遇がどうなのかというのを示してほしいということを言っているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"どうですか、こうですか、ああですかって聞いているだけでは、委員会の機能として役に立っていないので、例えば、民間委託をすべき事業を、この委員会で取り出していく、あるいはしないほうがいいという意見も、当然出てくるでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"沢田委員","kind":"意見","question":"今後、民間委託をどうするのかというまとめになるのか、そこはまだ私はわかりませんけれども、今の段階はその準備の段階で、私は非常に大事なことをやられているんじゃないかなと思います。だから、今しばらく、現在やってきた民間委託の問題で、意見交換や、資料を出してもらって、検証していくということでいいんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"他の問題と絡むと思うんです。前回は、並行してやっていこうという話でしたよね。そうしますと、あと二、三回というと、例えば議員定数削減問題なんかに重点を置いて、あとはそっちでやっていこうというのか、並行していこうというのか、ちょっと考え方を整理していただけるとありがたいんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-032"}]},{"id":"topic-02","title":"議員定数に関すること","agenda":"議員定数に関すること","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"いろいろな切り口、それから、考え方あると思うんですよね。よく言われるのは、区民の声を聞くというんだけれども、じゃあ、定数についての声というと、なかなか出てこないのが現状だろうと思うんです。それも総務委員会なのか、議会運営委員会なのかというのも議論されたところですけれども、一つの今年の品川区議会の決め事の中では、ここでやるということですから、やっていく。","respondent":"市岡区議会事務局長","answer":"実は、かつては、住民何人当たり１人の議員が根拠になりそうだとか、人口と議員数ということの相関関係というようなことが議論されたことがありますが、最近は、それはあまり論理的には説明がつかないだろうというのが、これは学者含めて、一般的な見解になっています。","voiceIndex":88,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、もちろん意見としては出し合っていくのは必要なんだけれども、最終的には、外部の人の意見というのか、識者というか、そういう方々の意見も聞きながら、我々が冷静にというか、中立にというのは無理な話で、どうしたって自会派中心的な考え方の議論の応酬になるんだけれども、そういう外部の意見というのは、今言った、歴史的ないろいろな流れがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"それは、各市区町村一緒なのか、それとも２３区だけのものなのか。東京都と国会は補欠選挙があるんだけれども、区議会に限ってないのは、何か理由があるんでしょうか。その辺のところが、もしわかれば教えていただきたい。","respondent":"市岡区議会事務局長","answer":"それからもう一つ、全く深い意味はありませんけれども、これにも例外がありまして、親選挙といいますか、もう一つ別の選挙があった場合、例えば首長の選挙がある場合には、６分の１を超えるところまで待たないで、補欠選挙を親選挙に付随する選挙として行うという規定が。","voiceIndex":92,"id":"exchange-035"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、例えば、私も勉強不足で教えていただきたいんですけれども、都議会では、例えば、何年か前に大田区で補欠選挙がありましたけれども、あれもやっぱり、全体で見ると法定定数の６分の１を超える減が、あの段階で出たということで、補欠選挙が行わたのでしょうか。それとも、都議会の場合は、また別の何かルールというか、条例があるのか。その辺を教えていただきたい。","respondent":"市岡区議会事務局長","answer":"特に、国会なんかでも、そういう親選挙があった場合に、国会議員の補欠選挙を行ったというような報道がよくありますけれども、多分、そういう例だと思います。","voiceIndex":94,"id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"なぜこんな質問をしたかというと、議員が、例えば４２人と品川区で決めて、それが必要なんだという前提で言えば、３名減って、何で補欠選挙をやらないんだという部分と、都議会とか国会では、１名でもやっているような、私、そういう認識に誤解があったもので、その辺の考え方の違いがあるのかなということで、ちょっと今、お聞きしたんですけれども、わかりました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-037"},{"speaker":"築舘委員","kind":"質問・要望","question":"ちょっと質問なんですけれども、平成１５年１２月３１日現在での人口ですけれども、その後、品川区の場合はかなり増えてると思うんですが、今のところ、何人というのがわかれれば教えていただきたい。それから、上限数というのが、一応、増えたり減ったりするところがこれからもあるわけで、その辺、今後、どういう形で２３区の場合、また数を決めていくものなのか。","respondent":"市岡区議会事務局長","answer":"ただ、区分で申し上げますと、３０万人から５０万人までは４６人で同じですので、もし上限数が増えるとなると、品川区は５０万人を超えないと増えないということになりますから、あまり影響はないということです。","voiceIndex":98,"id":"exchange-038"},{"speaker":"沢田委員","kind":"提案","question":"手元に資料があったら、教えてほしいんですが、全体の総予算に占める議会関連費の割合の推移みたいなものが、もしあれば教えていただきたい。それから、２３区でそれを比較したらどうなるのかということが、わかったら。きょう、なければないで、次回でも結構なんですが、教えていただきたい。もしあれば、教えてもらえるとありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-039"},{"speaker":"沢田委員","kind":"質問","question":"今回の委員会は、また新しい構成メンバーですから、それから、直近の資料という点で出していただければありがたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"２３区の表でいくと、江戸川区と杉並区が、１０人、８人と、減員数では多い。それから、多分、港区、新宿区あたりは、法そのものの数字が変わって減ったから、法定上の数字でいい、条例で減らさなくていいということだろうと聞いているんですけれども、従前からあって、減らしていないところはあるんですか。２３区の中で、法律で人口に合わせて定数が減ったから、減らしたというところは、ほとんどですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-041"},{"speaker":"大西委員","kind":"質問・要望","question":"私も、先ほど、沢田委員が言われた資料要求と、ちょっとダブルところがあるかと思うんですが、品川区で、議員定数を４６人から４２人にした時点の、品川区の人口。それから、４２人にしたときの議会費の占める割合。それから、現在の状況での、議会費の割合。要するに必要性があるかどうかということです。議会費の占める割合がどう推移しているかということで、ちょっと調べていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-042"},{"speaker":"藤田委員","kind":"質問","question":"区の広報で、区政モニターという制度がありますね。そういうところに、品川区の議員の数について、今まで調査といいますか、した経緯があるのかどうか。もし、今までやっていないという場合は、あれはどういう期間でテーマを決めて調査をするのか。その辺、ちょっとわかったらお聞きしたいと思います。","respondent":"市岡区議会事務局長","answer":"モニターですけれども、これは毎年、１年間の委嘱ということで、地域、年齢、男女別、これらを考慮しまして、募集をして、一定の枠の中で決めるというやり方をとって、その１年間の一番最初のときに、勉強してみたいテーマ、あるいは意見を言いたいテーマというのを出し合って。","voiceIndex":110,"id":"exchange-043"},{"speaker":"藤田委員","kind":"意見","question":"そうしますと、議会の自立性の尊重ということを、区長部局で考えているのであれば、例えば区議会として、仮に、各会派で皆さん一致した場合は、区政モニターの人たちの考えは、議会として聞けるのかどうか。そういうシステムになっているのかどうか。","respondent":"市岡区議会事務局長","answer":"議会の総意として、そういうテーマを取り上げてもらいたいということを依頼をすれば、十分に可能だと思います。","voiceIndex":112,"id":"exchange-044"},{"speaker":"藤田委員","kind":"意見","question":"私たち、まちを歩いていますと、まず国会議員の数が多いということ。そうしたことを十分に、私たちも認識をして、では、区議会としての人数をどうすべきなのか、定数はどうすべきなのかと、そうしたご意見のもとに、こうして行財政改革特別委員会の中で、一つのテーマとして挙がっているわけです。今、答弁がありましたけれども、これはひとつ参考にしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-045"},{"speaker":"大西委員","kind":"質問","question":"ある人は、身近に区議会議員がいないので、いろいろな相談ができなかったと言われる方もおられるので、そういう点では、私は、一般的に勉強されている方々のご意見を伺って、皆さんで意見を出し合っていくというふうな方法を進められることを希望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-046"},{"speaker":"沢田委員","kind":"提案","question":"そういう思いと、林委員が言われた、それから、事務局長が最初に言われた、議員の役割と権能の問題というのが、やっぱり大事なポイントなんじゃないかと思うので、ある程度、そういう識者の意見を聞いて、今後の審議の参考にするというのは、非常にありがたい提案だと思うので、どういうやり方にするかは、ちょっと検討が必要かもしれないですけれども、前回もやりましたけれども、ぜひそれは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-047"},{"speaker":"藤田委員","kind":"質問","question":"前回の委員会で、どなたかを呼んだということで、そこでのご意見というのはどういうふうに反映されているのか。私は委員じゃなかったんですが、聞いているわけですね。ですから、そうした意見というのを、ちょっと私たちもかいつまんでといいますか、ポイントだけでも、こういう意見がありましたというのを、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-048"},{"speaker":"三村委員","kind":"質問・要望","question":"私も、沢田委員と同じように、議員定数というだけで聞くと、とても意見が狭まってしまいますので、区民の方が、議員をどういうふうにとらえているか幅広く意見をくみ取れるような、もしアンケートをするんであれば、そういうような形でしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"ここは、行財政改革特別委員会で、定数を議論しているんで、ちょっと踏み出すと、議会全体の問題と絡んでくる。議会運営委員会のほうの範疇に入ったり、ここでそこまで踏み込んでアンケートをやるというのは行きすぎだと思いますので、それも、委員長にお任せしますけれども、あくまでも定数について議論をしようということですから、あまり踏み出さないほうがいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-050"},{"speaker":"沢田委員","kind":"意見","question":"私が言ったのは、やるべきだと言ったんじゃなくて、非常に難しいから、やり方については、慎重にしないと難しいんじゃないかという意味で言ったんです。私の真意はそういうことです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-051"},{"speaker":"中島委員","kind":"質問","question":"すごく単純な質問というか、先ほど、林委員も触れていましたが、江戸川区の場合は、６３万人に対して、１０人減らして４６名でやっている。この辺のところは、何か知ることができるのかどうか。難しい問題だとはわかっていますが。果たして、ここの少ない、特に千代田区なんて４万人ちょっとで、２５名いて、どういう役割をしていらっしゃるのかなというのが、とても気になったんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-052"},{"speaker":"武内委員","kind":"意見","question":"先ほど、林委員のほうから、江戸川区と杉並区というお話があったんですけれども、葛飾区が、今度、６名減る予定で、今年の１１月の区議会議員選挙のときに定数削減でやるということなんで、一番直近の例で、かなり大幅に減っているので、できれば葛飾区も、もしわかればお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問","question":"資料１の表の一番右側の適用年月日で、５月とあるんですよね。選挙は４月じゃないですか。そうすると、あの４月の選挙のときは適用されてない、適用できないと思うんですけれども、適用されているんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":56827,"voices":135}}]);
